insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('528', 'OTL', 'O-Ti-El', 'outdated-slang', NULL, '무릎 꿇고 좌절한 사람 모양의 옛날 이모티콘', '{"de": "Altes Text-Emoticon einer Person, die verzweifelt auf den Knien zusammenbricht", "en": "An old text emoticon of a person collapsed on their knees in despair", "es": "Antiguo emoticono de texto: una persona derrumbada de rodillas", "ja": "膝をついて崩れ落ちた人の形をした昔の顔文字", "vi": "Emoticon chữ cũ hình người quỳ gục vì thất vọng"}'::jsonb, '[오티엘]', '[{"type": "이모티콘", "examples": [{"de": "Nach drei Anläufen wieder durchgefallen … OTL", "es": "Suspendí otra vez tras tres intentos... OTL", "ja": "3浪目もダメだった…OTL", "vi": "Thi lần ba vẫn trượt... OTL", "eng": "Failed again after three tries... OTL", "kor": "3수 끝에 또 떨어졌다... OTL"}], "definition": "좌절과 절망을 나타내는 문자 이모티콘. O는 머리, T는 팔과 상체, L은 무릎 꿇은 다리를 본뜬 것으로 땅을 짚고 엎드린 사람 모습이다. 2000년대 중반 블로그와 커뮤니티에서 폭발적으로 쓰였고 지금은 거의 쓰이지 않는다.", "definition_i18n": {"de": "Ein Text-Emoticon für Verzweiflung: O ist der Kopf, T sind Arme und Oberkörper, L die knienden Beine — eine am Boden zusammengesackte Person. In den Blogs der Mitte-2000er überall, heute kaum noch benutzt.", "en": "A text emoticon for despair: O is the head, T the arms and torso, L the kneeling legs — a person slumped face-down on the ground. Everywhere on mid-2000s blogs and forums, barely used today.", "es": "Emoticono de texto para la desesperación: la O es la cabeza, la T los brazos y el torso, la L las piernas de rodillas — alguien derrumbado en el suelo. Omnipresente en los blogs de mediados de los 2000, hoy casi no se usa.", "ja": "挫折と絶望を表す文字の顔文字。Oは頭、Tは腕と上体、Lは膝をついた脚を表し、地面に手をついて崩れ落ちた人の姿。2000年代半ばのブログやコミュニティで大流行したが、今はほとんど使われない。", "vi": "Emoticon chữ diễn tả sự tuyệt vọng: O là đầu, T là tay và thân, L là chân quỳ — hình người gục xuống đất. Từng tràn ngập blog và diễn đàn giữa thập niên 2000, nay gần như không còn dùng."}}]'::jsonb, '일본 2ch 등에서 쓰이던 아스키아트 ○|￣|＿(한자로는 〇刀乙)에서 왔다는 설이 가장 널리 알려져 있다. 라틴 문자 O·T·L 세 글자만으로 같은 모양을 낼 수 있다는 점이 알려지며 2000년대 초중반 한국 블로그·커뮤니티로 빠르게 퍼졌다. 국내에 처음 퍼뜨린 사람에 대해서는 당시 한국에 살던 일본인 블로거라는 설 등 여러 설이 있고 확정되지 않았다.', '{"de": "Am verbreitetsten ist die Herleitung von der ASCII-Kunst ○|￣|＿ (auch 〇刀乙) aus japanischen Boards wie 2ch. Als auffiel, dass die drei lateinischen Buchstaben O·T·L dieselbe Form ergeben, verbreitete es sich Anfang bis Mitte der 2000er rasch über koreanische Blogs und Foren. Wer es zuerst nach Korea brachte, ist ungeklärt; eine Theorie nennt einen damals in Korea lebenden japanischen Blogger.", "en": "Most accounts trace it to the ASCII art ○|￣|＿ (also written 〇刀乙) used on Japanese boards such as 2ch. Once people noticed the three Latin letters O·T·L made the same shape, it spread fast through Korean blogs and forums in the early-to-mid 2000s. Who first brought it to Korea is unsettled — one theory names a Japanese blogger then living in Korea.", "es": "La versión más difundida lo remonta al arte ASCII ○|￣|＿ (también 〇刀乙) usado en foros japoneses como 2ch. Al descubrirse que las tres letras latinas O·T·L formaban la misma figura, se extendió rápido por blogs y foros coreanos a principios y mediados de los 2000. Quién lo introdujo en Corea no está confirmado; una teoría señala a un bloguero japonés residente allí.", "ja": "日本の2chなどで使われたAA ○|￣|＿(漢字では〇刀乙)に由来するという説が最も広く知られる。ラテン文字O・T・Lの三文字で同じ形になると分かり、2000年代前半から半ばに韓国のブログやコミュニティへ急速に広まった。国内への最初の伝播者については、当時韓国在住だった日本人ブロガー説など諸説あり未確定。", "vi": "Giả thuyết phổ biến nhất cho rằng nó bắt nguồn từ ASCII art ○|￣|＿ (còn viết 〇刀乙) trên các diễn đàn Nhật như 2ch. Khi mọi người nhận ra ba chữ Latin O·T·L tạo ra hình y hệt, nó lan nhanh qua blog và diễn đàn Hàn đầu đến giữa thập niên 2000. Ai đưa nó vào Hàn Quốc đầu tiên vẫn chưa rõ; một giả thuyết nhắc tới một blogger Nhật sống ở Hàn khi đó."}'::jsonb, '실패하거나 좌절한 순간에 문장 끝에 붙인다. 2000년대 블로그·게시판 세대의 표지 같은 말이라, 지금 쓰면 나이가 드러난다는 농담이 따라붙는다.', '{"de": "Wird bei einem Misserfolg ans Satzende gehängt. Es markiert die Blog- und Forengeneration der 2000er so deutlich, dass man heute damit Witze über sein Alter erntet.", "en": "Tacked onto the end of a sentence at a moment of failure. It marks the 2000s blog-and-forum generation so squarely that using it now invites jokes about your age.", "es": "Se añade al final de la frase en un momento de fracaso. Marca tanto a la generación de blogs y foros de los 2000 que usarlo hoy invita bromas sobre tu edad.", "ja": "失敗したり挫折した瞬間に文末へ付ける。2000年代のブログ・掲示板世代の目印のような言葉なので、今使うと年齢がばれると冗談を言われる。", "vi": "Gắn vào cuối câu lúc thất bại. Nó gắn chặt với thế hệ blog và diễn đàn thập niên 2000 đến mức dùng bây giờ sẽ bị trêu là lộ tuổi."}'::jsonb, array['안습', 'ㅠㅠ', '지못미']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "OTL (on-my-knees despair emoticon)"}, {"lang": "🇯🇵 JA", "text": "OTL(土下座・絶望の顔文字)"}, {"lang": "🇨🇳 ZH", "text": "OTL(跪地挫败颜文字)"}, {"lang": "🇻🇳 VI", "text": "OTL (emoticon quỳ gục thất vọng)"}, {"lang": "🇪🇸 ES", "text": "OTL (emoticono de derrota de rodillas)"}, {"lang": "🇩🇪 DE", "text": "OTL (Kniefall-Verzweiflungs-Emoticon)"}]'::jsonb),
('529', '간지', 'Gan-Ji', 'outdated-slang', 'beauty', '멋짐, 폼 — 간지 난다처럼 쓰는 일본어 유래 유행어', '{"de": "Stil, Schick — ein aus dem Japanischen stammendes Modewort, als gan-ji nan-da gebraucht", "en": "Style, swagger — a Japanese-derived buzzword used as gan-ji nan-da (that has style)", "es": "Estilo, garbo — palabra de origen japones usada como gan-ji nan-da (tiene estilo)", "ja": "かっこよさ・見栄え — 日本語由来で간지 난다のように使う流行語", "vi": "Chất, ngầu — từ gốc Nhật dùng kiểu gan-ji nan-da (trông chất đấy)"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Der Mantel hat echt Stil.", "es": "Ese abrigo tiene un estilo brutal.", "ja": "そのコート、マジでかっこいい。", "vi": "Cái áo khoác đó chất thật sự.", "eng": "That coat has serious style.", "kor": "그 코트 진짜 간지 난다."}, {"de": "Mein Onkel sagt immer noch Gan-ji. Ich sage einfach, es sieht gut aus.", "es": "Mi tio todavia dice gan-ji. Yo digo simplemente que queda bien.", "ja": "おじさんはいまだに간지って言う。私は普通にかっこいいって言う。", "vi": "Chú mình vẫn nói gan-ji. Mình thì chỉ nói là đẹp thôi.", "eng": "My uncle still says gan-ji. I just say it looks good.", "kor": "삼촌은 아직도 간지라고 하시더라. 나는 그냥 멋있다고 해."}], "definition": "멋지다, 세련됐다, 폼 난다는 뜻. 혼자 쓰기보다 간지 난다, 간지 폭발, 간지템처럼 붙여 쓴다. 일본어 간지(感じ)에서 왔지만 일본어에서는 그냥 느낌 인상이라는 뜻이라, 일본인에게 이 뜻으로 말하면 알아듣지 못한다.", "definition_i18n": {"de": "Cool, schick, stilvoll. Steht selten allein — meist als gan-ji nan-da (hat Stil), gan-ji pok-bal (Stilexplosion), gan-ji-tem (ein schickes Teil). Es stammt vom japanischen kanji, das lediglich Gefuehl oder Eindruck bedeutet, weshalb Japaner die koreanische Bedeutung nicht verstehen.", "en": "Cool, sharp, stylish. Rarely stands alone — it comes as gan-ji nan-da (has style), gan-ji pok-bal (style explosion), gan-ji-tem (a sharp-looking item). It comes from Japanese kanji, which merely means feel or impression, so a Japanese speaker will not understand the Korean sense.", "es": "Guay, elegante, con clase. Rara vez va solo: aparece como gan-ji nan-da (tiene estilo), gan-ji pok-bal (explosion de estilo), gan-ji-tem (prenda con estilo). Viene del japones kanji, que solo significa sensacion o impresion, asi que un japones no entendera el sentido coreano.", "ja": "かっこいい、洗練されている、決まっているという意味。単独より간지 난다、간지 폭발、간지템のように組み合わせて使う。日本語の感じから来ているが、日本語では単に感じ・印象の意味なので、日本人にこの意味で言っても通じない。", "vi": "Ngầu, sắc sảo, có gu. Hiếm khi đứng một mình — thường là gan-ji nan-da (trông chất), gan-ji pok-bal (chất nổ tung), gan-ji-tem (món đồ chất). Bắt nguồn từ tiếng Nhật kanji, vốn chỉ nghĩa là cảm giác, ấn tượng, nên người Nhật sẽ không hiểu nghĩa kiểu Hàn."}}]'::jsonb, '일본어 감じ(感じ, 느낌·인상)에서 온 말이다. 한국에서는 그 뜻이 좁아지고 세져서 멋짐 자체를 가리키게 됐고, 1990~2000년대 패션·힙합·디자인 쪽 말투로 자리 잡은 뒤 일반 유행어로 퍼졌다. 한국어 간지 난다를 다시 일본어로 옮기면 느낌을 내고 있다 정도가 되어 뜻이 통하지 않는다.', '{"de": "Vom japanischen kanji (感じ), Gefuehl oder Eindruck. Im Koreanischen verengte und verstaerkte sich die Bedeutung, bis sie Coolness selbst meinte; ueber Mode-, Hip-Hop- und Designsprache der 1990er und 2000er wurde sie allgemein. Uebersetzt man gan-ji nan-da zurueck ins Japanische, kommt so etwas wie gibt ein Gefuehl ab heraus — das passt nicht.", "en": "From Japanese kanji (感じ), meaning feel or impression. In Korean the sense narrowed and intensified until it meant coolness itself; it settled into fashion, hip-hop and design talk through the 1990s and 2000s before going mainstream. Translate gan-ji nan-da back into Japanese and you get something like giving off a feeling — which does not land.", "es": "Del japones kanji (感じ), sensacion o impresion. En coreano el sentido se estrecho y se intensifico hasta significar el atractivo mismo; se asento en el habla de la moda, el hip-hop y el diseño en los años 90 y 2000 antes de generalizarse. Si traduces gan-ji nan-da de vuelta al japones sale algo como esta dando una sensacion, que no funciona.", "ja": "日本語の感じ(印象・雰囲気)から来た語。韓国では意味が狭まり強まって、かっこよさそのものを指すようになり、1990-2000年代のファッション・ヒップホップ・デザイン界隈の言い回しとして定着した後、一般の流行語に広がった。간지 난다を日本語に戻すと感じを出しているくらいになり、意味が通じない。", "vi": "Từ tiếng Nhật kanji (感じ), nghĩa là cảm giác, ấn tượng. Sang tiếng Hàn nghĩa thu hẹp và mạnh lên thành chính cái chất ngầu; nó bám rễ trong giới thời trang, hip-hop, thiết kế suốt thập niên 1990-2000 rồi lan ra đại chúng. Dịch gan-ji nan-da ngược sang tiếng Nhật sẽ thành đang toát ra cảm giác — nghe không xuôi."}'::jsonb, '2000년대에 가장 흔했고 지금 10~20대는 잘 쓰지 않는다. 요즘은 같은 뜻으로 힙하다, 재질, 폼 미쳤다, 그냥 멋있다를 쓴다. 일본어 잔재라 국립국어원이 오래전부터 멋 폼으로 바꿔 쓰기를 권고해 온 말이기도 해서, 공적인 글이나 방송 자막에서는 피하는 편이다.', '{"de": "Hochzeit waren die 2000er; heutige Teenager und Twens greifen selten dazu und sagen eher hip-ha-da, jae-jil, pom mi-chyeot-da oder schlicht meot-it-da. Da es ein japanisches Lehnwort ist, empfiehlt das Nationale Institut der Koreanischen Sprache seit Langem meot oder pom, weshalb formelle Texte und TV-Untertitel es meiden.", "en": "Peak use was the 2000s; Koreans in their teens and twenties rarely reach for it now, preferring hip-ha-da, jae-jil, pom mi-chyeot-da, or plain meot-it-da. Because it is a Japanese loan, the National Institute of Korean Language has long recommended replacing it with the native meot or pom, so formal writing and broadcast subtitles tend to avoid it.", "es": "Su auge fueron los 2000; los coreanos de quince a veinticinco años rara vez lo usan hoy y prefieren hip-ha-da, jae-jil, pom mi-chyeot-da o simplemente meot-it-da. Al ser un prestamo japones, el Instituto Nacional de la Lengua Coreana lleva tiempo recomendando sustituirlo por meot o pom, asi que la escritura formal y los subtitulos televisivos suelen evitarlo.", "ja": "2000年代が全盛で、今の十代二十代はあまり使わず、ヒパダ、チェジル、フォームやばい、普通にかっこいいを使う。日本語の残滓であるため国立国語院が以前から멋・폼への言い換えを勧めており、公的な文章や放送字幕では避けられる傾向がある。", "vi": "Đỉnh cao là thập niên 2000; giới trẻ Hàn nay ít dùng, thay bằng hip-ha-da, jae-jil, pom mi-chyeot-da hoặc đơn giản là meot-it-da. Vì là từ mượn tiếng Nhật, Viện Quốc ngữ Hàn Quốc từ lâu khuyến nghị thay bằng meot hay pom, nên văn bản trang trọng và phụ đề truyền hình thường tránh."}'::jsonb, array['재질', '폼 미쳤다', '날티', '쌈뽕', '갓벽']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Style / swagger (looks sharp)"}, {"lang": "🇯🇵 JA", "text": "かっこよさ・見栄え(韓国的用法)"}, {"lang": "🇨🇳 ZH", "text": "帅气有型"}, {"lang": "🇻🇳 VI", "text": "Chất, ngầu, có gu"}, {"lang": "🇪🇸 ES", "text": "Estilo / garbo"}, {"lang": "🇩🇪 DE", "text": "Stil / Schick"}]'::jsonb),
('530', '갠춘', 'Gaen-chun', 'outdated-slang', NULL, '''괜찮다''를 굴려 적던 2000년대 인터넷 말투', '{"de": "Die 2000er-Netzsprech-Variante von 괜찮다 (ist okay)", "en": "The 2000s net-speak way of saying 괜찮다 (it is fine)", "es": "La forma internetera de los 2000 de decir 괜찮다 (está bien)", "ja": "「괜찮다(大丈夫)」を崩して書いた2000年代ネット語", "vi": "Cách viết kiểu mạng thập niên 2000 của 괜찮다 (ổn mà)"}'::jsonb, '[갠춘]', '[{"type": "형용사", "examples": [{"de": "So ist es doch gaen-chun, oder?", "es": "Así ya está gaen-chun, ¿no?", "ja": "これくらいならケンチュンじゃない?", "vi": "Vậy là gaen-chun rồi chứ nhỉ?", "eng": "This is gaen-chun enough, right?", "kor": "이 정도면 갠춘하지 않아?"}, {"de": "Der Preis ist gaen-chun und der Geschmack auch.", "es": "El precio está gaen-chun y el sabor también.", "ja": "値段もケンチュンで味もケンチュン", "vi": "Giá gaen-chun mà vị cũng gaen-chun.", "eng": "The price is gaen-chun and the taste is gaen-chun too.", "kor": "가격도 갠춘하고 맛도 갠춘해"}], "definition": "''괜찮다''를 모음을 굴려 ''갠춘하다''로 적은 말. 뜻은 괜찮다와 같지만 훨씬 가볍고 능청스러운 느낌이라, 진지한 ''괜찮아''와 달리 ''뭐 나쁘지 않네'' 정도의 온도다. ''갠춘해'', ''갠춘하다'', ''갠츈하다'' 꼴로 썼고 2000년대 중후반에 흔했다.", "definition_i18n": {"de": "괜찮다 (in Ordnung sein), mit verdrehten Vokalen als 갠춘하다 geschrieben. Gleiche Bedeutung, viel leichterer, frecherer Ton — wo 괜찮아 ernst sein kann, ist 갠춘해 eher ''och, nicht schlecht''. Vorkommen als 갠춘해, 갠춘하다, 갠츈하다; verbreitet Mitte bis Ende der 2000er.", "en": "괜찮다 (to be fine) respelled with rolled vowels as 갠춘하다. Same meaning, much lighter and cheekier tone — where 괜찮아 can be sincere, 갠춘해 is more like ''eh, not bad''. Appeared as 갠춘해, 갠춘하다, 갠츈하다 and was common in the mid-to-late 2000s.", "es": "괜찮다 (estar bien) reescrito con vocales retorcidas como 갠춘하다. Mismo significado, tono mucho más ligero y descarado: si 괜찮아 puede ser sincero, 갠춘해 es más un ''bah, no está mal''. Se usaba como 갠춘해, 갠춘하다, 갠츈하다 y fue común a mediados y finales de los 2000.", "ja": "「괜찮다(大丈夫だ)」を母音を崩して「갠춘하다」と書いた語。意味は同じだが、ずっと軽くとぼけた響きで、真剣な「괜찮아」と違い「まあ悪くないね」くらいの温度。「갠춘해」「갠춘하다」「갠츈하다」の形で2000年代中後期に多用された。", "vi": "괜찮다 (ổn) viết lại với nguyên âm bị bóp thành 갠춘하다. Nghĩa giống nhưng giọng nhẹ và tếu hơn nhiều — 괜찮아 có thể chân thành, còn 갠춘해 kiểu ''ừ, cũng không tệ''. Xuất hiện dưới dạng 갠춘해, 갠춘하다, 갠츈하다, phổ biến giữa và cuối thập niên 2000."}}]'::jsonb, '유래에 두 가지 설이 있고 확정되지 않았다. 하나는 방언의 ''괜차네''에서 ''괜춘해''를 거쳐 ''갠춘해''로 굳었다는 설, 다른 하나는 방언과 무관하게 2000년대 인터넷에서 유행한 ''외계어''(모음과 자음을 일부러 낯설게 바꿔 적는 놀이)의 한 갈래로 자연히 퍼졌다는 설이다. 어느 쪽도 문헌으로 확인되지 않았다.', '{"de": "Zwei konkurrierende Versionen, keine bestätigt. Eine führt es über den Dialekt: 괜차네 zu 괜춘해 zu 갠춘해. Die andere sagt, der Dialekt habe nichts damit zu tun, und ordnet es der 2000er-외계어-Mode zu, Vokale und Konsonanten online absichtlich zu verzerren. Kein Dokument entscheidet die Frage.", "en": "Two competing accounts, neither confirmed. One traces it through dialect: 괜차네 to 괜춘해 to 갠춘해. The other says dialect has nothing to do with it and places it in the 2000s 외계어 fad of deliberately mangling vowels and consonants online. No documentary evidence settles it.", "es": "Dos versiones en competencia, ninguna confirmada. Una lo rastrea por el dialecto: 괜차네, 괜춘해, 갠춘해. La otra dice que el dialecto no tiene nada que ver y lo sitúa en la moda 외계어 de los 2000 de retorcer vocales y consonantes en línea. Ningún documento lo resuelve.", "ja": "説が二つあり未確定。一つは方言の「괜차네」から「괜춘해」を経て「갠춘해」に定着したという説。もう一つは方言とは無関係に、2000年代ネットの「外界語」(母音・子音をわざと崩す遊び)の一種として広まったという説。いずれも文献では裏付けられていない。", "vi": "Hai thuyết cạnh tranh, chưa thuyết nào được xác nhận. Một thuyết truy theo phương ngữ: 괜차네 sang 괜춘해 sang 갠춘해. Thuyết kia nói phương ngữ không liên quan và xếp nó vào trào lưu 외계어 thập niên 2000 — cố tình bóp méo nguyên âm phụ âm trên mạng. Không có tài liệu nào phân định."}'::jsonb, '지금 쓰면 2000년대 인터넷 말투를 흉내는 것으로 읽힌다. 당시에도 ''왜 저렇게 쓰느냐''는 반응이 있어 호오가 갈렸던 표기이므로, 배우더라도 읽기용으로만 두는 게 안전하다. 요즘은 그냥 ''괜찮다''거나, 더 가벼우면 ''나쁘지 않다'', ''갠찮''처럼 줄여 쓴다.', '{"de": "Heute klingt es wie eine Imitation des 2000er-Netzsprechs. Schon damals beschwerten sich viele über die Schreibweise, sie war umstritten — am sichersten nur zum Lesen behalten. Heute sagt man einfach 괜찮다 oder 나쁘지 않다 für die leichtere Note.", "en": "Using it today reads as impersonating 2000s net-speak. Even back then plenty of people complained about the spelling, so it was divisive — safest to keep it as a reading-only word. Nowadays people just say 괜찮다, or 나쁘지 않다 for the lighter shade.", "es": "Usarlo hoy suena a imitación del internet de los 2000. Ya entonces mucha gente se quejaba de esa grafía, así que dividía opiniones: mejor guardarlo solo para leer. Hoy se dice 괜찮다 sin más, o 나쁘지 않다 para el matiz ligero.", "ja": "今使うと2000年代ネット語の真似として読まれる。当時も「なぜそう書くのか」という反発があり好き嫌いが分かれた表記なので、覚えるとしても読む用にとどめるのが安全。今は普通に「괜찮다」、軽く言うなら「나쁘지 않다」。", "vi": "Dùng hôm nay nghe như bắt chước tiếng mạng thập niên 2000. Ngay thời đó nhiều người đã phàn nàn về cách viết này nên nó gây chia rẽ — an toàn nhất là chỉ để đọc. Nay người ta nói 괜찮다, hoặc 나쁘지 않다 cho sắc thái nhẹ."}'::jsonb, array['대박', '레알', '방가방가']::text[], array['갠츈', '괜춘']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "It is fine / not bad (2000s net-speak)"}, {"lang": "🇯🇵 JA", "text": "大丈夫・悪くない(2000年代ネット語)"}, {"lang": "🇨🇳 ZH", "text": "还行、不错(2000年代网络用语)"}, {"lang": "🇻🇳 VI", "text": "Ổn mà / không tệ (tiếng mạng 2000s)"}, {"lang": "🇪🇸 ES", "text": "Está bien / no está mal (jerga net 2000)"}, {"lang": "🇩🇪 DE", "text": "Ist okay / nicht schlecht (2000er-Netzsprech)"}]'::jsonb),
('531', '냉무', 'Naeng-mu', 'outdated-slang', NULL, '''내용 없음'' — 제목이 곧 글 전부라는 표시', '{"de": "''Kein Inhalt'' — das Kürzel, dass der Titel schon der ganze Beitrag ist", "en": "''No body text'' — the tag meaning the title is the whole post", "es": "''Sin contenido'': la etiqueta que avisa que el título es todo el mensaje", "ja": "「本文なし」——タイトルが記事の全部という印", "vi": "''Không có nội dung'' — nhãn báo tiêu đề chính là toàn bộ bài"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Um wie viel Uhr ist das Treffen morgen? (kein Inhalt)", "es": "¿A qué hora es la quedada de mañana? (sin contenido)", "ja": "明日の集まり何時ですか?(本文なし)", "vi": "Mai họp mấy giờ vậy? (không có nội dung)", "eng": "What time is the meetup tomorrow? (no body text)", "kor": "내일 모임 몇 시예요? (냉무)"}, {"de": "Ein Forum, das noch 냉무 benutzt, fühlt sich an wie ein altes Schwarzes Brett.", "es": "Ver un foro que todavía usa 냉무 es como entrar en un tablón antiguo.", "ja": "まだ냉무を使ってるカフェを見ると本当に昔の掲示板みたい", "vi": "Thấy diễn đàn nào còn dùng 냉무 là y như lạc về bảng tin ngày xưa", "eng": "Seeing a forum still using 냉무 feels like stepping into an old message board.", "kor": "냉무 아직도 쓰는 카페 보면 진짜 옛날 게시판 같아"}], "definition": "''내용 없음''에서 ''없음''을 한자 무(無)로 바꾸고 ''내용''을 ''냉''으로 줄인 말. 게시판에 짧은 질문이나 한마디를 올릴 때 제목에 할 말을 다 쓰고 본문은 비워 둔 뒤, 제목 끝에 ''(냉무)''를 붙여 ''클릭해도 아무것도 없다''고 미리 알려 주던 표시다.", "definition_i18n": {"de": "Von 내용 없음 (kein Inhalt): 없음 wird durch das sinokoreanische 무 (無) ersetzt, 내용 auf 냉 gekürzt. Wer eine einzeilige Frage ins Forum stellte, schrieb alles in den Titel, ließ den Text leer und hängte (냉무) an, um zu warnen, dass drinnen nichts wartet.", "en": "From 내용 없음 (no content): 없음 swapped for the Sino-Korean 무 (無) and 내용 clipped to 냉. When you posted a one-line question on a message board, you wrote the whole thing in the title, left the body empty, and appended (냉무) to warn readers there was nothing inside to click for.", "es": "De 내용 없음 (sin contenido): 없음 se cambia por el sinocoreano 무 (無) y 내용 se recorta a 냉. Al publicar una pregunta de una línea en un foro, escribías todo en el título, dejabas el cuerpo vacío y añadías (냉무) para avisar de que no había nada dentro.", "ja": "「내용 없음(内容なし)」の「없음」を漢字の無に置き換え、「내용」を「냉」に縮めた語。掲示板に一言だけ書くとき、言いたいことをすべてタイトルに入れ本文は空にし、タイトル末に「(냉무)」を付けて「開いても何もない」と予告した。", "vi": "Từ 내용 없음 (không có nội dung): 없음 đổi thành chữ Hán 무 (無) và 내용 rút thành 냉. Khi đăng một câu hỏi ngắn lên diễn đàn, bạn viết hết vào tiêu đề, để trống phần thân, rồi thêm (냉무) để báo trước là bấm vào cũng chẳng có gì."}}]'::jsonb, '''내용 없음 → 내용 無 → 냉무'' 순으로 줄어든 통신 언어다. 처음 쓰인 것은 1990년대 후반으로 보이며 2000년대 초중반 게시판에서 크게 유행했다. 이후 어감이 비슷한 ''제곧내''(제목이 곧 내용)가 등장해 자리를 대신했는데, 냉무는 제목에 붙이고 제곧내는 본문에 쓴다는 차이가 있다. 본문 입력을 강제하지 않는 옛 게시판 구조에서만 성립하는 말이라, 게시판 자체가 줄어들면서 함께 사라졌다.', '{"de": "Eine Netzsprach-Kürzung: 내용 없음 → 내용 無 → 냉무. Erstbeleg Ende der 1990er, Höhepunkt auf Foren Anfang bis Mitte der 2000er. Später verdrängt vom ähnlich klingenden 제곧내 (der Titel IST der Inhalt) — Unterschied: 냉무 steht im Titel, 제곧내 im Text. Das Wort ergibt nur auf alten Boards Sinn, die keinen Fließtext verlangten, und verschwand mit ihnen.", "en": "A net-speak contraction: 내용 없음 → 내용 無 → 냉무. First attested in the late 1990s, it peaked on message boards in the early-to-mid 2000s. It was later displaced by the similar-sounding 제곧내 (the title IS the content) — the difference being that 냉무 goes in the title while 제곧내 goes in the body. The word only makes sense on old boards that did not require body text, so it vanished as those boards did.", "es": "Contracción de argot de red: 내용 없음 → 내용 無 → 냉무. Atestiguada por primera vez a finales de los 90, tuvo su auge en los foros de principios y mediados de los 2000. Luego la desplazó el parecido 제곧내 (el título ES el contenido); la diferencia es que 냉무 va en el título y 제곧내 en el cuerpo. Solo funciona en foros antiguos que no exigían texto, así que desapareció con ellos.", "ja": "「내용 없음 → 내용 無 → 냉무」と縮んだ通信言語。初出は90年代後半とされ、2000年代初中盤の掲示板で大流行した。その後、語感の似た「제곧내(タイトルがすなわち内容)」に取って代わられた。냉무はタイトルに、제곧내は本文に付けるという違いがある。本文入力を強制しない旧式掲示板でのみ成り立つ語なので、掲示板文化の衰退とともに消えた。", "vi": "Một dạng rút gọn của tiếng mạng: 내용 없음 → 내용 無 → 냉무. Xuất hiện lần đầu cuối thập niên 1990, thịnh nhất trên diễn đàn đầu-giữa thập niên 2000. Sau đó bị 제곧내 (tiêu đề chính là nội dung) thay thế; khác nhau ở chỗ 냉무 đặt ở tiêu đề còn 제곧내 đặt ở phần thân. Từ này chỉ hợp lý trên diễn đàn cũ không bắt buộc nhập nội dung, nên biến mất cùng chúng."}'::jsonb, '제목 맨 끝에 괄호로 ''(냉무)'' 또는 ''- 냉무''를 붙이는 게 정석이었다. 채팅과 메신저로 대화가 옮겨 간 지금은 거의 볼 수 없고, 같은 뜻으로는 ''제곧내''가 쓰인다.', '{"de": "Standard war ''(냉무)'' oder ''- 냉무'' ganz am Titelende. Seit Gespräche in Chat-Apps stattfinden, sieht man es kaum noch; 제곧내 deckt dieselbe Idee ab.", "en": "Standard form was ''(냉무)'' or ''- 냉무'' at the very end of the title. Now that conversation has moved to chat apps it is almost never seen; 제곧내 covers the same idea.", "es": "La forma estándar era ''(냉무)'' o ''- 냉무'' al final del título. Ahora que la conversación se mudó al chat casi no se ve; 제곧내 cubre la misma idea.", "ja": "タイトル末尾に括弧で「(냉무)」または「- 냉무」を付けるのが定番だった。会話がチャットに移った今はほぼ見かけず、同じ意味では「제곧내」が使われる。", "vi": "Dạng chuẩn là ''(냉무)'' hoặc ''- 냉무'' ở cuối tiêu đề. Nay khi trò chuyện chuyển sang ứng dụng chat thì gần như không còn thấy; 제곧내 mang cùng ý."}'::jsonb, array['짤', '즐']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "n/t — no text (title is the whole post)"}, {"lang": "🇯🇵 JA", "text": "本文なし(タイトルが全部)"}, {"lang": "🇨🇳 ZH", "text": "无内容(标题即正文)"}, {"lang": "🇻🇳 VI", "text": "Không có nội dung (tiêu đề là tất cả)"}, {"lang": "🇪🇸 ES", "text": "Sin contenido (el título es todo)"}, {"lang": "🇩🇪 DE", "text": "Kein Text (Titel ist der ganze Beitrag)"}]'::jsonb),
('532', '깜놀', 'Kkam-nol', 'outdated-slang', NULL, '깜짝 놀랐다는 뜻의 2000년대 줄임말', '{"de": "2000er-Kurzform für erschrocken", "en": "2000s shorthand for being startled", "es": "Abreviatura de los 2000 para susto", "ja": "「びっくりした」の2000年代式略語", "vi": "Từ tắt thập niên 2000 cho giật mình"}'::jsonb, NULL, '[{"type": "명사·동사(깜놀하다)", "examples": [{"de": "Du hast mich von hinten gerufen — ich bin voll zusammengezuckt.", "es": "Me llamaste de repente por detrás, ¡menudo susto!", "ja": "後ろから急に呼ぶからびっくりしたじゃん。", "vi": "Tự dưng gọi từ phía sau, làm tớ giật cả mình.", "eng": "You called me from behind out of nowhere — I totally jumped.", "kor": "뒤에서 갑자기 불러서 깜놀했잖아."}], "definition": "「깜짝 놀라다」를 두 글자로 줄인 말. 정말 무서운 일보다는 예상 못 한 일에 가볍게 놀랐을 때 쓴다. 「깜놀했어」처럼 하다를 붙여 동사로 쓰는 것이 보통이다.", "definition_i18n": {"de": "Zweisilbige Kurzform von 깜짝 놀라다 (erschrecken). Für kleine, harmlose Überraschungen, nicht für echte Angst; meist mit 하다: 깜놀했어 (ich bin zusammengezuckt).", "en": "A two-syllable clip of 깜짝 놀라다 (to be startled). Used for small, harmless surprises rather than real fright, normally with 하다: 깜놀했어 (I jumped).", "es": "Recorte de dos sílabas de 깜짝 놀라다 (asustarse). Para sustos leves e inofensivos, no para miedo real; normalmente con 하다: 깜놀했어 (me dio un susto).", "ja": "「깜짝 놀라다(びっくりする)」を2文字に縮めた語。本当に怖い場面より、予想外の出来事に軽く驚いたときに使う。普通は하다を付けて「깜놀했어」と動詞で使う。", "vi": "Rút gọn hai âm tiết của 깜짝 놀라다 (giật mình). Dùng cho bất ngờ nhẹ, không phải sợ thật; thường thêm 하다: 깜놀했어 (tớ giật cả mình)."}}]'::jsonb, '2000년대 초 채팅과 문자 메시지에서 글자 수를 줄이려고 만들어진 두 글자 줄임말 가운데 하나. 당시에는 「한글 파괴」라는 비판을 크게 받았지만 규제로 사라진 것이 아니라 유행이 지나면서 자연히 도태됐다.', '{"de": "Eine der zweisilbigen Kurzformen aus Chatrooms und SMS der frühen 2000er, als jedes Zeichen zählte. Damals als Hangul-Zerstörung gescholten, verschwand es aber von selbst mit der Mode, nicht durch Verbote.", "en": "One of the two-syllable clips born in early-2000s chat rooms and SMS, where every character counted. It drew heavy criticism at the time as hangul-wrecking, but it died out on its own as the fashion passed rather than through any crackdown.", "es": "Uno de los recortes de dos sílabas nacidos en los chats y SMS de principios de los 2000, cuando cada carácter contaba. Se le criticó mucho por destrozar el hangul, pero murió sola al pasar la moda, no por ninguna prohibición.", "ja": "2000年代初頭のチャットや携帯メールで文字数を削るために生まれた2文字略語の一つ。当時は「ハングル破壊」と強く批判されたが、規制で消えたのではなく流行が去って自然に廃れた。", "vi": "Một trong những từ tắt hai âm tiết sinh ra ở phòng chat và tin nhắn đầu những năm 2000, khi từng ký tự đều quý. Thời đó bị chê là phá hoại hangul, nhưng nó tự lụi tàn khi hết mốt chứ không vì lệnh cấm nào."}'::jsonb, '지금 10~20대는 「깜짝이야」나 초성 감탄사 「ㄴㅇㄱ」을 쓴다. 깜놀은 뜻이 바로 통하긴 하지만 30대 이상이 쓰면 나이대가 드러나는 말이 됐다.', '{"de": "Junge Leute sagen heute 깜짝이야 oder das reine Konsonantenkürzel ㄴㅇㄱ. 깜놀 versteht jeder, verrät aber, dass man über dreißig ist.", "en": "Young speakers today say 깜짝이야 or the consonant-only ㄴㅇㄱ instead. 깜놀 is still perfectly understandable, but using it now quietly gives away that you are over thirty.", "es": "Los jóvenes de hoy dicen 깜짝이야 o el ㄴㅇㄱ de solo consonantes. 깜놀 se entiende sin problema, pero usarlo delata que pasas de los treinta.", "ja": "今の10〜20代は「깜짝이야」や子音だけの「ㄴㅇㄱ」を使う。깜놀は意味は通じるが、使うと30代以上だと年代がばれる語になった。", "vi": "Giới trẻ giờ nói 깜짝이야 hoặc ㄴㅇㄱ chỉ gồm phụ âm. 깜놀 vẫn hiểu được, nhưng dùng nó là lộ ngay bạn đã ngoài ba mươi."}'::jsonb, array['ㄴㅇㄱ', '소름', '심쿵']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Startled / jump scare"}, {"lang": "🇯🇵 JA", "text": "びっくり(略語)"}, {"lang": "🇨🇳 ZH", "text": "吓一跳(缩略语)"}, {"lang": "🇻🇳 VI", "text": "Giật mình (từ tắt)"}, {"lang": "🇪🇸 ES", "text": "Susto (abreviado)"}, {"lang": "🇩🇪 DE", "text": "Erschrocken (Kurzform)"}]'::jsonb),
('533', '넌씨눈', 'Neon-ssi-nun', 'slang', 'outdated-slang', '분위기를 못 읽는 사람에게 쏘아붙인 2010년대 초 욕설 줄임말', '{"de": "Eine vulgäre Abkürzung der frühen 2010er für jemanden, der die Stimmung nicht liest", "en": "An early-2010s profane jab at someone who cannot read the room", "es": "Un insulto abreviado de principios de los 2010 para quien no sabe leer el ambiente", "ja": "空気を読めない人に浴びせた2010年代初めの罵り略語", "vi": "Từ tục viết tắt đầu thập niên 2010 mắng người không biết đọc không khí"}'::jsonb, '[넌씨눈]', '[{"type": "명사", "examples": [{"de": "Du bringst das jetzt auf? Du bist echt ein Neon-ssi-nun.", "es": "¿Sacas ese tema ahora? Eres un neon-ssi-nun de verdad.", "ja": "今その話する? まじでノンシヌンだわ。", "vi": "Giờ mà mày nói chuyện đó à? Neon-ssi-nun thật sự.", "eng": "You are bringing that up now? You are such a neon-ssi-nun.", "kor": "지금 그 얘기를 하냐? 넌씨눈이야 진짜."}, {"de": "Neon-ssi-nun ist recht hart — heute sagt man 눈새.", "es": "Neon-ssi-nun es bastante fuerte; hoy se dice 눈새.", "ja": "ノンシヌンはちょっと強い言葉。今は눈새って言う。", "vi": "Neon-ssi-nun hơi nặng đó, giờ người ta nói 눈새.", "eng": "Neon-ssi-nun is pretty harsh — these days people say 눈새.", "kor": "넌씨눈은 좀 센 말이야, 요즘은 눈새라고 해."}], "definition": "''넌 씨× 눈치도 없냐''를 앞글자만 따 줄인 말. 대화의 분위기를 전혀 못 읽고 하지 말아야 할 말을 꺼내는 사람을 거칠게 비난할 때 썼다. ''씨''가 욕설의 첫 음절이라 순한 말이 아니며, 웃으며 던지는 놀림보다 실제로 짜증이 난 상황에서 나왔다. 2010년대 초에 흔했고 지금은 같은 뜻으로 ''눈새''를 더 쓴다.", "definition_i18n": {"de": "Ein Akronym von 넌 씨× 눈치도 없냐, etwa ''hast du null Gespür für die Situation, du ...''. Man warf es jemandem entgegen, der die Stimmung eines Gesprächs völlig verfehlt und genau das Falsche sagt. Das 씨 ist die erste Silbe eines Schimpfworts, also ist es nicht höflich; es kam aus echtem Ärger, nicht aus freundlichem Neckern. Verbreitet in den frühen 2010ern; heute greift man zu 눈새.", "en": "An acronym of 넌 씨× 눈치도 없냐 — roughly ''do you have zero read on the room, you ...''. It was thrown at someone who completely misses the mood of a conversation and says the one thing they should not. The 씨 is the first syllable of a swear word, so this is not polite; it came out of genuine irritation rather than friendly teasing. Common in the early 2010s; today people reach for 눈새 instead.", "es": "Acrónimo de 넌 씨× 눈치도 없냐, algo así como ''¿no tienes ni idea de leer el ambiente, ...?''. Se lanzaba a quien no capta en absoluto el tono de una conversación y suelta justo lo que no debía. La 씨 es la primera sílaba de una palabrota, así que no es fino; salía del enfado real, no de la broma amistosa. Común a principios de los 2010; hoy se dice 눈새.", "ja": "「넌 씨× 눈치도 없냐(お前、空気も読めないのか)」の頭文字を取った略語。会話の空気をまるで読めず、言ってはいけないことを口にする人を荒く非難するときに使った。「씨」は罵倒語の頭文字なので上品な語ではなく、笑いながらのいじりではなく本当にイラついた場面で出た。2010年代初めに多用され、今は同じ意味で「눈새」を使う。", "vi": "Viết tắt của 넌 씨× 눈치도 없냐 — đại ý ''mày không biết đọc không khí gì à''. Nó được ném vào người hoàn toàn không nắm được không khí cuộc trò chuyện và nói đúng điều không nên. Chữ 씨 là âm đầu của một từ tục nên đây không phải lời lịch sự; nó bật ra từ sự bực thật, không phải trêu vui. Phổ biến đầu thập niên 2010; nay người ta dùng 눈새."}}]'::jsonb, '정확한 유래는 알려지지 않았다. 출처들은 공통적으로 2010년대 초반 인터넷 커뮤니티에서 쓰이기 시작한 것으로 추정한다고만 밝히고, 최초 게시물이나 발생 커뮤니티를 특정하지 못한다. 앞글자만 따는 줄임말 방식은 같은 시기 ''답정너''(답은 정해져 있고 너는 대답만 하면 돼)와 짝을 이루어 자주 언급되는데, 답정너가 질문하는 쪽을 비꼰다면 넌씨눈은 대답하는 쪽을 쏘아붙이는 말이다.', '{"de": "Die genaue Herkunft ist unbekannt. Die Quellen sind sich nur einig, dass es vermutlich Anfang der 2010er in Internet-Communities aufkam; keine kann einen ersten Beitrag oder ein Ursprungsforum nennen. Der Initialen-Abkürzungsstil wird oft zusammen mit 답정너 aus derselben Zeit besprochen: Während 답정너 die fragende Seite verspottet, fährt 넌씨눈 die antwortende Seite an.", "en": "The precise origin is unknown. Sources agree only that it is presumed to have started on internet communities in the early 2010s; none can point to a first post or a founding board. Its initial-letter abbreviation style is often discussed alongside 답정너 from the same period: where 답정너 mocks the person asking, 넌씨눈 snaps at the person answering.", "es": "El origen exacto se desconoce. Las fuentes solo coinciden en suponer que empezó en comunidades de internet a principios de los 2010; ninguna señala una primera publicación ni un foro fundador. Su estilo de sigla se comenta a menudo junto a 답정너 de la misma época: si 답정너 se burla de quien pregunta, 넌씨눈 le salta a quien responde.", "ja": "正確な由来は不明。各出処は2010年代初めのネットコミュニティで使われ始めたと推定するとだけ述べ、最初の投稿や発生コミュニティを特定できていない。頭文字を取る略語法は同時期の「답정너」とセットで語られることが多く、답정너が質問する側を皮肉るなら、넌씨눈は答える側に食ってかかる語である。", "vi": "Nguồn gốc chính xác không rõ. Các nguồn chỉ đồng ý rằng nó được cho là bắt đầu trên các cộng đồng mạng đầu thập niên 2010; không nguồn nào chỉ ra bài đăng đầu tiên hay diễn đàn khởi phát. Kiểu viết tắt lấy âm đầu thường được bàn cùng 답정너 cùng thời: nếu 답정너 châm người hỏi thì 넌씨눈 quát người trả lời."}'::jsonb, '욕설이 든 거친 말이므로 외국인 학습자는 뜻만 알아두고 입으로 쓰지 않는 게 안전하다. 요즘 한국에서는 같은 뜻으로 ''눈새''(눈치 없는 사람)를 더 쓰고, 넌씨눈은 2010년대 초 커뮤니티 글에서 주로 보인다. 자기 자신에게 ''나 넌씨눈이었네''처럼 쓰면 자책하는 농담이 되어 조금 부드러워진다.', '{"de": "Es enthält ein Schimpfwort, Lernende sollten die Bedeutung kennen und es nie sagen. In Korea trägt heute 눈새 (jemand ohne soziales Radar) dieselbe Idee, und 넌씨눈 findet sich vor allem in Forenbeiträgen der frühen 2010er. Auf sich selbst bezogen — 나 넌씨눈이었네 — wird es zu selbstironischem Humor und damit milder.", "en": "It contains a swear word, so learners are safest knowing the meaning and never saying it. In Korea today the same idea is carried by 눈새 (a person with no social radar), and 넌씨눈 mostly turns up in early-2010s forum posts. Aimed at yourself — 나 넌씨눈이었네 — it softens into self-deprecating humour.", "es": "Contiene una palabrota, así que a un estudiante le conviene conocer el significado y no decirlo nunca. En Corea hoy la misma idea la lleva 눈새 (alguien sin radar social), y 넌씨눈 aparece sobre todo en foros de principios de los 2010. Dirigido a uno mismo — 나 넌씨눈이었네 — se suaviza y pasa a ser humor autocrítico.", "ja": "罵倒語を含む荒い語なので、学習者は意味だけ知って口にしないのが安全。今の韓国では同じ意味を「눈새」(空気が読めない人)が担い、넌씨눈は2010年代初めの掲示板の書き込みに主に現れる。自分に向けて「나 넌씨눈이었네」と言えば自虐的な冗談になり少し和らぐ。", "vi": "Nó chứa từ tục, nên người học an toàn nhất là biết nghĩa mà không nói. Ở Hàn Quốc nay ý đó do 눈새 (người không có radar xã hội) đảm nhiệm, còn 넌씨눈 chủ yếu gặp trong bài diễn đàn đầu thập niên 2010. Nhắm vào chính mình — 나 넌씨눈이었네 — thì nó dịu lại thành câu tự trêu."}'::jsonb, array['답정너', '진지충', '씹선비']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Can you not read the room?! (crude, 2010s)"}, {"lang": "🇯🇵 JA", "text": "空気読めないのか(粗い言い方、2010年代)"}, {"lang": "🇨🇳 ZH", "text": "你一点眼力都没有吗(粗话，2010年代)"}, {"lang": "🇻🇳 VI", "text": "Không biết đọc không khí à (thô, 2010s)"}, {"lang": "🇪🇸 ES", "text": "¿No sabes leer el ambiente? (grosero, 2010)"}, {"lang": "🇩🇪 DE", "text": "Kannst du die Stimmung nicht lesen?! (vulgär, 2010er)"}]'::jsonb),
('534', '낚시', 'Nak-si', 'outdated-slang', NULL, '그럴듯한 제목으로 사람을 속이는 글', '{"de": "Ein Köder-Post mit irreführendem Titel", "en": "A bait post — a misleading title that tricks you into clicking", "es": "Un post cebo con título engañoso", "ja": "それらしい題名で人を釣る書き込み", "vi": "Bài câu view với tiêu đề lừa người đọc"}'::jsonb, '[낙씨]', '[{"type": "명사", "examples": [{"de": "Wegen des Titels geklickt — und voll reingefallen.", "es": "Entré por el titular y he picado del todo.", "ja": "題名につられて開いたら完全に釣られたわ。", "vi": "Thấy tiêu đề nên bấm vào, ai ngờ bị câu hoàn toàn.", "eng": "I clicked because of the title and got completely baited.", "kor": "제목 보고 들어왔는데 완전 낚였네."}], "definition": "제목이나 첫머리를 그럴듯하게 써서 사람들이 눌러 보게 만든 뒤 전혀 엉뚱한 내용을 보여 주는 일. 속은 쪽은 「낚였다」, 속인 쪽은 「낚았다」고 하고, 속이는 데 쓴 미끼 같은 내용은 그대로 「미끼」라고 부른다.", "definition_i18n": {"de": "Eine plausible Überschrift schreiben, damit Leute klicken, und ihnen dann etwas völlig anderes zeigen. Wer reinfällt, sagt 낚였다 (ich bin drauf reingefallen), wer es aufsetzt 낚았다 (ich hab sie an der Angel), und der Köder heißt schlicht 미끼.", "en": "Writing a plausible headline or opening so people click, then serving them something completely unrelated. The victim says 낚였다 (I got hooked), the author 낚았다 (I reeled them in), and the lure itself is called 미끼 (bait).", "es": "Poner un titular creíble para que la gente entre y luego mostrarle algo que no tiene nada que ver. Quien cae dice 낚였다 (he picado), quien lo monta 낚았다 (lo he pescado), y el anzuelo se llama 미끼 (cebo).", "ja": "それらしい題名や書き出しでクリックさせ、まったく別の中身を見せること。引っかかった側は「낚였다(釣られた)」、仕掛けた側は「낚았다(釣った)」と言い、釣るのに使った内容はそのまま「미끼(餌)」と呼ぶ。", "vi": "Đặt tiêu đề hay câu mở nghe có lý để người ta bấm vào, rồi cho xem thứ hoàn toàn khác. Người mắc bẫy nói 낚였다 (bị câu rồi), người giăng bẫy nói 낚았다 (câu được rồi), còn mồi nhử gọi thẳng là 미끼."}}]'::jsonb, '물고기를 낚듯 사람을 걸어 올린다는 비유에서 나왔다. 2000년대 초 커뮤니티에서, 그럴듯한 제목의 글을 눌러 보면 만화 한 컷과 「걸렸다」는 짧은 글만 나오는 장난이 퍼지면서 시작됐고, 낚인 것을 알리려고 실제 낚시꾼 사진을 붙이는 관습도 이때 함께 생겼다.', '{"de": "Vom Bild, einen Menschen zu angeln wie einen Fisch. Es begann in Communities der frühen 2000er mit einem Scherzformat: eine vielversprechende Überschrift, dahinter nur ein Comicpanel und der Satz reingefallen. Auch der Brauch, ein Foto eines echten Anglers anzuhängen, stammt von dort.", "en": "From the image of hooking a person the way you hook a fish. It began in early-2000s communities with a prank format: a promising headline that opened onto a single cartoon panel and the words you got caught. The habit of pasting a photo of a real angler to signal the catch dates from the same moment.", "es": "De la imagen de pescar a una persona como se pesca un pez. Nació en los foros de comienzos de los 2000 con una broma: un titular prometedor que abría a una sola viñeta y la frase has picado. La costumbre de pegar la foto de un pescador real para anunciar la captura viene de entonces.", "ja": "魚を釣るように人を引っかけるという比喩から。2000年代初頭のコミュニティで、それらしい題名の記事を開くと漫画一コマと「引っかかった」という短文だけが出るいたずらが広まったのが始まりで、釣られたことを示すため実際の釣り人の写真を貼る習慣もこのとき生まれた。", "vi": "Từ hình ảnh câu người như câu cá. Bắt đầu ở các diễn đàn đầu những năm 2000 với trò đùa: tiêu đề hấp dẫn nhưng mở ra chỉ có một khung truyện tranh và dòng chữ dính rồi nhé. Thói quen dán ảnh người câu cá thật để báo đã câu được cũng ra đời từ lúc đó."}'::jsonb, '커뮤니티들이 규정으로 강하게 막고 이용자들도 대놓고 불쾌해하면서, 장난으로서의 낚시글 문화는 거의 사라졌다. 다만 「낚시성 제목」처럼 언론 기사에서는 지금도 쓰이므로 완전히 죽은 말은 아니다. 표준어 낚시(물고기 잡기)와 문맥으로 구별해야 한다.', '{"de": "Communities gehen heute streng dagegen vor und Nutzer reagieren offen genervt, die Scherzpost-Kultur ist damit weitgehend weg. Das Wort überlebt in der Presse als 낚시성 제목 (Köder-Schlagzeile), ist also nicht ganz tot. Vom gewöhnlichen 낚시 (Angeln) am Kontext unterscheiden.", "en": "Communities now police it hard and users react with open irritation, so the prank-post culture itself is mostly gone. The word survives in press usage like 낚시성 제목 (baity headline), so it is not fully dead. Distinguish it from the ordinary sense of 낚시 (fishing) by context.", "es": "Los foros lo sancionan con dureza y los usuarios reaccionan con fastidio abierto, así que la cultura del post-broma casi ha desaparecido. La palabra sobrevive en la prensa con 낚시성 제목 (titular cebo), o sea que no está del todo muerta. Distínguela por contexto del 낚시 normal (pescar).", "ja": "コミュニティが規定で強く取り締まり、利用者もあからさまに不快感を示すため、いたずらとしての釣り記事文化はほぼ消えた。ただし「낚시성 제목(釣り見出し)」のように報道では今も使われ、完全な死語ではない。標準語の낚시(釣り)とは文脈で区別する。", "vi": "Các diễn đàn nay xử lý rất gắt và người dùng phản ứng ra mặt, nên văn hóa bài câu kiểu trò đùa gần như biến mất. Từ này vẫn sống trong báo chí qua cụm 낚시성 제목 (tiêu đề câu view) nên chưa hẳn đã chết. Phân biệt với 낚시 nghĩa câu cá bằng ngữ cảnh."}'::jsonb, array['어그로', '박제', '뒷광고']::text[], array['낚였다', '낚이다', '낚시글', '낚다']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Clickbait / bait post"}, {"lang": "🇯🇵 JA", "text": "釣り(釣り記事)"}, {"lang": "🇨🇳 ZH", "text": "标题党、钓鱼帖"}, {"lang": "🇻🇳 VI", "text": "Bài câu view, giật tít"}, {"lang": "🇪🇸 ES", "text": "Clickbait, post cebo"}, {"lang": "🇩🇪 DE", "text": "Clickbait, Köder-Post"}]'::jsonb),
('535', '득템', 'Deuk-tem', 'outdated-slang', NULL, '운 좋게 좋은 물건을 손에 넣음', '{"de": "Einen Glücksgriff machen", "en": "Scoring a great find", "es": "Conseguir un chollo", "ja": "良い物を手に入れること", "vi": "Vớ được món hời"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Der Mantel für 50.000 Won? Absoluter Glücksgriff.", "es": "¿Este abrigo por cincuenta mil wones? Menudo chollo.", "ja": "このコート5万ウォン? 完全に掘り出し物じゃん。", "vi": "Cái áo khoác này 50 nghìn won á? Vớ hời thật rồi.", "eng": "This coat was fifty thousand won? Total score.", "kor": "이 코트 5만 원? 완전 득템했네."}], "definition": "한자 得(득)과 영어 item을 붙인 말. 온라인 게임에서 귀한 아이템을 얻는다는 뜻으로 시작해, 현실에서 싸고 좋은 물건을 손에 넣는 일까지 뜻이 넓어졌다. 아무 물건에나 쓰지 않고 운이나 끈질긴 노력 끝에 겨우 얻은 것에 쓴다.", "definition_i18n": {"de": "得 (erlangen) + item. Ursprünglich Gamer-Slang für einen endlich ergatterten seltenen Drop, später jeder tolle Fund im echten Leben. Nicht für normale Käufe — nur für etwas, das man mit Glück oder Ausdauer bekam.", "en": "得 (to obtain) + item. It started as game slang for finally landing a rare drop, then widened to any great real-world score. Not used for ordinary purchases — only for something you got through luck or persistence.", "es": "得 (obtener) + item. Nació como jerga gamer para conseguir por fin un objeto raro y se amplió a cualquier gran hallazgo real. No vale para una compra cualquiera: solo para algo logrado con suerte o insistencia.", "ja": "漢字の得と英語のitemを合わせた語。オンラインゲームでレアアイテムを入手する意味から始まり、現実で安くて良い物を手に入れることまで広がった。何にでも使わず、運や粘り強さの末にやっと得た物に使う。", "vi": "得 (được) + item. Khởi đầu là tiếng lóng game khi cuối cùng cũng rơi đồ hiếm, sau mở rộng sang mọi món hời ngoài đời. Không dùng cho mua sắm thường — chỉ cho thứ có được nhờ may mắn hay kiên trì."}}]'::jsonb, '얻는다는 뜻의 한자 得과 영어 item의 합성어. 어느 게임에서 시작됐는지는 확정되지 않았고 온라인 게임 「리니지」에서 비롯됐다는 설이 가장 유력하게 거론된다. 2016년 국내 최초의 게임 용어 사전이 이 말을 표제어로 실으면서 게임 밖으로 퍼져 나간 대표 사례로 소개됐다.', '{"de": "Mischung aus sinokoreanisch 得 (erlangen) und englisch item. In welchem Spiel es entstand, ist ungeklärt; am häufigsten wird das MMO Lineage genannt. 2016 nahm Koreas erstes Games-Fachwörterbuch es als Stichwort auf — als Paradebeispiel für Gamer-Slang, der in die Alltagssprache überging.", "en": "A blend of the Sino-Korean 得 (obtain) and English item. Which game it started in is not settled; the most-cited theory points to the MMO Lineage. In 2016 Korea first game-terminology dictionary listed it as a headword, presenting it as a showcase of game slang crossing into everyday speech.", "es": "Mezcla del sinocoreano 得 (obtener) y el inglés item. No está claro en qué juego nació; la teoría más citada apunta al MMO Lineage. En 2016 el primer diccionario coreano de términos de videojuegos lo recogió como entrada, como ejemplo de jerga gamer que saltó al habla común.", "ja": "「得る」を意味する漢字の得と英語itemの合成語。どのゲーム発祥かは未確定で、オンラインゲーム「リネージュ」起源説が最も有力とされる。2016年、国内初のゲーム用語辞典が見出し語として収録し、ゲーム外へ広がった代表例として紹介された。", "vi": "Ghép chữ Hán 得 (được) với item tiếng Anh. Chưa rõ xuất phát từ game nào; giả thuyết được nhắc nhiều nhất là MMO Lineage. Năm 2016, từ điển thuật ngữ game đầu tiên của Hàn Quốc đưa nó vào làm mục từ, như ví dụ tiêu biểu cho tiếng lóng game tràn ra đời thường."}'::jsonb, '2000년대 게임·쇼핑 커뮤니티에서 매우 흔했지만 지금은 「꿀템」·「인생템」 쪽이 더 자주 쓰인다. 중고 거래 후기나 세일 인증 글에는 아직 남아 있어 완전히 죽은 말은 아니다.', '{"de": "In Gaming- und Shopping-Foren der 2000er allgegenwärtig; heute sind 꿀템 und 인생템 gebräuchlicher. In Gebrauchtkauf-Reviews und Schnäppchen-Posts taucht es noch auf, ganz tot ist es also nicht.", "en": "Everywhere in 2000s gaming and shopping forums; today 꿀템 and 인생템 are more common. It still turns up in secondhand-sale reviews and haul posts, so it is not fully dead.", "es": "Omnipresente en foros de juegos y compras de los 2000; hoy se usan más 꿀템 e 인생템. Sigue apareciendo en reseñas de segunda mano y posts de rebajas, así que no está del todo muerta.", "ja": "2000年代のゲーム・ショッピングコミュニティでは定番だったが、今は「꿀템」「인생템」の方が多い。中古取引のレビューやセール自慢の投稿には残っており、完全な死語ではない。", "vi": "Cực phổ biến trên diễn đàn game và mua sắm những năm 2000; nay 꿀템 và 인생템 thông dụng hơn. Vẫn thấy trong review đồ cũ và bài khoe săn sale nên chưa hẳn đã chết."}'::jsonb, array['인생템', '개이득']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "To score / a great find"}, {"lang": "🇯🇵 JA", "text": "良品ゲット"}, {"lang": "🇨🇳 ZH", "text": "捡漏、入手好物"}, {"lang": "🇻🇳 VI", "text": "Vớ được món hời"}, {"lang": "🇪🇸 ES", "text": "Pillar un chollo"}, {"lang": "🇩🇪 DE", "text": "Ein Schnäppchen abstauben"}]'::jsonb),
('536', '눈팅', 'Nun-ting', 'outdated-slang', NULL, '글은 안 쓰고 보기만 하는 것', '{"de": "Nur mitlesen, nie posten", "en": "Lurking — reading without ever posting", "es": "Mirar sin participar nunca", "ja": "書き込まずに見るだけの行為", "vi": "Chỉ đọc mà không bao giờ đăng bài"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Ich lese in dem Forum seit drei Jahren mit und habe nie etwas gepostet.", "es": "Llevo tres años en ese foro solo mirando, sin escribir nada.", "ja": "そのカフェ、3年間ずっと눈팅だけしてる。", "vi": "Tớ vào diễn đàn đó ba năm rồi mà chỉ đọc chứ chưa đăng gì.", "eng": "I have been lurking on that forum for three years without posting once.", "kor": "나 그 카페 3년째 눈팅만 하고 있어."}], "definition": "「눈」과 채팅의 「팅」을 합친 말. 커뮤니티나 채팅방에 들어가 있으면서 글도 댓글도 쓰지 않고 보기만 하는 행동. 그렇게 하는 사람은 「눈팅족」이라고 부른다.", "definition_i18n": {"de": "눈 (Auge) verschmolzen mit dem 팅 von 채팅 (chatten). In einer Community oder einem Chat anwesend sein, aber nur lesen — nie posten, nie kommentieren. Wer das tut, ist ein 눈팅족.", "en": "눈 (eye) fused with the 팅 of 채팅 (chatting). Being present in a community or chatroom but only reading — never posting, never commenting. Someone who does this is a 눈팅족.", "es": "눈 (ojo) unido al 팅 de 채팅 (chatear). Estar en una comunidad o sala de chat pero solo leer, sin publicar ni comentar nunca. Quien lo hace es un 눈팅족.", "ja": "「눈(目)」と채팅(チャット)の「팅」を合わせた語。コミュニティやチャット部屋にいながら、投稿もコメントもせず見るだけの行動。そうする人は「눈팅족」と呼ぶ。", "vi": "눈 (mắt) ghép với 팅 trong 채팅 (chat). Có mặt trong cộng đồng hay phòng chat nhưng chỉ đọc, không đăng bài cũng không bình luận. Người như vậy gọi là 눈팅족."}}]'::jsonb, '1990년대 말에서 2000년대 채팅방에서, 대화에 끼지 않고 남들 이야기를 구경만 하는 사람을 두고 「채팅은 안 하고 눈으로만 한다」며 부른 데서 나왔다. 같은 행동을 일본에서는 ROM(Read Only Member), 영어권에서는 lurker라고 부른다.', '{"de": "Entstand in den Chatrooms der späten 1990er und 2000er für Leute, die nie mitredeten — sie chatteten angeblich nur mit den Augen. Im Japanischen heißt das ROM (Read Only Member), im Englischen lurking.", "en": "Coined in the late-1990s and 2000s chatrooms for people who never joined the conversation — they were said to be chatting with their eyes only. Japanese calls the same behaviour ROM (Read Only Member); English calls it lurking.", "es": "Surgió en las salas de chat de finales de los 90 y los 2000 para quienes nunca entraban en la conversación: se decía que chateaban solo con los ojos. En Japón lo llaman ROM (Read Only Member); en inglés, lurking.", "ja": "1990年代末〜2000年代のチャット部屋で、会話に入らず人の話を眺めるだけの人を「チャットせず目でだけする」と呼んだことに由来。同じ行動を日本ではROM(Read Only Member)、英語圏ではlurkerという。", "vi": "Ra đời ở các phòng chat cuối thập niên 1990 và 2000, chỉ người không bao giờ tham gia trò chuyện — bị nói là chat bằng mắt thôi. Tiếng Nhật gọi hành vi này là ROM (Read Only Member), tiếng Anh là lurking."}'::jsonb, '커뮤니티 활동이 인스타그램·유튜브로 옮겨 가면서 쓰임이 크게 줄었다. 지금은 그냥 「보기만 해」라고 하거나 영어 그대로 「럴커」라고 하는 편이다. 오래된 네이버 카페나 디시인사이드 같은 게시판에서는 아직 살아 있는 말이다.', '{"de": "Der Gebrauch ging stark zurück, als sich das Community-Leben zu Instagram und YouTube verlagerte; heute sagt man einfach 보기만 해 (ich schaue nur) oder nutzt das englische lurker. In alten Naver-Cafés und Boards wie DC Inside lebt es weiter.", "en": "Its use shrank sharply as community life moved to Instagram and YouTube; people now just say 보기만 해 (I only look) or borrow the English lurker. It is still alive on older Naver cafés and boards like DC Inside.", "es": "Su uso cayó en picado al migrar la vida comunitaria a Instagram y YouTube; ahora se dice 보기만 해 (solo miro) o se toma el inglés lurker. Sigue vivo en cafés de Naver antiguos y foros como DC Inside.", "ja": "コミュニティ活動がインスタやYouTubeへ移るにつれ使用が激減し、今は単に「보기만 해(見てるだけ)」や英語のlurkerを使う。古いネイバーカフェやDCインサイドのような掲示板では今も生きている。", "vi": "Ít dùng hẳn khi sinh hoạt cộng đồng chuyển sang Instagram và YouTube; giờ người ta nói 보기만 해 (chỉ xem thôi) hoặc mượn từ lurker. Vẫn sống ở các café Naver cũ và diễn đàn như DC Inside."}'::jsonb, array['잠수', '어그로', '박제']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Lurking"}, {"lang": "🇯🇵 JA", "text": "ROM専(見るだけ)"}, {"lang": "🇨🇳 ZH", "text": "潜水(只看不发言)"}, {"lang": "🇻🇳 VI", "text": "Chỉ đọc không đăng"}, {"lang": "🇪🇸 ES", "text": "Lurkear"}, {"lang": "🇩🇪 DE", "text": "Mitlesen ohne zu posten"}]'::jsonb),
('537', '듣보잡', 'Deut-Bo-Jap', 'outdated-slang', NULL, '듣도 보도 못한 무명 — 사람·작품을 깎아내리던 2000년대 은어', '{"de": "Ein voellig unbekannter Niemand — 2000er-Slang zur Herabwuerdigung von Obskurem", "en": "A never-heard-of nobody — 2000s slang for belittling an obscure person or work", "es": "Un don nadie del que nadie ha oido — jerga de los 2000 para menospreciar a alguien desconocido", "ja": "聞いたことも見たこともない無名 — 人や作品を見下した2000年代の隠語", "vi": "Kẻ vô danh chưa ai nghe tới — tiếng lóng thập niên 2000 để dè bỉu người hay tác phẩm vô danh"}'::jsonb, '[듣뽀잡]', '[{"type": "명사", "examples": [{"de": "Die No-Name-Marke, die alle abtaten, ist heute ein Riesenkonzern.", "es": "Esa marca que todos daban por don nadie ahora es una gran empresa.", "ja": "あのトゥッポジャプ扱いされてたブランド、今や完全に大企業じゃん。", "vi": "Cái hãng vô danh hồi đó giờ thành tập đoàn lớn rồi đấy.", "eng": "That no-name brand everyone dismissed is a huge company now.", "kor": "그 듣보잡 브랜드가 지금은 완전 대기업 됐잖아."}, {"de": "Sag das heute und du kriegst sofort Gegenwind — Deut-bo-jap ist ein altes Wort.", "es": "Si dices eso hoy te caen encima al instante; deut-bo-jap es palabra de antes.", "ja": "今そんな言葉使ったらすぐ叩かれるよ。トゥッポジャプは昔の言葉。", "vi": "Giờ nói vậy là bị mắng ngay. Deut-bo-jap là từ ngày xưa rồi.", "eng": "Say that now and you get called out immediately — deut-bo-jap is an old word.", "kor": "요즘은 그런 말 쓰면 바로 욕먹어. 듣보잡은 옛날 말이야."}], "definition": "듣도 보도 못한 잡놈의 줄임말로, 이름이 알려지지 않았거나 인기 없는 사람·물건·작품을 낮잡아 부르는 말. 작품에 쓸 때는 듣보작이라고도 했고, 더 줄여 듣보라고만 쓰기도 했다. 상대를 깎아내리는 비하 표현이라 대놓고 쓰면 시비가 붙는 말이었다.", "definition_i18n": {"de": "Kurzform von deut-do bo-do mot-han jap-nom (ein Niemand, von dem keiner gehoert oder gesehen hat). Es setzt eine Person, ein Produkt oder ein Werk als unbekannt oder unbeliebt herab. Fuer Werke sagte man Deut-bo-jak, weiter gekuerzt auch Deut-bo. Es ist offen abwertend — jemandem ins Gesicht gesagt, war es eine Provokation.", "en": "Short for deut-do bo-do mot-han jap-nom (a lowlife nobody has heard or seen). It belittles a person, product or work as unknown or unpopular. For works people said deut-bo-jak; it was also clipped further to deut-bo. It is openly derogatory, so using it to someone face was picking a fight.", "es": "Abreviatura de deut-do bo-do mot-han jap-nom (un don nadie que nadie ha oido ni visto). Menosprecia a una persona, producto u obra por desconocida o impopular. Para obras se decia deut-bo-jak, y tambien se recortaba a deut-bo. Es abiertamente despectivo: usarlo en la cara era buscar pelea.", "ja": "聞いたことも見たこともない雑魚の略で、名が知られていない、人気のない人・物・作品を見下して呼ぶ語。作品にはトゥッポジャク、さらに略してトゥッポとも言った。露骨な蔑称なので面と向かって使えば喧嘩になる言葉だった。", "vi": "Viết tắt của deut-do bo-do mot-han jap-nom (kẻ hạng bét chưa ai nghe ai thấy). Dùng để dè bỉu người, sản phẩm hay tác phẩm vô danh, kém tiếng. Với tác phẩm thì nói deut-bo-jak, rút gọn hơn nữa là deut-bo. Đây là từ miệt thị rõ ràng, nói thẳng vào mặt ai là gây sự."}}]'::jsonb, '2000년대 인터넷 커뮤니티에서 듣보잡대(듣도 보도 못한 잡대학)라는 표현이 대학 서열 논쟁 중에 쓰이다가, 뒤의 대가 떨어져 나가며 사람·작품 전반으로 뜻이 넓어졌다. 발원지는 출처마다 갈려서 디시인사이드로 보는 설과 다음 카페 훌리건천국으로 보는 설이 있고 확정되지 않았다. 두 설 모두 듣보잡대가 먼저였다는 구조는 같다.', '{"de": "In Online-Foren der 2000er kursierte deut-bo-jap-dae (eine Hochschule, von der niemand gehoert hat) in Debatten ueber Universitaetsrankings; als das abschliessende dae wegfiel, weitete sich die Bedeutung auf Personen und Werke aus. Die Quellen streiten ueber den Ursprung — mal DCInside, mal ein Daum-Cafe namens Hooligan Heaven — und es bleibt offen. Beide Versionen sind sich einig, dass deut-bo-jap-dae zuerst da war.", "en": "In 2000s online communities the phrase deut-bo-jap-dae (a lowlife college nobody has heard of) circulated in arguments over university rankings; when the final dae (college) dropped off, the meaning widened to people and works in general. Sources disagree on the birthplace — some say DCInside, others a Daum cafe called Hooligan Heaven — and it is unsettled. Both versions agree deut-bo-jap-dae came first.", "es": "En los foros de los 2000 circulo deut-bo-jap-dae (una universidad cualquiera de la que nadie ha oido) en las discusiones sobre rankings universitarios; al caer el dae final, el sentido se amplio a personas y obras en general. Las fuentes discrepan sobre el origen — unas apuntan a DCInside, otras a un cafe de Daum llamado Hooligan Heaven — y sigue sin resolverse. Ambas coinciden en que deut-bo-jap-dae fue primero.", "ja": "2000年代のネットコミュニティで大学序列論争の中トゥッポジャプデ(聞いたことも見たこともない雑大学)という表現が使われ、末尾のデ(大)が落ちて人や作品全般へ意味が広がった。発祥地は出典により分かれ、DCインサイド説とDaumカフェのフーリガン天国説があり未確定。どちらもトゥッポジャプデが先という構造は同じ。", "vi": "Trên các diễn đàn thập niên 2000, cụm deut-bo-jap-dae (trường đại học hạng bét chưa ai nghe tới) lưu hành trong các cuộc tranh cãi xếp hạng đại học; khi chữ dae (đại học) rụng đi, nghĩa mở rộng sang người và tác phẩm nói chung. Các nguồn bất đồng về nơi khởi phát — có nguồn nói DCInside, nguồn khác nói quán cà phê Daum tên Hooligan Heaven — và vẫn chưa ngã ngũ. Cả hai đều đồng ý deut-bo-jap-dae có trước."}'::jsonb, '2000년대 후반~2010년대 초 인터넷에서 아주 흔했지만 지금은 거의 쓰지 않는다. 명백한 비하 표현이라 요즘 온라인에서는 쓰면 오히려 쓴 사람이 비판받는다. 외국인 학습자라면 뜻은 알아 두되 직접 쓰지 않는 쪽을 권한다 — 2000년대 글이나 옛 댓글을 읽을 때 만나는 말이다.', '{"de": "Im Internet der spaeten 2000er und fruehen 2010er sehr gelaeufig, heute weitgehend verschwunden. Es ist klar abwertend, sodass heute derjenige kritisiert wird, der es sagt. Lernende sollten es erkennen, aber nicht verwenden — man begegnet ihm beim Lesen alter Beitraege und Kommentare, nicht im heutigen Gespraech.", "en": "Very common online in the late 2000s and early 2010s, now largely gone. It is plainly derogatory, so today the person who says it is the one who gets criticised. Learners should recognise it but not use it — you will meet it reading 2000s posts and old comments, not in live conversation.", "es": "Muy comun en internet a finales de los 2000 e inicios de los 2010, hoy practicamente ausente. Es abiertamente despectivo, asi que ahora el criticado es quien lo dice. A los estudiantes les conviene reconocerlo pero no usarlo: aparece al leer publicaciones y comentarios antiguos, no en conversacion viva.", "ja": "2000年代後半から2010年代初めのネットでは非常によく使われたが、今はほぼ使わない。明白な蔑称なので、今のオンラインでは使った側が批判される。学習者は意味は知っておき自分では使わないことを勧める — 2000年代の書き込みや古いコメントを読むときに出会う語。", "vi": "Rất phổ biến trên mạng cuối 2000 đầu 2010, nay gần như không còn. Đây là từ miệt thị rõ ràng nên bây giờ ai nói ra mới là người bị chỉ trích. Người học nên biết nghĩa nhưng đừng dùng — bạn sẽ gặp nó khi đọc bài viết và bình luận cũ, không phải trong hội thoại hiện nay."}'::jsonb, array['안습', '박제', '극혐', '좆소', '틀딱']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "A never-heard-of nobody (derogatory)"}, {"lang": "🇯🇵 JA", "text": "無名の雑魚(蔑称)"}, {"lang": "🇨🇳 ZH", "text": "没听过的无名小卒(贬义)"}, {"lang": "🇻🇳 VI", "text": "Kẻ vô danh tiểu tốt (miệt thị)"}, {"lang": "🇪🇸 ES", "text": "Don nadie desconocido (despectivo)"}, {"lang": "🇩🇪 DE", "text": "Unbekannter Niemand (abwertend)"}]'::jsonb),
('538', '머박', 'Meo-Bak', 'outdated-slang', 'yaminjeongeum', '''대박''을 글자 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Eine Umschreibung von 대박 (krass) mit ähnlich aussehenden Hangul", "en": "A look-alike-Hangul respelling of 대박 (awesome)", "es": "Reescritura de 대박 (¡genial!) con hangul de forma parecida", "ja": "「テバク(すごい)」を形の似たハングルに置き換えた表記", "vi": "Cách viết lại 대박 (đỉnh quá) bằng chữ Hàn trông giống"}'::jsonb, '[머박]', '[{"type": "감탄사", "examples": [{"de": "Der neue Song ist echt meobak.", "es": "El tema nuevo es meobak de verdad.", "ja": "今回の新曲、マジでモバクだわ", "vi": "Bài mới lần này đúng là meobak thật.", "eng": "This new track is straight-up meobak.", "kor": "이번 신곡 머박이다 진짜"}], "definition": "''대박''의 ''ㄷ''을 모양이 닮은 ''ㅁ''으로 바꿔 쓴 야민정음 표기. 뜻과 쓰임은 ''대박''과 똑같아 놀라움이나 감탄을 나타낸다. 2018~2019년 온라인에서 많이 쓰였고 지금은 한물간 표기로 여겨진다. 어느 쪽으로 검색해도 같은 말이다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung von 대박, bei der ㄷ durch das ähnlich aussehende ㅁ ersetzt wird. Bedeutung und Gebrauch sind identisch mit 대박 — ein Ausruf der Überraschung oder Bewunderung. Um 2018-2019 online groß, heute als altbacken empfunden. Beide Schreibungen sind dasselbe Wort.", "en": "A yaminjeongeum spelling of 대박, replacing ㄷ with the similarly shaped ㅁ. It means and works exactly like 대박 — an exclamation of surprise or admiration. Big online around 2018-2019, now seen as dated. Both spellings are the same word.", "es": "Grafía yaminjeongeum de 대박, con la ㄷ sustituida por la ㅁ, de forma parecida. Significa y funciona igual que 대박: una exclamación de sorpresa o admiración. Muy usada en 2018-2019, hoy se percibe anticuada. Ambas grafías son la misma palabra.", "ja": "「대박」の「ㄷ」を形の似た「ㅁ」に替えたヤミン正音表記。意味も使い方も「대박」と同じで、驚きや感嘆を表す。2018〜2019年にオンラインでよく使われ、今は古い表記とみなされる。どちらで検索しても同じ語。", "vi": "Cách viết yaminjeongeum của 대박, đổi ㄷ thành ㅁ trông giống. Nghĩa và cách dùng y hệt 대박 — thán từ bày tỏ ngạc nhiên hay thán phục. Rộ trên mạng quãng 2018-2019, giờ bị coi là lỗi thời. Hai cách viết là cùng một từ."}}]'::jsonb, '야민정음(글자 모양이 닮은 한글로 바꿔 쓰는 인터넷 표기법)의 대표적인 예 중 하나다. 야민정음 자체는 디시인사이드 야구 갤러리에서 2014년경 퍼졌다는 설이 알려져 있으나 확정되지 않았고, ''머박''을 누가 처음 썼는지도 확인되지 않는다. 한글날 전후 언론이 ''머박'', ''띵언'' 등을 신조어·줄임말 남용 사례로 다루면서 이름이 알려졌다.', '{"de": "Eines der Standardbeispiele für Yaminjeongeum (Hangul mit ähnlich aussehenden Zeichen umschreiben). Yaminjeongeum soll sich um 2014 vom Baseball-Board auf DCInside verbreitet haben, bestätigt ist das nicht, und wer 머박 zuerst schrieb, ist unbekannt. Bekannt wurde es, als die Presse zum Hangul-Tag 머박 und 띵언 als Beispiele für Slang-Übertreibung anführte.", "en": "One of the stock examples of yaminjeongeum (rewriting Hangul with look-alike letters). Yaminjeongeum itself is said to have spread from DCInside''s baseball board around 2014, but that is unconfirmed, and no one knows who wrote 머박 first. It became widely known when Hangul Day coverage cited 머박 and 띵언 as cases of slang overuse.", "es": "Uno de los ejemplos clásicos de yaminjeongeum (reescribir hangul con letras parecidas). Se dice que el yaminjeongeum se extendió desde el tablón de béisbol de DCInside hacia 2014, pero no está confirmado, y se desconoce quién escribió 머박 primero. Se dio a conocer cuando la prensa del Día del Hangul citó 머박 y 띵언 como ejemplos de abuso de jerga.", "ja": "ヤミン正音(形の似たハングルに置き換える書き方)の代表例の一つ。ヤミン正音自体はDCインサイドの野球ギャラリーで2014年頃広まったという説があるが未確定で、「머박」を最初に使った人も分かっていない。ハングルの日前後に報道が「머박」「띵언」を新造語・略語乱用の例として取り上げ、名が知られた。", "vi": "Một trong những ví dụ kinh điển của yaminjeongeum (viết lại chữ Hàn bằng chữ trông giống). Bản thân yaminjeongeum được cho là lan từ diễn đàn bóng chày DCInside khoảng 2014 nhưng chưa được xác nhận, và không rõ ai viết 머박 đầu tiên. Nó nổi lên khi báo chí dịp Ngày chữ Hàn dẫn 머박 và 띵언 làm ví dụ lạm dụng tiếng lóng."}'::jsonb, '''대박''이 들어갈 자리에 그대로 바꿔 넣으면 된다. 장난스러운 표기라 공식적인 글에는 쓰지 않고, 2018~2019년 유행이 지나 지금 쓰면 촌스럽다는 소리를 듣는다.', '{"de": "Einfach dort einsetzen, wo 대박 stünde. Eine verspielte Schreibung, also nie in formellen Texten — und seit die Welle 2018-2019 vorbei ist, wirkt es altbacken.", "en": "Drop it in wherever 대박 would go. It is a playful spelling, so never in formal writing — and since the 2018-2019 wave passed, using it now reads as dated.", "es": "Colócalo donde iría 대박. Es una grafía juguetona, nunca para textos formales; y pasada la ola de 2018-2019, hoy suena anticuado.", "ja": "「대박」が入る場所にそのまま置き換えればよい。遊びの表記なので公式の文章には使わず、2018〜2019年のブームが去った今使うとダサいと言われる。", "vi": "Cứ thay vào chỗ của 대박. Đây là lối viết đùa nên không dùng trong văn bản trang trọng; và sau làn sóng 2018-2019, dùng bây giờ nghe quê."}'::jsonb, array['대박', '댕댕이', '띵곡']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Awesome! (dated look-alike spelling of 대박)"}, {"lang": "🇯🇵 JA", "text": "すごい!(대박のヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "厉害!(대박的\"野民正音\"写法)"}, {"lang": "🇻🇳 VI", "text": "Đỉnh! (cách viết giống của 대박)"}, {"lang": "🇪🇸 ES", "text": "¡Genial! (grafía parecida de 대박)"}, {"lang": "🇩🇪 DE", "text": "Krass! (Ähnlichkeitsschreibung von 대박)"}]'::jsonb),
('539', '뭥미', 'Mwong-mi', 'outdated-slang', NULL, '오타가 그대로 굳어진 ''이게 뭐야?''', '{"de": "Ein Tippfehler, der zum Wort wurde: ''Was soll das denn?''", "en": "A typo that became a word: ''what even is this?''", "es": "Un error de tecleo convertido en palabra: ''¿pero qué es esto?''", "ja": "打ち間違いがそのまま定着した「何これ?」", "vi": "Lỗi gõ phím thành từ: ''cái gì đây?''"}'::jsonb, NULL, '[{"type": "감탄사", "examples": [{"de": "Ich hab aus dem Nichts diese Nachricht bekommen — was soll das denn?", "es": "Me llegó este mensaje de la nada, ¿qué es esto?", "ja": "急にこんなメッセージ来たんだけど何これ?", "vi": "Tự nhiên nhận được tin nhắn này, cái gì vậy?", "eng": "I just got this text out of nowhere — what even is this?", "kor": "갑자기 이런 문자가 왔는데 뭥미?"}, {"de": "Schreibt wirklich noch jemand 뭥미? Das ist uralt.", "es": "¿Todavía hay quien escribe 뭥미? Es viejísimo.", "ja": "まだ뭥미使う人いる?めっちゃ昔の言葉なのに", "vi": "Vẫn còn người dùng 뭥미 à? Cũ lắm rồi mà", "eng": "People still type 뭥미? That is so old.", "kor": "아직도 뭥미 쓰는 사람 있어? 완전 옛날 말인데"}], "definition": "''뭐임?''을 급하게 치다 생긴 오타. 황당하거나 어이없는 것을 봤을 때 ''이게 뭐야?'' 정도로 쓴다. 원래 말보다 어감이 우스워서 일부러 쓰게 된 경우로, 2000년대 중후반에 크게 유행했다.", "definition_i18n": {"de": "Tippfehler für 뭐임 (was ist das), benutzt wie ''was soll das denn?'' bei etwas Verwirrendem. Die verhunzte Form klang witziger als das Original, also tippte man sie absichtlich; Höhepunkt Mitte bis Ende der 2000er.", "en": "A typo for 뭐임 (what is it), used like ''what even is this?'' when something is baffling. The mangled version sounded funnier than the original, so people started typing it on purpose; it peaked in the mid-to-late 2000s.", "es": "Error al teclear 뭐임 (qué es), usado como ''¿pero qué es esto?'' ante algo desconcertante. Sonaba más gracioso que el original, así que se empezó a escribir a propósito; su auge fue a mediados y finales de los 2000.", "ja": "「뭐임?(何これ)」を急いで打ったときの誤字。あきれたり訳が分からないものを見たときの「何これ?」。元の語より語感が面白く、わざと使うようになった。2000年代半ば~後半に大流行。", "vi": "Lỗi gõ của 뭐임 (cái gì vậy), dùng như ''cái quái gì đây?'' khi thấy điều khó hiểu. Bản lỗi nghe buồn cười hơn bản gốc nên người ta cố tình gõ vậy; thịnh nhất giữa và cuối thập niên 2000."}}]'::jsonb, '두벌식 자판으로 ''뭐임''을 빠르게 칠 때 두 번째 음절의 ㅁ이 ㅣ보다 먼저 입력되면서 ㅁ과 ㅇ의 자리가 뒤바뀌어 ''뭥미''가 된다. 두벌식 자판에서만 생기는 오타다. 2000년대 중후반에 널리 퍼졌고 2020년대에는 거의 쓰이지 않는다. 최초 사용 시점을 특정한 출처는 없다.', '{"de": "Auf der zweisatzigen koreanischen Tastatur kann beim schnellen Tippen von 뭐임 das ㅁ vor dem ㅣ registriert werden, wodurch ㅁ und ㅇ tauschen und 뭥미 entsteht. Der Fehler tritt nur bei diesem Layout auf. Verbreitet Mitte bis Ende der 2000er, in den 2020ern kaum noch in Gebrauch; keine Quelle nennt eine Erstverwendung.", "en": "On the standard two-set Korean keyboard, typing 뭐임 fast can register the ㅁ before the ㅣ, swapping ㅁ and ㅇ and producing 뭥미. The typo is only possible on that layout. It spread in the mid-to-late 2000s and is nearly unused in the 2020s; no source pins down a first attested use.", "es": "En el teclado coreano de dos juegos, teclear 뭐임 rápido puede registrar la ㅁ antes que la ㅣ, intercambiando ㅁ y ㅇ y dando 뭥미. El error solo ocurre en ese teclado. Se difundió a mediados y finales de los 2000 y apenas se usa en los 2020; ninguna fuente fija su primer uso.", "ja": "2ボル式キーボードで「뭐임」を速く打つと2音節目のㅁがㅣより先に入力され、ㅁとㅇが入れ替わって「뭥미」になる。2ボル式でしか起きない誤字。2000年代半ば~後半に広まり、2020年代にはほぼ使われない。初出を特定した資料はない。", "vi": "Trên bàn phím tiếng Hàn hai bộ, gõ nhanh 뭐임 có thể nhập ㅁ trước ㅣ, khiến ㅁ và ㅇ đổi chỗ thành 뭥미. Lỗi này chỉ xảy ra với bố cục đó. Lan rộng giữa-cuối thập niên 2000, gần như không dùng trong thập niên 2020; không nguồn nào xác định lần dùng đầu tiên."}'::jsonb, '물음표 없이 문장 끝에 붙여 ''뭥미''만 던지는 게 전형적인 쓰임이었다. 지금 쓰면 나이대가 드러나는 말이라 젊은 층은 대신 ''이게 뭐임'', ''뭐지'', ''이왜진''을 쓴다.', '{"de": "Wurde typischerweise allein ans Satzende gesetzt, ohne Fragezeichen. Heute verrät es dein Alter — Jüngere sagen stattdessen 이게 뭐임, 뭐지 oder 이왜진.", "en": "Typically dropped at the end of a sentence on its own, no question mark needed. Today it dates you — younger speakers say 이게 뭐임, 뭐지, or 이왜진 instead.", "es": "Se soltaba al final de la frase, sin signo de interrogación. Hoy delata tu edad: los jóvenes dicen 이게 뭐임, 뭐지 o 이왜진.", "ja": "文末に「뭥미」だけ放り投げるのが典型的な使い方。今使うと年齢がバレるので、若い世代は「이게 뭐임」「뭐지」「이왜진」を使う。", "vi": "Thường ném ở cuối câu, không cần dấu hỏi. Giờ dùng là lộ tuổi — người trẻ nói 이게 뭐임, 뭐지 hay 이왜진."}'::jsonb, array['이왜진', '냉무']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "What even is this? (2000s typo slang)"}, {"lang": "🇯🇵 JA", "text": "何これ?(2000年代の誤字スラング)"}, {"lang": "🇨🇳 ZH", "text": "这是什么鬼?(2000年代错字俚语)"}, {"lang": "🇻🇳 VI", "text": "Cái gì đây? (tiếng lóng lỗi gõ thập niên 2000)"}, {"lang": "🇪🇸 ES", "text": "¿Qué es esto? (jerga de errata de los 2000)"}, {"lang": "🇩🇪 DE", "text": "Was soll das denn? (Tippfehler-Slang der 2000er)"}]'::jsonb),
('540', '몸짱', 'Mom-jjang', 'outdated-slang', NULL, '몸이 최고인 사람 — ''얼짱''의 몸 버전', '{"de": "Jemand mit Traumkörper — das 얼짱 für den Body", "en": "Someone with a knockout body — the 얼짱 of physiques", "es": "Alguien con un cuerpazo: la versión corporal de 얼짱", "ja": "体が最高な人——「オルチャン」の体版", "vi": "Người có thân hình cực phẩm — phiên bản body của 얼짱"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Das ganze Training hat sich gelohnt — du bist jetzt richtig in Form.", "es": "Tanto gimnasio dio resultado: estás hecho un cuerpazo.", "ja": "最近ちゃんと運動してたら完全に体が仕上がったね。", "vi": "Dạo này chăm tập ghê, giờ body đỉnh luôn.", "eng": "All that gym time paid off — you are totally ripped now.", "kor": "요즘 운동 열심히 하더니 완전 몸짱 됐네."}, {"de": "Klingt das Wort 몸짱 nicht selbst schon etwas altbacken?", "es": "¿No suena ya un poco antigua la palabra 몸짱?", "ja": "「몸짱」って言葉自体ちょっと昔っぽくない?", "vi": "Bản thân từ 몸짱 nghe hơi cũ rồi đúng không?", "eng": "Does not the word 몸짱 itself sound a bit dated?", "kor": "몸짱이라는 말 자체가 좀 옛날 말 같지 않아?"}], "definition": "몸매가 뛰어난 사람. ''몸'' 뒤에 ''최고''를 뜻하는 ''짱''을 붙인 말로, 얼굴이 뛰어난 사람을 뜻하는 ''얼짱''과 한 쌍을 이룬다. 원래 ''짱''은 청소년들 사이에서 ''싸움대장''을 가리키던 은어였는데 언제부턴가 ''최고''라는 뜻으로 넓어지면서 이런 조어들이 쏟아졌다.", "definition_i18n": {"de": "Eine Person mit herausragender Figur — 몸 (Körper) plus 짱 (das Beste), der Zwilling von 얼짱 (herausragendes Gesicht). 짱 hieß im Jugendslang ursprünglich ''stärkster Schläger'', bevor es sich zu schlicht ''das Beste'' weitete — daraufhin sprudelte diese ganze Wortfamilie hervor.", "en": "A person with an outstanding physique — 몸 (body) plus 짱 (the best), the twin of 얼짱 (outstanding face). 짱 originally meant ''toughest fighter'' in teen slang before it widened to simply ''the best'', which is when this whole family of coinages poured out.", "es": "Persona de físico espectacular: 몸 (cuerpo) más 짱 (lo mejor), gemela de 얼짱 (cara espectacular). 짱 significaba antes ''el más peleón'' en la jerga adolescente, hasta que se amplió a simplemente ''lo mejor'' y brotó toda esta familia de palabras.", "ja": "体つきが優れた人。「몸(体)」に「最高」を意味する「짱」を付けた語で、顔が優れた人を指す「얼짱」と対をなす。もともと「짱」は青少年の間で「ケンカ大将」を指す隠語だったが、いつからか「最高」の意味に広がり、この種の造語が一気に生まれた。", "vi": "Người có thân hình xuất sắc — 몸 (thân) ghép với 짱 (đỉnh nhất), sinh đôi với 얼짱 (mặt xuất sắc). 짱 ban đầu là tiếng lóng tuổi teen chỉ ''trùm đánh nhau'', sau mở rộng thành ''đỉnh nhất'', và cả loạt từ ghép kiểu này tuôn ra từ đó."}}]'::jsonb, '2003년 ''얼짱''이 그해 인터넷 유행어 1위에 오르며 ''짱'' 조어가 유행하던 흐름 속에서 나왔다. 결정적 계기는 2003년 11월 한 인터넷 신문에 연재된 주부의 다이어트 체험기로, 연재자가 ''몸짱 아줌마''로 불리며 전국적인 화제가 됐다. 이른바 ''몸짱 신드롬''은 2004년 대한민국 10대 뉴스에 선정될 만큼 큰 사회 현상이었다. 지금은 완전히 죽은 말은 아니지만 ''바디프로필'', ''오운완'' 같은 말에 밀려 확실히 옛날 말로 들린다.', '{"de": "Entstand in der Welle von 짱-Wortbildungen, nachdem 얼짱 2003 die Liste der Internet-Schlagwörter anführte. Der Wendepunkt war das ab November 2003 in einer Online-Zeitung serialisierte Diättagebuch einer Hausfrau; die Autorin wurde landesweit als ''Momjjang-Ajumma'' bekannt. Das ''Momjjang-Syndrom'' war groß genug, um unter Koreas Top-Ten-Nachrichten 2004 zu landen. Ganz tot ist das Wort nicht, doch 바디프로필 und 오운완 haben es klar in die Vergangenheit geschoben.", "en": "It emerged in the wave of 짱 coinages that followed 얼짱 topping the 2003 list of internet buzzwords. The tipping point was a housewife''''s diet diary serialized in an online paper from November 2003; the writer became known nationwide as the ''momjjang ajumma''. The resulting ''momjjang syndrome'' was big enough to make Korea''''s top-ten news stories of 2004. The word is not fully dead today, but 바디프로필 and 오운완 have pushed it firmly into the past.", "es": "Surgió en la ola de palabras con 짱 que siguió al triunfo de 얼짱 como expresión de internet del año 2003. El punto de inflexión fue el diario de dieta de un ama de casa publicado por entregas en un periódico digital desde noviembre de 2003; la autora pasó a ser la ''momjjang ajumma'' de todo el país. El ''síndrome momjjang'' fue tan grande que entró en las diez noticias del año 2004 en Corea. Hoy no está del todo muerta, pero 바디프로필 y 오운완 la han empujado al pasado.", "ja": "2003年に「얼짱」がその年のネット流行語1位となり「짱」造語が流行した流れの中で生まれた。決定的なきっかけは2003年11月からネット新聞に連載された主婦のダイエット体験記で、連載者は「몸짱アジュンマ」と呼ばれ全国的な話題になった。いわゆる「몸짱シンドローム」は2004年の韓国10大ニュースに選ばれるほどの社会現象。今も完全な死語ではないが、「바디프로필」「오운완」に押されて明らかに昔の言葉に聞こえる。", "vi": "Ra đời trong làn sóng ghép từ với 짱 sau khi 얼짱 đứng đầu danh sách từ mạng thịnh hành năm 2003. Bước ngoặt là loạt bài nhật ký giảm cân của một bà nội trợ đăng trên báo mạng từ tháng 11/2003; tác giả được cả nước gọi là ''momjjang ajumma''. Cái gọi là ''hội chứng momjjang'' lớn tới mức lọt top 10 tin tức Hàn Quốc năm 2004. Nay từ này chưa chết hẳn, nhưng 바디프로필 và 오운완 đã đẩy nó về quá khứ."}'::jsonb, '''몸짱 되다'', ''몸짱 몸매''처럼 쓴다. 칭찬이지만 몸을 평가하는 말이라 처음 만난 사이나 직장에서는 쓰지 않는 게 좋다. 요즘 같은 맥락에서는 ''바디프로필 찍었다'', ''오운완'' 쪽이 자연스럽다.', '{"de": "Verwendet als 몸짱 되다 (einen Traumkörper bekommen) oder 몸짱 몸매. Ein Kompliment, aber eines, das den Körper bewertet — bei Fremden oder im Job besser vermeiden. Heute klingen 바디프로필 찍었다 oder 오운완 natürlicher.", "en": "Used as 몸짱 되다 (become a 몸짱) or 몸짱 몸매. It is a compliment, but it judges a body — avoid it with people you just met or at work. In today''''s conversations 바디프로필 찍었다 or 오운완 sound more natural.", "es": "Se usa como 몸짱 되다 (ponerse cachas) o 몸짱 몸매. Es un halago, pero juzga el cuerpo: evítalo con desconocidos o en el trabajo. Hoy suena más natural 바디프로필 찍었다 u 오운완.", "ja": "「몸짱になる」「몸짱の体つき」のように使う。褒め言葉だが体を評価する語なので、初対面や職場では避けたほうがいい。今の文脈では「바디프로필撮った」「오운완」のほうが自然。", "vi": "Dùng dạng 몸짱 되다 (lên dáng) hay 몸짱 몸매. Là lời khen nhưng vẫn là đánh giá cơ thể — tránh dùng với người mới quen hoặc ở công sở. Ngày nay nói 바디프로필 찍었다 hay 오운완 tự nhiên hơn."}'::jsonb, array['얼짱', '훈남', '오운완']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Someone with a knockout body"}, {"lang": "🇯🇵 JA", "text": "体が最高な人(モムチャン)"}, {"lang": "🇨🇳 ZH", "text": "身材极佳的人(身짱)"}, {"lang": "🇻🇳 VI", "text": "Người có thân hình cực phẩm"}, {"lang": "🇪🇸 ES", "text": "Persona con un cuerpazo"}, {"lang": "🇩🇪 DE", "text": "Jemand mit Traumkörper"}]'::jsonb),
('541', '방콕', 'Bang-Kok', 'outdated-slang', 'daily', '방에 콕 박혀 있기 — 집에서 쉬는 휴가를 방콕 여행에 빗댄 말장난', '{"de": "Im Zimmer verschanzt — ein Wortspiel, das Zuhausebleiben wie eine Bangkok-Reise klingen laesst", "en": "Holed up in your room — a pun that makes staying home sound like a trip to Bangkok", "es": "Encerrado en tu cuarto — juego de palabras que hace que quedarse en casa suene a viaje a Bangkok", "ja": "部屋にこもること — 家で過ごす休暇をバンコク旅行に掛けた言葉遊び", "vi": "Rúc trong phòng — cách chơi chữ khiến ở nhà nghe như đi du lịch Bangkok"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Diesen Urlaub mache ich einfach Bang-kok. Ausland, von wegen.", "es": "Estas vacaciones toca bang-kok. Que voy a ir al extranjero.", "ja": "今回の休暇はバンコク(部屋にこもる)だよ。海外なんてとんでもない。", "vi": "Kỳ nghỉ này mình bang-kok thôi. Nước ngoài gì tầm này.", "eng": "This vacation I am just doing bang-kok. Overseas, yeah right.", "kor": "이번 휴가는 그냥 방콕이야. 해외는 무슨."}, {"de": "Auf die Frage, wohin ich fahre, sagte ich Bangkok — und sie dachten wirklich, ich fliege nach Thailand.", "es": "Me preguntaron adonde iba, dije Bangkok y de verdad pensaron que iba a Tailandia.", "ja": "どこ行くのって聞かれてバンコクって言ったら、本当にタイに行くと思われた。", "vi": "Bị hỏi đi đâu, mình bảo Bangkok, thế là họ tưởng mình đi Thái thật.", "eng": "When they asked where I was going I said Bangkok, and they actually thought I meant Thailand.", "kor": "어디 가냐길래 방콕이라니까 진짜 태국 가는 줄 알더라."}], "definition": "방에 콕 박혀 있다를 줄인 말로, 휴가나 주말에 아무 데도 안 가고 집에만 있는 것. 태국 수도 방콕과 소리가 같아서, 어디 가느냐는 물음에 방콕이요라고 답하면 해외여행 가는 것처럼 들렸다가 곧 농담인 게 드러나는 말장난이 핵심이다. 그렇게 지내는 사람은 방콕족이라고 했다.", "definition_i18n": {"de": "Kurzform von bang-e kok bak-hyeo it-da (im Zimmer verschanzt): Urlaub oder Wochenende verbringen, ohne irgendwohin zu gehen. Es klingt genau wie Bangkok, sodass die Antwort Bangkok auf die Frage wohin fuer einen Moment nach Auslandsreise klingt, bevor der Witz zuendet. Wer so lebte, war ein Bang-kok-jok.", "en": "Short for bang-e kok bak-hyeo it-da (holed up in your room): spending a holiday or weekend going nowhere. It sounds exactly like Bangkok, so answering where are you going with Bangkok momentarily suggests an overseas trip before the joke lands. Someone who lives that way was a bang-kok-jok.", "es": "Abreviatura de bang-e kok bak-hyeo it-da (metido en tu cuarto): pasar las vacaciones o el fin de semana sin ir a ninguna parte. Suena igual que Bangkok, asi que responder Bangkok a donde vas sugiere por un instante un viaje al extranjero antes de que se entienda la broma. A quien vivia asi se le llamaba bang-kok-jok.", "ja": "部屋にこもっているの略で、休暇や週末にどこにも行かず家にいること。タイの首都バンコクと同音なので、どこ行くのという問いにバンコクと答えると一瞬海外旅行に聞こえてから冗談だとわかる言葉遊びが肝。そう過ごす人はバンコク族と呼んだ。", "vi": "Viết tắt của bang-e kok bak-hyeo it-da (rúc trong phòng): nghỉ lễ hay cuối tuần mà chẳng đi đâu. Nó phát âm hệt Bangkok, nên trả lời Bangkok cho câu đi đâu thế sẽ nghe như đi nước ngoài trong một giây trước khi lộ ra là đùa. Người sống vậy gọi là bang-kok-jok."}}]'::jsonb, '방에 콕이라는 우리말 표현과 태국 수도 방콕의 소리가 같은 데서 나온 말장난이다. 언제 누가 처음 썼는지는 이 말의 유래를 정면으로 다룬 자료를 찾지 못해 확정할 수 없다. 다만 2008년 한국일보 휴가 특집 기사에 이미 낭만 방콕족이라는 표현이 제목에 쓰인 것으로 보아, 늦어도 2000년대 중후반에는 널리 통용되고 있었다.', '{"de": "Das Wortspiel beruht darauf, dass die koreanische Wendung bang-e kok (im Zimmer verschanzt) genauso klingt wie Bangkok. Keine Quelle dokumentiert direkt, wer es zuerst benutzte, daher laesst sich der Ursprung nicht festlegen. Eine Urlaubsreportage der Hankook Ilbo von 2008 trug Bang-kok-jok bereits in der Schlagzeile, es war also spaetestens Mitte bis Ende der 2000er weit verbreitet.", "en": "The pun rests on the Korean phrase bang-e kok (holed up in a room) sounding identical to Bangkok. No source directly documents who first used it or when, so the origin cannot be fixed. A 2008 Hankook Ilbo holiday feature already used bang-kok-jok in its headline, so it was clearly in wide circulation by the mid-to-late 2000s at the latest.", "es": "El juego se apoya en que la expresion coreana bang-e kok (metido en el cuarto) suena identica a Bangkok. Ninguna fuente documenta directamente quien lo uso primero ni cuando, asi que el origen no puede fijarse. Un reportaje vacacional del Hankook Ilbo de 2008 ya llevaba bang-kok-jok en el titular, de modo que a mas tardar a mediados o finales de los 2000 circulaba ampliamente.", "ja": "部屋にこもるという韓国語の言い回しとタイの首都バンコクが同音であることに基づく言葉遊び。誰がいつ最初に使ったかを正面から扱った資料が見つからず、由来は確定できない。ただ2008年の韓国日報の休暇特集記事の見出しに既にバンコク族という表現が使われており、遅くとも2000年代半ばから後半には広く通用していた。", "vi": "Trò chơi chữ dựa trên việc cụm tiếng Hàn bang-e kok (rúc trong phòng) phát âm y hệt Bangkok. Không nguồn nào ghi lại trực tiếp ai dùng đầu tiên và khi nào, nên không thể xác định gốc. Một bài đặc san kỳ nghỉ của Hankook Ilbo năm 2008 đã dùng bang-kok-jok ngay trên tít, cho thấy muộn nhất là giữa đến cuối thập niên 2000 nó đã lưu hành rộng rãi."}'::jsonb, '2000~2010년대에 휴가철마다 나오던 말이다. 지금도 통하긴 하지만, 코로나 이후 같은 뜻의 주력은 집콕으로 넘어갔고 집에만 있는 사람은 집돌이 집순이라고 부른다. 방콕은 윗세대 말투에 가깝게 들린다. 영어로 비슷한 말은 staycation이다.', '{"de": "Ein Klassiker jeder Urlaubssaison in den 2000ern und 2010ern. Es funktioniert noch, doch seit der Pandemie ist die Bedeutung zu jip-kok (zu Hause verschanzt) gewandert, und Stubenhocker heissen jip-dol-i oder jip-sun-i. Bang-kok klingt heute nach aelterer Generation. Das naechste englische Wort ist Staycation.", "en": "A staple of every holiday season through the 2000s and 2010s. It still communicates, but since the pandemic the same idea moved to jip-kok (holed up at home), and homebodies are called jip-dol-i or jip-sun-i. Bang-kok now reads as older-generation phrasing. The closest English is staycation.", "es": "Un clasico de cada temporada vacacional en los 2000 y 2010. Aun se entiende, pero desde la pandemia el peso paso a jip-kok (encerrado en casa), y a los caseros se les llama jip-dol-i o jip-sun-i. Bang-kok suena hoy a habla de generaciones mayores. El equivalente ingles mas cercano es staycation.", "ja": "2000-2010年代の休暇シーズンの定番語。今も通じるが、コロナ以降は同じ意味の主役が집콕(家にこもる)に移り、家にいる人は집돌이・집순이と呼ぶ。バンコクは上の世代の言い回しに聞こえる。英語で近いのはstaycation。", "vi": "Một từ quen thuộc mỗi mùa nghỉ suốt thập niên 2000 và 2010. Vẫn hiểu được, nhưng từ sau đại dịch, nghĩa này chuyển sang jip-kok (rúc ở nhà), còn người thích ở nhà gọi là jip-dol-i, jip-sun-i. Bang-kok giờ nghe như lối nói của thế hệ trước. Tiếng Anh gần nhất là staycation."}'::jsonb, array['혼밥', '아싸', '복세편살', '소확행', '워케이션']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Staycation / holed up at home"}, {"lang": "🇯🇵 JA", "text": "部屋にこもる休暇(バンコクと掛けた語)"}, {"lang": "🇨🇳 ZH", "text": "宅在家里(与曼谷谐音)"}, {"lang": "🇻🇳 VI", "text": "Nghỉ ở nhà (chơi chữ với Bangkok)"}, {"lang": "🇪🇸 ES", "text": "Vacaciones en casa (juego con Bangkok)"}, {"lang": "🇩🇪 DE", "text": "Urlaub daheim (Wortspiel mit Bangkok)"}]'::jsonb),
('542', '볼매', 'Bol-Mae', 'outdated-slang', 'love', '볼수록 매력 있다 — 두고 볼수록 좋아지는 사람·물건 칭찬', '{"de": "Je laenger man hinsieht, desto reizvoller — Lob fuer alles, was langsam waechst", "en": "The more you look, the more charming — praise for what grows on you", "es": "Cuanto mas lo miras, mas encanto tiene — elogio para lo que gana con el tiempo", "ja": "見れば見るほど魅力的 — じわじわ好きになる人やモノへの褒め言葉", "vi": "Càng nhìn càng cuốn — lời khen cho người hay thứ ngấm dần"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Anfangs fand ich es nichts, aber dieses Lied ist ein echtes Bol-mae.", "es": "Al principio no me decia nada, pero esta cancion es un autentico bol-mae.", "ja": "最初はいまいちだったけど、この曲マジでボルメ。", "vi": "Lúc đầu thấy thường, mà bài này đúng là bol-mae thật.", "eng": "I was not into it at first, but this song is a real bol-mae.", "kor": "처음엔 별로였는데 진짜 볼매다, 이 노래."}, {"de": "Sie ist ein Bol-mae. Auf Fotos merkt man es nicht, aber persoenlich schaut man staendig hin.", "es": "Ella es un bol-mae. En fotos no se nota, pero en persona no puedes dejar de mirarla.", "ja": "あの子ボルメだよ。写真じゃわからないけど実際に会うとつい目で追っちゃう。", "vi": "Nhỏ đó là bol-mae đấy. Nhìn ảnh thì không thấy, gặp ngoài đời cứ muốn nhìn hoài.", "eng": "She is a bol-mae. You cannot tell from photos, but in person you keep looking.", "kor": "걔 볼매야. 사진으로는 모르는데 실제로 보면 계속 눈이 가."}], "definition": "볼수록 매력 있다(또는 볼수록 매력 있는 사람)의 줄임말. 첫인상은 평범해도 자꾸 보다 보면 좋아지는 사람이나 물건을 칭찬할 때 썼다. 사람뿐 아니라 노래·옷·가게 같은 것에도 두루 붙였다.", "definition_i18n": {"de": "Kurzform fuer bol-su-rok mae-ryeok it-da (je oefter man hinsieht, desto reizvoller) oder fuer eine solche Person. Lob fuer jemanden oder etwas, dessen Reiz sich einschleicht statt sofort zu treffen. Wurde auf Lieder, Kleidung und Laeden ebenso angewandt wie auf Menschen.", "en": "Short for bol-su-rok mae-ryeok it-da (the more you see, the more charming) or the person that describes. Used to praise someone or something whose appeal sneaks up on you rather than hitting at first sight. Applied to songs, clothes and shops as freely as to people.", "es": "Abreviatura de bol-su-rok mae-ryeok it-da (cuanto mas lo ves, mas encanto tiene) o de la persona asi. Elogiaba a alguien o algo cuyo atractivo se cuela poco a poco en vez de golpear a primera vista. Se aplicaba igual a canciones, ropa y tiendas que a personas.", "ja": "見れば見るほど魅力がある(またはそういう人)の略。第一印象は普通でも見るほどに好きになる人やモノを褒めるときに使った。人だけでなく曲・服・店などにも広く付けた。", "vi": "Viết tắt của bol-su-rok mae-ryeok it-da (càng nhìn càng có sức hút) hoặc chính người như vậy. Dùng để khen người hay vật mà sức hút ngấm dần chứ không đập vào mắt ngay. Dùng cho bài hát, quần áo, quán xá cũng thoải mái như dùng cho người."}}]'::jsonb, '2000년대 후반~2010년대 초 인터넷 커뮤니티에서 퍼진 두 글자 줄임말 유행의 하나다. 이 시기에는 완소(완전 소중한), 강추(강력 추천)처럼 네 글자 이상을 두 글자로 잘라 쓰는 방식이 흔했고 볼매도 그 틀을 따랐다. 반대로 비꼬아 볼수록 매력 없다, 볼수록 매를 번다로 다시 푼 농담 용법도 함께 돌았다.', '{"de": "Eine der zweisilbigen Kurzformen, die Ende der 2000er und Anfang der 2010er die koreanischen Online-Foren ueberschwemmten, aus derselben Form wie Wan-so (voellig kostbar) oder Gang-chu (starke Empfehlung). Parallel kursierte eine sarkastische Gegenlesart: je laenger man hinsieht, desto reizloser, oder desto mehr Prügel verdient.", "en": "One of the two-syllable clippings that swept Korean online communities in the late 2000s and early 2010s, the same mould as wan-so (utterly precious) and gang-chu (strong recommendation). A sarcastic counter-reading also circulated, re-expanding it as the more you look, the less charming or the more you look, the more you deserve a smack.", "es": "Uno de los recortes de dos silabas que arrasaron en los foros coreanos a finales de los 2000 e inicios de los 2010, del mismo molde que wan-so (totalmente valioso) o gang-chu (recomendacion fuerte). Tambien circulo una relectura sarcastica: cuanto mas lo miras, menos encanto tiene, o cuanto mas lo miras, mas azotes merece.", "ja": "2000年代後半から2010年代初めにネットコミュニティで流行した二文字略語の一つで、ワンソ(完全に大切)やカンチュ(強力推薦)と同じ型。逆に皮肉って見るほど魅力がない、見るほど殴られるという再解釈のネタ用法も一緒に出回った。", "vi": "Một trong những từ rút gọn hai âm tiết tràn ngập cộng đồng mạng Hàn cuối thập niên 2000 đầu 2010, cùng khuôn với wan-so (vô cùng quý) hay gang-chu (đề cử mạnh). Song song còn có cách đọc châm biếm: càng nhìn càng kém duyên, hoặc càng nhìn càng đáng ăn đòn."}'::jsonb, '2010년대 초반에 흔했고 지금은 거의 쓰지 않는다. 요즘 같은 뜻으로는 매력 터진다, 추구미, 인생캐 같은 말이 각자 다른 각도로 그 자리를 나눠 가졌다. 지금 볼매라고 하면 알아듣긴 하지만 말투가 옛날 사람처럼 들린다.', '{"de": "Anfang der 2010er gelaeufig, heute kaum noch. Das Feld teilen sich nun Wendungen wie mae-ryeok teo-jin-da (vor Charme platzend), Chu-gu-mi und In-saeng-kae, je aus anderer Richtung. Man versteht Bol-mae noch, aber es klingt heute aelter.", "en": "Common in the early 2010s, barely used now. Today the same territory is split between phrases like mae-ryeok teo-jin-da (bursting with charm), chu-gu-mi and in-saeng-kae, each from a different angle. People still understand bol-mae, but saying it now marks you as older.", "es": "Frecuente a inicios de los 2010, hoy apenas se usa. Ese terreno se lo reparten ahora expresiones como mae-ryeok teo-jin-da (rebosa encanto), chu-gu-mi e in-saeng-kae, cada una desde un angulo. Se entiende, pero decirlo hoy te delata como mayor.", "ja": "2010年代前半によく使われ、今はほぼ使わない。今は魅力が爆発する、チュググミ、インセンケなどが別々の角度でその位置を分け合っている。ボルメと言えば通じるが、言い方が年配っぽく聞こえる。", "vi": "Phổ biến đầu thập niên 2010, nay gần như không dùng. Mảng nghĩa đó giờ chia cho mae-ryeok teo-jin-da (cuốn dã man), chu-gu-mi, in-saeng-kae, mỗi từ một góc. Người ta vẫn hiểu bol-mae, nhưng nói ra nghe hơi già."}'::jsonb, array['완소', '훈남', '훈녀', '추구미', '인생캐']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Grows on you / charming on second look"}, {"lang": "🇯🇵 JA", "text": "見るほど魅力的(じわ推し)"}, {"lang": "🇨🇳 ZH", "text": "越看越有魅力"}, {"lang": "🇻🇳 VI", "text": "Càng nhìn càng cuốn"}, {"lang": "🇪🇸 ES", "text": "Gana cuanto mas lo miras"}, {"lang": "🇩🇪 DE", "text": "Waechst einem ans Herz"}]'::jsonb),
('543', '뷁', 'Bwek', 'outdated-slang', NULL, '2000년대 초 인터넷을 지배한 한 글자 짜증', '{"de": "Der einsilbige Laut, der das koreanische Internet der frühen 2000er beherrschte", "en": "The one-syllable grunt that ruled the early-2000s Korean internet", "es": "El gruñido de una sílaba que dominó la internet coreana de los 2000", "ja": "2000年代初頭のネットを支配した一文字の不快音", "vi": "Tiếng càu nhàu một âm tiết thống trị mạng Hàn đầu 2000"}'::jsonb, '[뷐]', '[{"type": "감탄사", "examples": [{"de": "Schon morgens die U-Bahn rappelvoll — bwek.", "es": "Metro repleto a primera hora de la mañana… bwek.", "ja": "朝から満員電車とか、ブェク。", "vi": "Sáng sớm mà tàu điện đã chật cứng, bwek.", "eng": "Packed subway first thing in the morning — bwek.", "kor": "아침부터 지하철 만원이라니, 뷁."}, {"de": "Wer 뷁 tippt, outet sich sofort als 2000er-Relikt.", "es": "Escribir 뷁 es certificar al instante que eres de los 2000.", "ja": "뷁って書いたら即2000年代おじさん認定だよ", "vi": "Gõ 뷁 là tự nhận mình dân thập niên 2000 luôn", "eng": "Typing 뷁 is an instant badge of being a 2000s relic.", "kor": "뷁이라고 쓰면 바로 2000년대 아재 인증이지"}], "definition": "기분이 나쁘거나 언짢을 때 내뱉는 소리. 지금의 ''아 짜증'', ''킹받네'' 자리에 쓰이던 말로, 받침 ㄺ 때문에 발음 자체가 찌푸린 표정처럼 들리는 게 매력이었다. 2000년대 초중반 ''즐'', ''잼''과 함께 인터넷에서 가장 많이 쓰였다.", "definition_i18n": {"de": "Ein Laut, den man bei Ärger oder Unbehagen ausstößt — er besetzte den Platz des heutigen 아 짜증 oder 킹받네. Das sperrige End-ㄺ lässt das Wort selbst wie eine Grimasse klingen. Anfang bis Mitte der 2000er gehörte es neben 즐 und 잼 zu den meistgetippten Wörtern.", "en": "A sound you spit out when annoyed or put off — it occupied the slot today''s 아 짜증 or 킹받네 fills. The clotted ㄺ ending made the word itself sound like a scowl. In the early-to-mid 2000s it was one of the most-typed words online, alongside 즐 and 잼.", "es": "Sonido que se suelta al estar molesto o incómodo; ocupaba el lugar del actual 아 짜증 o 킹받네. La ㄺ final hace que la palabra suene como una mueca. A principios y mediados de los 2000 fue de las más tecleadas, junto a 즐 y 잼.", "ja": "不快なとき、気分が悪いときに吐き出す音。今の「아 짜증」「킹받네」の位置にあった語で、パッチムのㄺのせいで発音そのものがしかめっ面に聞こえるのが魅力だった。2000年代初中盤、「즐」「잼」と並びネットで最も使われた。", "vi": "Tiếng bật ra khi bực hoặc khó chịu — chiếm chỗ của 아 짜증 hay 킹받네 ngày nay. Phụ âm cuối ㄺ khiến chính cách phát âm nghe như đang nhăn mặt. Đầu-giữa thập niên 2000, đây là một trong những từ được gõ nhiều nhất, cùng 즐 và 잼."}}]'::jsonb, '2002년 발표된 노래의 가사 중 영어 ''break'' 부분이 논란이 되면서, 인터넷 이용자들이 이 발음을 ''브레이끼'', ''부레끼'' 등으로 흉내 내다가 한 글자로 뭉갠 표기 ''뷁''이 생겼다. 국립국어원 2003년 신어 자료집에 ''기분이 좋지 않을 때 내뱉는 소리''로 실렸고, 개방형 국어사전에도 감탄사로 등재돼 있다. 특정 가수를 조롱하던 맥락에서 출발했으나 그 맥락이 옅어지면서 말 자체도 함께 사라졌다.', '{"de": "2002 wurde das englische Wort ''break'' in einem Songtext zur Zielscheibe von Online-Spott; Nutzer ahmten die Aussprache als ''beureiggi'' oder ''bureggi'' nach und pressten sie schließlich in die eine Silbe 뷁. Es kam 2003 in den Neuwortbericht des Nationalinstituts für Koreanische Sprache als ''Laut bei schlechter Laune'' und steht als Interjektion in dessen offenem Wörterbuch. Entstanden aus dem Spott über einen Sänger, verschwand es mit diesem Kontext.", "en": "In 2002 the English word ''break'' in a song lyric became a target of online mockery; users imitated the pronunciation as ''beureiggi'' or ''bureggi'' and finally crushed it into the single syllable 뷁. It entered the National Institute of Korean Language''s 2003 new-word report as ''a sound uttered when in a bad mood'' and is listed as an interjection in the institute''s open dictionary. It began in the mockery of one singer, and faded out as that context faded.", "es": "En 2002, la palabra inglesa ''break'' de la letra de una canción se volvió blanco de burlas en línea; los usuarios imitaban la pronunciación como ''beureiggi'' o ''bureggi'' hasta aplastarla en la sílaba 뷁. Entró en el informe de neologismos de 2003 del Instituto Nacional de la Lengua Coreana como ''sonido que se emite de mal humor'' y figura como interjección en su diccionario abierto. Nació de la burla a un cantante y se apagó cuando ese contexto se apagó.", "ja": "2002年の楽曲の歌詞にある英語「break」がネットで揶揄の的になり、利用者がその発音を「ブレイッキ」「ブレッキ」と真似た末に一文字へ潰した表記が「뷁」。国立国語院の2003年新語資料集に「気分が良くないときに吐く音」として載り、開放型国語辞典にも感嘆詞として登録されている。特定歌手を嘲る文脈から生まれ、その文脈が薄れると語も消えた。", "vi": "Năm 2002, từ tiếng Anh ''break'' trong lời một bài hát trở thành mục tiêu chế giễu trên mạng; người dùng nhại cách phát âm thành ''beureiggi'', ''bureggi'' rồi nén lại thành một âm tiết 뷁. Nó vào báo cáo từ mới 2003 của Viện Quốc ngữ với nghĩa ''tiếng bật ra khi tâm trạng không tốt'' và có trong từ điển mở của viện với tư cách thán từ. Sinh ra từ việc chế giễu một ca sĩ, và tắt đi khi bối cảnh ấy tắt."}'::jsonb, '한 글자만 툭 던지는 게 전부다. 지금은 사실상 쓰지 않으며, 당시를 아는 사람에게 옛 인터넷 감성을 불러오는 용도로만 등장한다. 같은 자리에 요즘은 ''킹받네'', ''극혐'', ''아 짜증''이 들어간다.', '{"de": "Man wirft einfach die eine Silbe hin, mehr nicht. Heute praktisch tot; taucht nur noch als Nostalgie für Zeitzeugen auf. Moderne Entsprechungen: 킹받네, 극혐, 아 짜증.", "en": "You just drop the single syllable, nothing more. It is effectively dead today and surfaces only to evoke old-internet nostalgia for people who were there. Modern equivalents: 킹받네, 극혐, 아 짜증.", "es": "Se suelta la sílaba y ya. Hoy está prácticamente muerta y solo aparece como nostalgia para quienes vivieron esa época. Equivalentes actuales: 킹받네, 극혐, 아 짜증.", "ja": "一文字だけ放り投げるのが全て。今や事実上使われず、当時を知る人に昔のネットの空気を呼び起こすためだけに登場する。今の同ポジションは「킹받네」「극혐」「아 짜증」。", "vi": "Chỉ cần ném ra một âm tiết, hết. Nay gần như đã chết, chỉ xuất hiện để gợi hoài niệm internet xưa cho người từng trải. Tương đương hiện đại: 킹받네, 극혐, 아 짜증."}'::jsonb, array['즐', '킹받다']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Ugh / yuck (2000s internet grunt)"}, {"lang": "🇯🇵 JA", "text": "うげっ(2000年代ネット感嘆詞)"}, {"lang": "🇨🇳 ZH", "text": "呃(2000年代网络不爽用语)"}, {"lang": "🇻🇳 VI", "text": "Ực / chán (thán từ mạng thập niên 2000)"}, {"lang": "🇪🇸 ES", "text": "Puaj (gruñido de internet de los 2000)"}, {"lang": "🇩🇪 DE", "text": "Igitt (Internet-Laut der 2000er)"}]'::jsonb),
('544', '삼포세대', 'Sam-Po-Se-Dae', 'outdated-slang', NULL, '연애·결혼·출산을 포기한 청년 세대', '{"de": "Die Generation, die Beziehung, Heirat und Kinder aufgegeben hat", "en": "The generation that gave up dating, marriage and children", "es": "La generación que renunció a salir con alguien, casarse y tener hijos", "ja": "恋愛・結婚・出産を諦めた若者世代", "vi": "Thế hệ từ bỏ hẹn hò, kết hôn và sinh con"}'::jsonb, '[삼포세대]', '[{"type": "명사", "examples": [{"de": "Ich finde nicht mal einen Job, geschweige denn eine Beziehung — voll die Sampo-Generation.", "es": "Ni encuentro trabajo, ¿cómo voy a tener pareja? Generación sampo total.", "ja": "就職もできないのに恋愛どころじゃない、完全に三抛世代だよ", "vi": "Việc còn chưa có thì yêu đương gì, đúng chuẩn thế hệ sampo.", "eng": "I cannot even get a job, let alone date — total sampo generation.", "kor": "취업도 안 되는데 연애는 무슨, 완전 삼포세대지"}], "definition": "연애, 결혼, 출산 세 가지를 포기했거나 기약 없이 미루는 청년 세대를 가리키는 말. 한자로는 三抛世代로, 불안정한 일자리·학자금 대출·집값 부담이 이유로 꼽힌다. 2010년대 초중반 사회 논의의 핵심어였으나, 이후 오포·칠포·N포세대로 말이 옮겨 가면서 이 표현 자체는 잘 쓰이지 않게 됐다.", "definition_i18n": {"de": "Ein Begriff für junge Koreaner, die drei Dinge aufgegeben oder auf unbestimmte Zeit verschoben haben: Beziehung, Heirat und Kinder (三抛世代). Als Gründe gelten unsichere Jobs, Studienschulden und Wohnkosten. Ein Schlüsselwort der frühen 2010er-Debatte, später von 오포, 칠포 und N포세대 verdrängt.", "en": "A term for young Koreans who have abandoned, or indefinitely postponed, three things: dating, marriage and having children (三抛世代). Unstable jobs, student debt and housing costs are the cited causes. A keyword of early-2010s social debate, it has since been displaced by 오포, 칠포 and N포세대.", "es": "Término para los jóvenes coreanos que han renunciado —o aplazado sin fecha— a tres cosas: pareja, matrimonio e hijos (三抛世代). Se citan como causas el empleo precario, la deuda estudiantil y el precio de la vivienda. Fue palabra clave del debate social de principios de los 2010, luego desplazada por 오포, 칠포 y N포세대.", "ja": "恋愛・結婚・出産の三つを諦めた、あるいは無期限に先送りする若者世代を指す語。漢字で三抛世代。不安定な雇用、奨学金ローン、住宅費の負担が理由に挙げられる。2010年代前半の社会的議論のキーワードだったが、その後五抛・七抛・N抛世代へ言葉が移り、この表現自体はあまり使われなくなった。", "vi": "Từ chỉ những người trẻ Hàn đã từ bỏ, hoặc hoãn vô thời hạn, ba thứ: hẹn hò, kết hôn và sinh con (三抛世代). Nguyên nhân được nêu là việc làm bấp bênh, nợ học phí và giá nhà. Từng là từ khóa của tranh luận xã hội đầu thập niên 2010, sau bị 오포, 칠포 và N포세대 thay thế."}}]'::jsonb, '2011년 경향신문이 특별취재 기획 ''복지국가를 말한다'' 시리즈에서 처음 쓴 말로 알려져 있다. 국가가 책임지지 않는 복지 부담이 가족에게 쏠려 전통적인 가족 형성 공식이 무너졌음을 보이려는 취지였다. 이후 인간관계·내 집 마련을 더한 ''오포세대'', 꿈·희망까지 더한 ''칠포세대'', 개수를 특정하지 않는 ''N포세대''로 확장됐다.', '{"de": "Der Begriff wird einer Rechercheserie der Kyunghyang Shinmun von 2011 zugeschrieben, ''Über den Wohlfahrtsstaat'', die damit zeigte, wie die vom Staat nicht getragene Wohlfahrtslast auf Familien fiel, bis der übliche Weg zur Familiengründung zerbrach. Später folgten 오포세대 (plus Beziehungen und Wohneigentum), 칠포세대 (plus Träume und Hoffnung) und N포세대 (ohne feste Zahl).", "en": "It is credited to a 2011 Kyunghyang Shinmun investigative series, ''Talking About the Welfare State'', which used it to show that welfare burdens the state would not carry had fallen on families until the conventional path to forming one broke down. Later expansions added relationships and home ownership (오포세대), then dreams and hope (칠포세대), then an unspecified number (N포세대).", "es": "Se atribuye a una serie de investigación de 2011 del Kyunghyang Shinmun, ''Hablemos del Estado del bienestar'', que lo usó para mostrar cómo la carga del bienestar que el Estado no asumía recaía en las familias hasta romper la vía tradicional de formarlas. Después llegaron 오포세대 (más relaciones y vivienda), 칠포세대 (más sueños y esperanza) y N포세대 (sin número fijo).", "ja": "2011年、京郷新聞の特別取材企画「福祉国家を語る」シリーズで初めて使われたとされる。国が担わない福祉の負担が家族に集中し、従来の家族形成の公式が崩れたことを示す趣旨だった。のちに人間関係・マイホームを加えた「五抛世代」、夢・希望まで加えた「七抛世代」、数を特定しない「N抛世代」へ広がった。", "vi": "Từ này được cho là xuất hiện lần đầu trong loạt bài điều tra năm 2011 của Kyunghyang Shinmun, ''Bàn về nhà nước phúc lợi'', nhằm cho thấy gánh nặng phúc lợi mà nhà nước không gánh đã dồn lên các gia đình cho tới khi con đường lập gia đình truyền thống đổ vỡ. Sau đó mở rộng thành 오포세대 (thêm quan hệ và nhà ở), 칠포세대 (thêm ước mơ và hy vọng), rồi N포세대 (không định số)."}'::jsonb, '자기 처지를 자조할 때나 청년 문제를 이야기할 때 쓴다. 지금은 ''N포세대''가 더 자주 쓰여, 삼포세대는 2010년대 초를 가리키는 말처럼 들린다.', '{"de": "Wird genutzt, um über die Not junger Leute zu sprechen oder die eigene Lage selbstironisch zu beschreiben. Heute sagt man eher N포세대, weshalb 삼포세대 nach den frühen 2010ern klingt.", "en": "Used to talk about youth hardship or to describe your own situation wryly. N포세대 is the common term now, so 삼포세대 reads as shorthand for the early 2010s.", "es": "Se usa al hablar de las dificultades juveniles o para describir la propia situación con ironía. Hoy se dice más N포세대, así que 삼포세대 suena a los primeros 2010.", "ja": "自分の境遇を自嘲するときや若者問題を語るときに使う。今は「N抛世代」の方がよく使われ、三抛世代は2010年代初めを指す言葉のように聞こえる。", "vi": "Dùng khi nói về khó khăn của giới trẻ hoặc tự giễu hoàn cảnh mình. Giờ N포세대 phổ biến hơn, nên 삼포세대 nghe như cách gọi đầu thập niên 2010."}'::jsonb, array['이생망', '헬조선', '열정페이']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "The give-up-three generation (dating, marriage, kids)"}, {"lang": "🇯🇵 JA", "text": "三抛世代(恋愛・結婚・出産を諦めた世代)"}, {"lang": "🇨🇳 ZH", "text": "三抛世代(放弃恋爱、结婚、生育)"}, {"lang": "🇻🇳 VI", "text": "Thế hệ ba từ bỏ (yêu, cưới, sinh con)"}, {"lang": "🇪🇸 ES", "text": "Generación de las tres renuncias"}, {"lang": "🇩🇪 DE", "text": "Drei-Verzicht-Generation"}]'::jsonb),
('545', '실검', 'Sil-Geom', 'outdated-slang', NULL, '''실시간 검색어''의 줄임말', '{"de": "Kurzform für ''Echtzeit-Suchbegriffe''", "en": "Short for ''real-time search rankings''", "es": "Abreviatura de ''búsquedas en tiempo real''", "ja": "「リアルタイム検索ワード」の略", "vi": "Viết tắt của ''từ khóa tìm kiếm thời gian thực''"}'::jsonb, '[실껌]', '[{"type": "명사", "examples": [{"de": "Der Schauspieler soll auf Platz eins der Echtzeit-Suche gewesen sein.", "es": "Dicen que ese actor llegó al número uno de las búsquedas en tiempo real.", "ja": "あの俳優、リアルタイム検索1位取ったんだって", "vi": "Nghe nói diễn viên đó đứng nhất bảng tìm kiếm thời gian thực.", "eng": "That actor apparently hit number one on the real-time search list.", "kor": "그 배우 실검 1위 찍었대"}], "definition": "포털 사이트가 보여 주던 ''실시간 검색어'' 순위의 줄임말. 지금 사람들이 무엇을 검색하는지 1위부터 줄 세워 보여 주던 기능으로, 여기 오르는 것이 화제성의 척도였다. 네이버가 2021년 2월 이 서비스를 없애면서 가리킬 대상 자체가 사라졌다.", "definition_i18n": {"de": "Kurzform für das Echtzeit-Suchranking, das Portale früher anzeigten — eine Live-Liste dessen, wonach gerade gesucht wurde; dort aufzutauchen galt als Maß für Aufmerksamkeit. Naver stellte den Dienst im Februar 2021 ein, das Bezeichnete gibt es also nicht mehr.", "en": "Short for the real-time search ranking a portal used to display — a live top-ten of what people were searching, where landing on the list was the measure of being a hot topic. Naver scrapped the service in February 2021, so the thing the word named no longer exists.", "es": "Abreviatura del ranking de búsquedas en tiempo real que mostraban los portales: una lista en vivo de lo más buscado, donde aparecer era la medida de estar de moda. Naver eliminó el servicio en febrero de 2021, así que aquello que nombraba ya no existe.", "ja": "ポータルサイトが表示していた「リアルタイム検索ワード」ランキングの略。今みんなが何を検索しているかを1位から並べる機能で、そこに載ることが話題性の物差しだった。ネイバーが2021年2月にこのサービスを廃止し、指す対象自体がなくなった。", "vi": "Viết tắt của bảng xếp hạng từ khóa tìm kiếm thời gian thực mà các cổng thông tin từng hiển thị — danh sách trực tiếp những gì người ta đang tìm, lọt vào đó là thước đo độ hot. Naver bỏ dịch vụ này vào tháng 2/2021 nên thứ mà từ này gọi tên đã không còn."}}]'::jsonb, '''실시간 검색어''의 앞 글자를 딴 줄임말이다. 네이버는 2021년 2월 25일 ''정보의 다양성 확보''를 이유로 이 서비스를 종료했는데, 언론은 같은 단어를 반복 검색해 순위를 올리는 여론 조작과 지나친 상업성 논란이 배경이라고 짚었다. 서비스가 사라지면서 이 말도 함께 옛말이 됐다.', '{"de": "Eine Abkürzung von 실시간 검색어 (Echtzeit-Suchbegriffe). Naver beendete den Dienst am 25. Februar 2021 mit Verweis auf die ''Sicherung der Informationsvielfalt''; die Presse nannte als eigentlichen Hintergrund Manipulation — ein Wort wiederholt zu suchen, um es hochzutreiben — und übermäßige Kommerzialisierung. Mit der Funktion veraltete auch das Wort.", "en": "An abbreviation of 실시간 검색어 (real-time search terms). Naver ended the service on 25 February 2021, citing ''securing diversity of information''; press coverage pointed to manipulation — repeatedly searching a term to push it up — and complaints of commercialism as the real backdrop. The word aged out along with the feature.", "es": "Abreviatura de 실시간 검색어 (términos de búsqueda en tiempo real). Naver cerró el servicio el 25 de febrero de 2021 alegando ''garantizar la diversidad informativa''; la prensa apuntó a la manipulación —buscar un término repetidamente para subirlo— y al exceso de comercialismo como trasfondo real. La palabra envejeció junto con la función.", "ja": "「リアルタイム検索ワード」の頭を取った略語。ネイバーは2021年2月25日、「情報の多様性確保」を理由にこのサービスを終了したが、報道は同じ語を繰り返し検索して順位を上げる世論操作や過度な商業性の議論が背景だと指摘した。サービスの消滅とともにこの語も古語になった。", "vi": "Viết tắt của 실시간 검색어 (từ khóa tìm kiếm thời gian thực). Naver đóng dịch vụ ngày 25/2/2021 với lý do ''bảo đảm sự đa dạng thông tin''; báo chí chỉ ra bối cảnh thật là nạn thao túng — tìm đi tìm lại một từ để đẩy hạng — và sự thương mại hóa quá mức. Từ này lỗi thời theo tính năng đó."}'::jsonb, '''실검 1위'', ''실검에 떴다''처럼 화제가 됐다는 뜻으로 썼다. 표준국어대사전에도 ''실검(實檢)''이 있지만 ''검사함''이라는 전혀 다른 말이니 헷갈리지 말 것. 지금 같은 뜻으로는 유튜브·SNS의 ''인급동''이나 ''트렌딩''이 쓰인다.', '{"de": "Wurde als 실검 1위 oder 실검에 떴다 benutzt, um zu sagen, dass etwas eingeschlagen hat. Achtung: Das Standardwörterbuch führt ein anderes 실검 (實檢, ''Prüfung'') — ohne Bezug. Heute sagt man 인급동 oder ''trending''.", "en": "Used as 실검 1위 or 실검에 떴다 to say something blew up. Note the Standard Korean Dictionary lists a different 실검 (實檢, ''inspection'') — unrelated. For today''s equivalent people say 인급동 or ''trending''.", "es": "Se usaba como 실검 1위 o 실검에 떴다 para decir que algo había estallado. Ojo: el diccionario estándar recoge otro 실검 (實檢, ''inspección''), sin relación. Hoy se dice 인급동 o ''trending''.", "ja": "「실검1位」「실검に上がった」のように話題になったという意味で使った。標準国語大辞典にも「실검(實檢)」があるが「検査すること」という全く別の語なので混同しないこと。今は同じ意味でYouTubeやSNSの「인급동」「トレンド」が使われる。", "vi": "Dùng kiểu 실검 1위 hay 실검에 떴다 để nói cái gì đó gây sốt. Lưu ý từ điển chuẩn có một 실검 khác (實檢, ''kiểm tra''), không liên quan. Nghĩa tương đương ngày nay là 인급동 hay ''trending''."}'::jsonb, array['인급동', '어그로', '역주행', '박제']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Real-time search rankings (defunct)"}, {"lang": "🇯🇵 JA", "text": "リアルタイム検索ワード(廃止)"}, {"lang": "🇨🇳 ZH", "text": "实时搜索排行(已停用)"}, {"lang": "🇻🇳 VI", "text": "Bảng tìm kiếm thời gian thực (đã bỏ)"}, {"lang": "🇪🇸 ES", "text": "Búsquedas en tiempo real (extinto)"}, {"lang": "🇩🇪 DE", "text": "Echtzeit-Suchranking (abgeschafft)"}]'::jsonb),
('546', '십장생', 'Sip-Jang-Saeng', 'outdated-slang', 'work', '십 대도 장차 백수를 생각해야 한다 — 이태백의 후속 자조어', '{"de": "Schon Teenager sollten mit Arbeitslosigkeit rechnen — die Fortsetzung von I-tae-baek", "en": "Even teenagers should start planning on being jobless — the sequel to i-tae-baek", "es": "Hasta los adolescentes deben contar con el paro — la secuela de i-tae-baek", "ja": "十代も将来の無職を考えるべき — イテベクの続編的自嘲語", "vi": "Ngay cả tuổi mười mấy cũng phải tính chuyện thất nghiệp — phần tiếp theo của i-tae-baek"}'::jsonb, '[십짱생]', '[{"type": "명사", "examples": [{"de": "Erst I-tae-baek, dann Sip-jang-saeng — damals war es also auch schon uebel.", "es": "Primero i-tae-baek y luego sip-jang-saeng: la cosa tambien estaba dura entonces.", "ja": "イテベクの次がシプチャンセンって、あの頃もなかなかだったな。", "vi": "Sau i-tae-baek là sip-jang-saeng, hồi đó cũng chật vật ra phết.", "eng": "First i-tae-baek, then sip-jang-saeng — things were pretty rough back then too.", "kor": "이태백 다음이 십장생이라니, 그때도 어지간했네."}, {"de": "Auf Opas Wandschirm ist das Sip-jang-saeng gemalt — und der Slang bedeutet genau das Gegenteil.", "es": "El biombo del abuelo tiene pintado el sip-jang-saeng, y resulta que la jerga significa justo lo contrario.", "ja": "おじいちゃんの部屋の屏風に十長生が描いてあるけど、意味が正反対だったんだ。", "vi": "Bình phong phòng ông có vẽ sip-jang-saeng, hoá ra nghĩa lóng lại ngược hẳn.", "eng": "Grandpa folding screen has the sip-jang-saeng painted on it — turns out the slang means the exact opposite.", "kor": "할아버지 방 병풍에 십장생 그려져 있는데, 뜻이 완전 반대였네."}], "definition": "십 대도 장차 백수를 생각해야 한다를 줄인 말. 청년 취업난이 이십 대를 넘어 십 대까지 내려왔다는 뜻으로 쓴 자조적 신조어다. 원래 십장생은 오래 사는 열 가지(해·산·물·돌·구름·소나무·불로초·거북·학·사슴)를 뜻하는 복스러운 말인데, 그 이름을 그대로 빌려 정반대로 비튼 것이 이 말의 핵심 농담이다.", "definition_i18n": {"de": "Kurzform fuer selbst Teenager sollten mit Arbeitslosigkeit planen. Es besagt, dass die Jugendarbeitslosigkeit unter die Zwanziger bis in die Teenagerjahre gesunken war. Das urspruengliche Sip-jang-saeng bezeichnet die zehn Symbole der Langlebigkeit (Sonne, Berg, Wasser, Stein, Wolke, Kiefer, Unsterblichkeitskraut, Schildkroete, Kranich, Hirsch) — ein Glueckswort, und genau dieses Glueckswort fuer das Gegenteil zu kapern ist der ganze Witz.", "en": "Short for even teenagers should start planning on being jobless. It says the youth job crisis had sunk below the twenties into the teens. The original sip-jang-saeng means the ten symbols of longevity (sun, mountain, water, stone, cloud, pine, herb of immortality, turtle, crane, deer) — an auspicious word, and hijacking that lucky name for the opposite meaning is the whole joke.", "es": "Abreviatura de hasta los adolescentes deben contar con quedarse sin empleo. Señala que la crisis laboral juvenil bajo de los veinte a la adolescencia. El sip-jang-saeng original designa los diez simbolos de longevidad (sol, montaña, agua, piedra, nube, pino, hierba de la inmortalidad, tortuga, grulla, ciervo), una palabra de buen augurio: secuestrar ese nombre afortunado para el sentido contrario es toda la gracia.", "ja": "十代も将来の無職を考えるべきの略。就職難が二十代を越えて十代にまで下りてきたという自嘲語。本来の十長生は長寿を象徴する十のもの(日・山・水・石・雲・松・不老草・亀・鶴・鹿)を指すめでたい語で、その縁起の良い名を正反対の意味に横取りしたのがこの語の笑いどころ。", "vi": "Viết tắt của ngay cả tuổi mười mấy cũng phải tính chuyện thất nghiệp. Ý nói khủng hoảng việc làm đã tụt từ tuổi hai mươi xuống tuổi thiếu niên. Sip-jang-saeng gốc chỉ mười biểu tượng trường thọ (mặt trời, núi, nước, đá, mây, thông, cỏ bất tử, rùa, hạc, hươu) — một từ cát tường, và việc mượn cái tên may mắn ấy cho nghĩa ngược lại chính là điểm gây cười."}}]'::jsonb, 'IMF 외환위기 이후 2000년대 초중반, 이태백(이십 대 태반이 백수)·이구백(이십 대 구십 퍼센트가 백수)에 이어 나온 같은 계열의 숫자·한자 말장난 신조어다. 문화일보·시사포커스 등 당시 신조어 기사에서 청년실업 자조어 묶음으로 함께 소개됐다. 풀어쓴 원문은 십대 장래 백수 생각으로 적은 매체도 있어 표현이 조금씩 다르다.', '{"de": "Entstand Mitte der 2000er nach I-tae-baek (Haelfte der Zwanzigjaehrigen arbeitslos) und I-gu-baek (90 Prozent arbeitslos), aus derselben Familie von Zahlen- und Hanja-Wortspielen nach der IMF-Krise. Die damalige Presse stellte das ganze Set als Galgenhumor zur Jugendarbeitslosigkeit vor. Die ausgeschriebene Form variiert je nach Medium leicht.", "en": "It followed i-tae-baek (half of twentysomethings jobless) and i-gu-baek (90 percent of twentysomethings jobless) in the mid-2000s, part of the same family of numeric and hanja puns born after the IMF crisis. Contemporary press pieces introduced the whole set together as youth-unemployment gallows humor. Some outlets spelled the expansion slightly differently.", "es": "Surgio a mediados de los 2000 tras i-tae-baek (mitad de veinteaneros en paro) e i-gu-baek (90 por ciento en paro), dentro de la misma familia de juegos numericos y de hanja nacidos tras la crisis del FMI. La prensa de la epoca presentaba el conjunto como humor negro sobre el paro juvenil. Algunos medios desarrollaban la frase de forma ligeramente distinta.", "ja": "IMF通貨危機後の2000年代中頃、イテベク(二十代の大半が無職)、イグベク(二十代の九十パーセントが無職)に続いて生まれた同系統の数字・漢字の言葉遊び。当時の文化日報や時事フォーカスなどの新造語記事で若者失業の自嘲語としてまとめて紹介された。元の展開形の表記は媒体によって少し異なる。", "vi": "Ra đời giữa thập niên 2000, tiếp nối i-tae-baek (quá nửa tuổi hai mươi thất nghiệp) và i-gu-baek (90 phần trăm thất nghiệp), cùng họ với các trò chơi chữ số và Hán tự sinh ra sau khủng hoảng IMF. Báo chí đương thời giới thiệu cả cụm này như tiếng cười chua chát về thất nghiệp trẻ. Cách diễn giải đầy đủ ở mỗi báo hơi khác nhau."}'::jsonb, '2000년대 신문·방송 신조어 코너의 단골이었지만 지금은 거의 사어다. 지금 이 말을 들으면 대부분의 한국인은 병풍·자수에 나오는 전통 문양 십장생부터 떠올린다. 따라서 이 슬랭 뜻으로 쓰려면 앞뒤에 이태백 같은 동시대 말을 같이 놓아야 통한다.', '{"de": "Ein Dauergast in Neologismus-Rubriken der 2000er, heute praktisch tot. Sagt man es heute, denken die meisten Koreaner an das traditionelle Langlebigkeitsmotiv auf Wandschirmen und Stickereien. Fuer den Slang-Sinn muss man es praktisch neben ein Zeitwort wie I-tae-baek stellen.", "en": "A regular in 2000s newspaper and TV neologism segments, now essentially dead. Say it today and most Koreans will picture the traditional longevity motif on folding screens and embroidery instead. To use the slang sense you basically have to set it next to a period word like i-tae-baek.", "es": "Habitual en las secciones de neologismos de prensa y television de los 2000, hoy practicamente muerto. Si lo dices ahora, la mayoria de los coreanos pensara en el motivo tradicional de longevidad de biombos y bordados. Para usar el sentido jergal casi hay que ponerlo junto a una palabra de epoca como i-tae-baek.", "ja": "2000年代の新聞・放送の新造語コーナーの常連だったが、今はほぼ死語。今これを聞くと大半の韓国人は屏風や刺繍の伝統文様の十長生を思い浮かべる。スラングの意味で使うにはイテベクのような同時代語を並べる必要がある。", "vi": "Từng là khách quen của các mục từ mới trên báo đài thập niên 2000, nay gần như chết hẳn. Nói bây giờ, đa số người Hàn sẽ nghĩ tới hoạ tiết trường thọ truyền thống trên bình phong và đồ thêu. Muốn dùng nghĩa lóng thì hầu như phải đặt cạnh một từ cùng thời như i-tae-baek."}'::jsonb, array['이퇴백', '헬조선', '쉬었음 청년']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Even teens should expect joblessness"}, {"lang": "🇯🇵 JA", "text": "十代も将来の無職を覚悟(自嘲語)"}, {"lang": "🇨🇳 ZH", "text": "连十几岁也该做好失业准备"}, {"lang": "🇻🇳 VI", "text": "Tuổi mười mấy cũng phải tính thất nghiệp"}, {"lang": "🇪🇸 ES", "text": "Hasta los adolescentes al paro"}, {"lang": "🇩🇪 DE", "text": "Schon Teenager planen Arbeitslosigkeit ein"}]'::jsonb),
('547', '엣지있다', 'Et-ji-it-da', 'outdated-slang', NULL, '2009년을 지배한 ''감각 있다''는 말', '{"de": "Die Art, 2009 zu sagen, dass etwas Pfiff hat", "en": "The 2009 way to say something has flair", "es": "La forma de 2009 de decir que algo tiene estilo", "ja": "2009年を席巻した「センスがある」という言い方", "vi": "Cách nói ''có gu'' thống trị năm 2009"}'::jsonb, NULL, '[{"type": "형용사", "examples": [{"de": "Der Mantel hat echt Pfiff.", "es": "Ese abrigo tiene un estilo brutal.", "ja": "そのコート、ほんとにセンスある。", "vi": "Cái áo khoác đó đúng là có gu thật.", "eng": "That coat really has flair.", "kor": "그 코트 진짜 엣지있다."}, {"de": "''Mit Edge''? Das ist doch Sprech von 2009.", "es": "¿''Con edge''? Eso es hablar como en 2009.", "ja": "「エッジよく」とか、完全に2009年の言い回しじゃん", "vi": "''Cho có edge'' á? Đúng giọng năm 2009 luôn", "eng": "''With edge''? That is pure 2009 talk.", "kor": "엣지있게라니, 완전 2009년 말투잖아"}], "definition": "모서리를 뜻하는 영어 edge에서 온 말로, 흐릿하지 않고 뚜렷하게 개성이 살아 있다는 뜻이다. ''감각 있다'', ''스타일 있다'', ''남들과 다르다''를 한 단어로 압축한 칭찬. 옷·머리·인테리어처럼 보이는 것을 평할 때 주로 썼다.", "definition_i18n": {"de": "Vom englischen edge: nicht vage oder brav, sondern markant eigen. Ein Kompliment, das ''hat Geschmack'', ''hat Stil'' und ''fällt auf'' in einem Wort bündelt. Angewendet vor allem auf Sichtbares — Kleidung, Frisur, Einrichtung.", "en": "From the English edge: not vague or safe, but sharply distinctive. A compliment compressing ''has taste'', ''has style'' and ''stands out'' into one word. It was applied mostly to visible things — clothes, hair, interiors.", "es": "Del inglés edge: nada difuso ni seguro, sino marcadamente distintivo. Un piropo que comprime ''tiene gusto'', ''tiene estilo'' y ''destaca'' en una palabra. Se aplicaba sobre todo a lo visible: ropa, peinado, interiorismo.", "ja": "角を意味する英語 edge から来た語で、ぼんやりせず個性がくっきり立っているという意味。「センスがある」「スタイルがある」「他と違う」を一語に圧縮した褒め言葉。服・髪・インテリアなど見た目を評するときに主に使った。", "vi": "Từ tiếng Anh edge: không mờ nhạt hay an toàn mà nổi bật rõ nét. Một lời khen gói gọn ''có gu'', ''có phong cách'' và ''khác biệt'' vào một từ. Chủ yếu dùng để nhận xét những gì nhìn thấy được — quần áo, tóc, nội thất."}}]'::jsonb, '원래 광고·패션업계에서 ''뚜렷하고 두드러진''이라는 뜻으로 쓰던 은어였다. ''유니크하다''가 식상해지자 그 자리를 대신해 쓰이기 시작했다고 전해진다. 2009년 패션지 편집장이 주인공인 드라마 ''스타일''에서 배우 김혜수가 말끝마다 ''엣지있게''를 반복하면서 그해 최고 유행어가 됐고, 의학 기사 제목에까지 쓰일 만큼 번졌다. 유행이 워낙 강했던 탓에 열기가 식자마자 오히려 촌스러운 말로 굳어졌다. 외래어 표기법상 올바른 표기는 ''에지''지만 실제로는 ''엣지''로 쓰였다.', '{"de": "Entstand als Jargon der Werbe- und Modebranche für ''klar konturiert und auffällig'' und füllte die Lücke, die das abgenutzte 유니크하다 hinterließ. 2009 ließ die Serie Style über eine Modemagazin-Chefredakteurin Schauspielerin Kim Hye-soo jeden zweiten Satz mit ''엣지있게'' beenden — das Schlagwort des Jahres, das bis in Überschriften medizinischer Artikel vordrang. Die Mode brannte so heiß, dass das Wort mit dem Abkühlen sofort altbacken klang. Normgerecht wäre 에지, geschrieben wurde aber 엣지.", "en": "It began as advertising and fashion-industry jargon meaning ''clear-cut and striking'', reportedly filling the slot left by the worn-out 유니크하다. In 2009 the drama Style, about a fashion magazine editor, had actress Kim Hye-soo end every other sentence with ''엣지있게'', making it the catchphrase of the year — it spread as far as headlines on medical articles. The fad burned so hot that the moment it cooled, the word flipped into sounding dated. The prescriptively correct spelling is 에지, but in practice everyone wrote 엣지.", "es": "Nació como jerga publicitaria y de moda con el sentido de ''nítido y llamativo'', ocupando el hueco que dejó el gastado 유니크하다. En 2009, la serie Style, sobre una editora de revista de moda, hizo que la actriz Kim Hye-soo rematara casi cada frase con ''엣지있게'', convirtiéndola en la muletilla del año; llegó hasta titulares de artículos médicos. La moda ardió tan fuerte que, al enfriarse, la palabra pasó a sonar anticuada. La grafía normativa es 에지, pero en la práctica todos escribían 엣지.", "ja": "もともと広告・ファッション業界で「はっきりしていて際立つ」の意味で使われた隠語。「ユニークだ」が陳腐化した後釜として使われ始めたと伝えられる。2009年、ファッション誌編集長が主人公のドラマ「スタイル」で女優キム・ヘスが語尾ごとに「エッジよく」を連発し、その年最高の流行語に。医療記事の見出しにまで使われるほど広まった。流行があまりに激しく、熱が冷めた途端に逆にダサい言葉として固まった。外来語表記法上の正しい表記は「에지」だが実際は「엣지」が使われた。", "vi": "Vốn là tiếng lóng của giới quảng cáo và thời trang, nghĩa ''rõ nét và nổi bật'', được cho là thế chỗ cho 유니크하다 đã nhàm. Năm 2009, bộ phim Style về nữ tổng biên tập tạp chí thời trang khiến diễn viên Kim Hye-soo kết mỗi câu bằng ''엣지있게'', biến nó thành câu cửa miệng của năm — lan tới cả tiêu đề bài báo y khoa. Cơn sốt mạnh đến mức vừa nguội đi thì từ này lập tức thành quê mùa. Chính tả chuẩn là 에지, nhưng thực tế ai cũng viết 엣지."}'::jsonb, '''엣지있다'', ''엣지있게'', 명사로 ''엣지''만 떼어 ''엣지가 없다''처럼도 썼다. 지금 진지하게 쓰면 2009년에서 온 사람 취급을 받으므로, 같은 뜻으로는 ''힙하다'', ''감각 있다'', ''재질 좋다''를 쓴다. 어느 쪽으로 검색해도 이 항목 하나로 모이도록 ''에지있다'', ''엣지있게''도 같은 말로 묶어 두었다.', '{"de": "Verwendet als 엣지있다, 엣지있게 oder als bloßes Nomen in 엣지가 없다 (keine Edge). Wer es heute ernst meint, outet sich als Gast aus 2009 — nimm 힙하다, 감각 있다 oder 재질 좋다. 에지있다 und 엣지있게 sind hier mit abgelegt, jede Schreibweise führt also zu diesem einen Eintrag.", "en": "Used as 엣지있다, 엣지있게, or as the bare noun in 엣지가 없다 (no edge). Saying it earnestly today marks you as a visitor from 2009 — use 힙하다, 감각 있다 or 재질 좋다 instead. 에지있다 and 엣지있게 are filed here too, so either spelling finds this one entry.", "es": "Se usa como 엣지있다, 엣지있게, o solo el sustantivo en 엣지가 없다 (sin edge). Decirlo en serio hoy te delata como visitante de 2009; usa 힙하다, 감각 있다 o 재질 좋다. 에지있다 y 엣지있게 están recogidas aquí, así que cualquier grafía lleva a esta única entrada.", "ja": "「엣지있다」「엣지있게」、名詞だけ取って「엣지가 없다」のようにも使った。今まじめに使うと2009年から来た人扱いされるので、同じ意味なら「힙하다」「감각 있다」「재질 좋다」を使う。「에지있다」「엣지있게」もこの項目にまとめてあり、どちらで検索しても同じ一件に行き着く。", "vi": "Dùng dạng 엣지있다, 엣지있게, hoặc chỉ danh từ trong 엣지가 없다 (không có edge). Nói nghiêm túc bây giờ là lộ ngay dân từ 2009 — hãy dùng 힙하다, 감각 있다 hay 재질 좋다. 에지있다 và 엣지있게 cũng gộp ở đây nên tra cách nào cũng ra đúng một mục."}'::jsonb, array['재질', '쌈뽕', '꾸안꾸']::text[], array['에지있다', '엣지있게', '엣지']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "To have edge / flair (2009 catchphrase)"}, {"lang": "🇯🇵 JA", "text": "エッジがある(センスがいい・2009年流行語)"}, {"lang": "🇨🇳 ZH", "text": "有格调、有个性(2009年流行语)"}, {"lang": "🇻🇳 VI", "text": "Có gu, có chất (câu cửa miệng 2009)"}, {"lang": "🇪🇸 ES", "text": "Tener estilo / edge (muletilla de 2009)"}, {"lang": "🇩🇪 DE", "text": "Pfiff haben (Schlagwort von 2009)"}]'::jsonb),
('548', '열폭', 'Yeol-pok', 'outdated-slang', NULL, '''열등감 폭발'' — 질투에 못 이겨 화내는 것', '{"de": "''Minderwertigkeitskomplex, explodiert'' — vor Neid ausrasten", "en": "''Inferiority complex, detonated'' — lashing out from envy", "es": "''Complejo de inferioridad, detonado'': estallar de envidia", "ja": "「劣等感爆発」——嫉妬に耐えかねて怒ること", "vi": "''Mặc cảm bùng nổ'' — nổi khùng vì ghen tị"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Man merkt genau, dass er nur vor Neid kocht, weil jemand anders Erfolg hat.", "es": "Se nota que está ardiendo de envidia porque a otro le va bien.", "ja": "人が成功したから劣等感爆発してるの丸わかり。", "vi": "Thấy rõ là đang cay vì người ta thành công.", "eng": "You can tell they are just seething because someone else is doing well.", "kor": "남 잘되니까 열폭하는 거 티 난다."}, {"de": "Sagt man heute nicht eher 억까 statt 열폭?", "es": "Últimamente se dice más 억까 que 열폭, ¿no?", "ja": "最近は열폭より억까って言わない?", "vi": "Dạo này người ta nói 억까 chứ đâu nói 열폭 nữa nhỉ?", "eng": "These days people say 억까 rather than 열폭, no?", "kor": "요즘은 열폭보다 억까라고 하지 않나?"}], "definition": "''열등감 폭발''의 준말. 남들은 아무렇지 않은 상황에서 유독 혼자 발끈하는 사람을 두고, 사실은 질투 때문이라고 짚어 비꼬는 말이다. 유명인을 칭찬하는 기사 밑에 굳이 그 사람을 깎아내리는 악플을 다는 식의 행동이 전형적인 예다.", "definition_i18n": {"de": "Kurzform von 열등감 폭발 (explodierender Minderwertigkeitskomplex). Gemünzt auf jemanden, der sich als Einziger über etwas aufregt, das sonst niemanden stört — und benennt Neid als den wahren Grund. Klassischer Fall: ein gehässiger Kommentar unter einem Artikel, der einen Promi lobt.", "en": "Short for 열등감 폭발 (inferiority complex exploding). It is aimed at someone who gets uniquely worked up over something nobody else minds, and it names envy as the real reason. The classic case: leaving a nasty comment under an article praising a celebrity, just to tear them down.", "es": "Abreviatura de 열등감 폭발 (complejo de inferioridad estallando). Se dirige a quien se enciende solo por algo que a nadie más molesta, señalando la envidia como la causa real. El caso típico: dejar un comentario hiriente bajo un artículo que elogia a un famoso.", "ja": "「劣等感爆発」の略。他の人は何とも思わない場面で一人だけムキになる人を指し、その本当の理由は嫉妬だと当てこする言葉。有名人を褒める記事の下にわざわざ悪口コメントを書く行動が典型例。", "vi": "Rút gọn của 열등감 폭발 (mặc cảm tự ti bùng nổ). Nhắm vào người tự dưng nổi đóa vì chuyện chẳng ai bận tâm, và chỉ đích danh sự ghen tị là lý do thật. Ví dụ điển hình: vào bình luận ác ý dưới bài báo khen một người nổi tiếng."}}]'::jsonb, '''열등감 폭발''이라는 표현 자체는 한일 커뮤니티 인조이재팬의 일본인 이용자들이 먼저 썼고, 이를 ''열폭''으로 줄인 것은 한국이라는 설이 널리 퍼져 있다. 다만 만들어진 정확한 시기는 확인되지 않았고 2006~2007년 무렵 등장한 것으로 추정될 뿐이다. 2000년대 후반부터 2010년대까지 댓글창에서 흔히 보였으나, 지금은 ''억까''처럼 더 새로운 말에 자리를 내줬다.', '{"de": "Verbreitet wird erzählt, die Wendung 열등감 폭발 sei zuerst von japanischen Nutzern in der koreanisch-japanischen Community Enjoy Japan verwendet worden, die Kürzung zu 열폭 dagegen in Korea entstanden. Das genaue Entstehungsjahr ist nicht gesichert — geschätzt wird 2006-2007. Von Ende der 2000er bis in die 2010er füllte es die Kommentarspalten, heute haben neuere Wörter wie 억까 seinen Platz.", "en": "A widely repeated account holds that the phrase 열등감 폭발 was first used by Japanese users on the Korea-Japan community Enjoy Japan, and that the clipping to 열폭 happened in Korea. The exact date it was coined is not established — it is only estimated to have appeared around 2006-2007. It was everywhere in comment sections from the late 2000s through the 2010s, but newer words such as 억까 have since taken its place.", "es": "Una versión muy repetida sostiene que la frase 열등감 폭발 la usaron primero usuarios japoneses en la comunidad coreano-japonesa Enjoy Japan, y que el recorte a 열폭 ocurrió en Corea. La fecha exacta de acuñación no está establecida: solo se estima hacia 2006-2007. Abundó en los comentarios desde finales de los 2000 hasta los 2010, pero palabras más nuevas como 억까 la han reemplazado.", "ja": "「劣等感爆発」という表現自体は韓日コミュニティ「エンジョイジャパン」の日本人ユーザーが先に使い、それを「열폭」と縮めたのは韓国という説が広く流布している。ただし作られた正確な時期は確認されておらず、2006~2007年頃の登場と推定されるにとどまる。2000年代後半から2010年代にかけてコメント欄でよく見られたが、今は「억까」など新しい語に取って代わられた。", "vi": "Một cách giải thích được lặp lại rộng rãi cho rằng cụm 열등감 폭발 do người dùng Nhật trên cộng đồng Hàn-Nhật Enjoy Japan dùng trước, còn việc rút gọn thành 열폭 là ở Hàn Quốc. Thời điểm ra đời chính xác chưa được xác lập — chỉ ước chừng khoảng 2006-2007. Nó tràn ngập mục bình luận từ cuối 2000 đến hết thập niên 2010, nhưng nay đã bị các từ mới hơn như 억까 thay chỗ."}'::jsonb, '''열폭하다'', ''열폭하네''처럼 쓴다. 상대를 깎아내리는 공격적인 말이라 면전에 대고 쓰면 싸움이 된다. 뜻을 아는 것과 쓰는 것은 다르니 알아듣기만 하는 편이 안전하다. 지금 같은 뜻으로는 ''억까'', ''배 아프다''가 더 자주 쓰인다.', '{"de": "Verwendet als 열폭하다 / 열폭하네. Es ist ein Angriff — jemandem ins Gesicht gesagt, gibt es Streit; besser verstehen als benutzen. Heute decken 억까 oder 배 아프다 dasselbe ab.", "en": "Used as 열폭하다 / 열폭하네. It is an attack on the other person, so saying it to someone''''s face starts a fight — better to recognize it than to use it. Today 억까 or 배 아프다 cover the same ground.", "es": "Se usa como 열폭하다 / 열폭하네. Es un ataque directo, así que decírselo a alguien a la cara provoca pelea: mejor entenderlo que usarlo. Hoy 억까 o 배 아프다 cubren lo mismo.", "ja": "「열폭하다」「열폭하네」のように使う。相手を貶す攻撃的な語なので面と向かって言えば喧嘩になる。意味を知ることと使うことは別なので、聞き取れるだけにしておくのが安全。今は「억까」「배 아프다」が同じ役割。", "vi": "Dùng dạng 열폭하다 / 열폭하네. Đây là lời công kích nên nói thẳng vào mặt ai đó là sinh chuyện — hiểu thì tốt hơn là dùng. Ngày nay 억까 hay 배 아프다 mang cùng ý."}'::jsonb, array['억까', '극혐', '관종']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Seething from an inferiority complex"}, {"lang": "🇯🇵 JA", "text": "劣等感爆発(嫉妬でキレること)"}, {"lang": "🇨🇳 ZH", "text": "自卑心爆发(因嫉妒而发火)"}, {"lang": "🇻🇳 VI", "text": "Mặc cảm bùng nổ (cay cú vì ghen tị)"}, {"lang": "🇪🇸 ES", "text": "Arder de envidia / complejo estallado"}, {"lang": "🇩🇪 DE", "text": "Vor Neid explodieren"}]'::jsonb),
('549', '오나전', 'O-na-jeon', 'outdated-slang', NULL, '''완전''의 오타가 유행어가 된 강조 표현', '{"de": "Ein Tippfehler von 완전 (total), der zum Slang aufstieg", "en": "A typo of 완전 (totally) that graduated into slang", "es": "Una errata de 완전 (totalmente) ascendida a jerga", "ja": "「완전(完全に)」の誤字がそのまま流行語になった強調表現", "vi": "Lỗi gõ của 완전 (hoàn toàn) trở thành tiếng lóng nhấn mạnh"}'::jsonb, NULL, '[{"type": "부사", "examples": [{"de": "Den Film mag ich onajeon gern.", "es": "Esa peli me encanta oh-na-jeon.", "ja": "私その映画オナジョン好き。", "vi": "Tớ thích phim đó onajeon luôn.", "eng": "I totally love that movie.", "kor": "나 그 영화 오나전 좋아해."}, {"de": "Er sagt 오나전. Aus welchem Jahrzehnt ist das denn?", "es": "Dijo 오나전. ¿De qué década es eso?", "ja": "오나전だって。いつの時代の言葉よ", "vi": "Nói 오나전 cơ à. Từ thời nào vậy trời", "eng": "They said 오나전. What decade is that from?", "kor": "오나전이래. 언제 적 말이야 그게"}], "definition": "''완전''을 급하게 치다 글자 순서가 엉켜 나온 오타. 뜻은 ''완전'', ''진짜'', ''엄청''과 똑같지만, 일부러 틀리게 쓴다는 장난기가 더해져 원래 말보다 더 센 강조로 쓰였다. 2000년대 인터넷 유행어이며 지금은 옛날 감성을 낼 때만 꺼낸다.", "definition_i18n": {"de": "Ein Buchstabendreher von 완전 (total). Bedeutet dasselbe wie 완전, 진짜 oder 엄청, doch das Augenzwinkern der absichtlichen Falschschreibung machte es wuchtiger als das Original. Ein Internetwort der 2000er, heute nur noch für Retro-Flair.", "en": "A scrambled-letter typo of 완전 (totally). It means exactly what 완전, 진짜 or 엄청 mean, but the wink of deliberate misspelling made it hit harder than the original. A 2000s internet word, now pulled out only for retro flavor.", "es": "Errata con las letras cambiadas de 완전 (totalmente). Significa lo mismo que 완전, 진짜 o 엄청, pero el guiño de escribirlo mal a propósito le daba más fuerza que al original. Palabra de internet de los 2000, hoy solo para dar aire retro.", "ja": "「완전」を急いで打って文字順が崩れた誤字。意味は「완전」「진짜」「엄청」と同じだが、わざと間違えるおどけが加わって元の語より強い強調になった。2000年代のネット流行語で、今はレトロな雰囲気を出すときだけ使う。", "vi": "Lỗi gõ đảo chữ của 완전 (hoàn toàn). Nghĩa y hệt 완전, 진짜 hay 엄청, nhưng cái nháy mắt cố tình viết sai khiến nó mạnh hơn bản gốc. Từ mạng thập niên 2000, nay chỉ lôi ra để tạo chất hoài cổ."}}]'::jsonb, '자판으로 ''완전''을 급하게 치다 글자 순서가 엉켜 나온 오타에서 시작됐다. 처음에는 실수였지만 어감이 우습다는 이유로 일부러 쓰게 됐고, 2000년대 인터넷에서 유행어로 자리 잡았다. 정확히 어떤 키 입력 순서에서 오타가 나는지는 출처마다 설명이 없어 확정하지 않는다. 유행 시점도 ''2000년대 초반''이라는 설과 시기를 특정하지 않는 설로 갈린다.', '{"de": "Begann als Vertipper beim hastigen Schreiben von 완전, bei dem die Buchstaben in falscher Reihenfolge landeten. Aus dem Fehler wurde Absicht, weil es komisch klang, und es etablierte sich als Internet-Slang der 2000er. Die Quellen erklären nicht, welche Tastenfolge den Tippfehler genau erzeugt, daher bleibt das offen; auch die Datierung ist uneinheitlich.", "en": "It began as a keyboard slip while typing 완전 in a hurry, the letters landing out of order. What started as a mistake became deliberate because it sounded funny, and it settled in as 2000s internet slang. Sources do not explain exactly which keystroke order produces the typo, so that is left unstated; they also disagree on timing — some say early 2000s, others give no date.", "es": "Empezó como un desliz al teclear 완전 con prisa, con las letras fuera de orden. Lo que fue un error se volvió intencional porque sonaba gracioso, y cuajó como jerga de internet de los 2000. Las fuentes no explican qué orden exacto de teclas produce la errata, así que no se afirma; tampoco coinciden en la fecha.", "ja": "「완전」を急いで打った際に文字順が入れ替わった打ち間違いが出発点。最初はミスだったが語感が面白いのでわざと使うようになり、2000年代のネット流行語として定着した。どのキー入力順で誤字が生じるかは資料に説明がなく断定しない。流行時期も「2000年代初頭」説と時期不特定の説に分かれる。", "vi": "Bắt đầu từ một cú trượt phím khi gõ vội 완전, các chữ rơi sai thứ tự. Vốn là lỗi nhưng vì nghe buồn cười nên người ta cố tình dùng, rồi đóng đinh thành tiếng lóng mạng thập niên 2000. Các nguồn không giải thích thứ tự phím nào tạo ra lỗi này nên không khẳng định; thời điểm thịnh hành cũng không thống nhất."}'::jsonb, '꾸미는 말 앞에 붙여 ''오나전 맛있어'', ''오나전 대박''처럼 쓴다. 지금 진지하게 쓰는 사람은 없고, 옛날 인터넷 말투를 흉내 낼 때만 등장한다. 같은 자리에 요즘은 ''완전'', ''개'', ''찐''이 들어간다.', '{"de": "Steht vor dem Bezugswort: 오나전 맛있어 (voll lecker), 오나전 대박. Ernsthaft benutzt es heute niemand; es taucht nur beim Nachahmen alter Internetsprache auf. Heutige Entsprechungen: 완전, 개-, 찐.", "en": "Placed before what it modifies: 오나전 맛있어 (totally delicious), 오나전 대박. Nobody uses it earnestly today; it appears only when mimicking old internet speech. Modern fillers for the slot: 완전, 개-, 찐.", "es": "Va delante de lo que modifica: 오나전 맛있어 (buenísimo), 오나전 대박. Hoy nadie la usa en serio; solo aparece al imitar el habla de la vieja internet. Sustitutos actuales: 완전, 개-, 찐.", "ja": "修飾する語の前に置いて「오나전 おいしい」「오나전 やばい」のように使う。今どき本気で使う人はおらず、昔のネット口調を真似るときだけ登場する。今の同ポジションは「완전」「개-」「찐」。", "vi": "Đặt trước từ được bổ nghĩa: 오나전 맛있어 (ngon cực), 오나전 대박. Nay không ai dùng nghiêm túc; chỉ xuất hiện khi nhại giọng mạng ngày xưa. Chỗ đó giờ dùng 완전, 개-, 찐."}'::jsonb, array['뭥미', '찐']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Totally (2000s typo slang for 완전)"}, {"lang": "🇯🇵 JA", "text": "完全に(2000年代の誤字スラング)"}, {"lang": "🇨🇳 ZH", "text": "完全(2000年代错字俚语)"}, {"lang": "🇻🇳 VI", "text": "Hoàn toàn (tiếng lóng lỗi gõ thập niên 2000)"}, {"lang": "🇪🇸 ES", "text": "Totalmente (jerga de errata de los 2000)"}, {"lang": "🇩🇪 DE", "text": "Voll / total (Tippfehler-Slang der 2000er)"}]'::jsonb),
('550', '잉여인간', 'Ing-yeo-in-gan', 'outdated-slang', 'work', '하는 일 없이 시간만 보내는 사람 (주로 자조)', '{"de": "Jemand, der nichts zustande bringt — meist selbstironisch", "en": "A person going nowhere — usually said about oneself", "es": "Alguien que no hace nada — casi siempre dicho de uno mismo", "ja": "何もせず時間だけ過ごす人(主に自嘲)", "vi": "Người chẳng làm gì cả — thường tự nói về mình"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Ich habe das ganze Wochenende nur gelegen. Komplett nutzlos.", "es": "Me he pasado el finde entero tumbado. Un cero a la izquierda total.", "ja": "週末ずっと寝てただけ。完全に無駄人間。", "vi": "Cả cuối tuần tớ chỉ nằm. Đúng là đồ bỏ đi.", "eng": "I lay in bed the entire weekend. Complete waste of space.", "kor": "주말 내내 누워만 있었어. 완전 잉여인간."}], "definition": "사회에서 딱히 쓸모를 찾지 못하고 무기력하게 지내는 사람. 남을 욕할 때보다 「나 오늘 완전 잉여였어」처럼 스스로를 낮추는 자조에 훨씬 많이 쓰였다. 줄여서 「잉여」, 그런 상태를 두고는 「잉여롭다」·「잉여짓」이라고 했다.", "definition_i18n": {"de": "Jemand, der ohne erkennbaren Nutzen vor sich hin treibt. Viel häufiger auf sich selbst gemünzt — 나 오늘 완전 잉여였어 (ich war heute komplett nutzlos) — als gegen andere. Verkürzt zu 잉여, dazu 잉여롭다 und 잉여짓 für Zustand und Tätigkeit.", "en": "Someone drifting without a use for themselves. Far more often aimed at oneself — 나 오늘 완전 잉여였어 (I was a total waste of space today) — than thrown at others. Clipped to 잉여, with 잉여롭다 and 잉여짓 for the state and the activity.", "es": "Alguien que va a la deriva sin encontrarse una utilidad. Se usaba mucho más contra uno mismo — 나 오늘 완전 잉여였어 (hoy he sido un cero a la izquierda) — que contra otros. Se acortaba a 잉여, con 잉여롭다 y 잉여짓 para el estado y la actividad.", "ja": "社会で自分の使い道を見つけられず無気力に過ごす人。他人をけなすより「나 오늘 완전 잉여였어(今日は完全に無駄人間だった)」のように自嘲で使うことが圧倒的に多い。縮めて「잉여」、その状態は「잉여롭다」「잉여짓」と言った。", "vi": "Người sống vật vờ, không thấy mình có ích gì. Thường tự nói về mình — 나 오늘 완전 잉여였어 (hôm nay tớ đúng là đồ bỏ đi) — hơn là nói người khác. Rút gọn thành 잉여, kèm 잉여롭다 và 잉여짓 cho trạng thái và hành vi."}}]'::jsonb, '경제 용어 「잉여 생산물」의 「잉여(剩餘, 쓰고 남은 것)」에 「인간」을 붙인 말. 1997년 외환위기 이후의 대량 실업과 청년 취업난을 배경으로 2006~2008년 무렵 인터넷에서 널리 쓰이게 됐다. 같은 제목의 손창섭 단편소설(1958)이 표준국어대사전에 올라 있지만, 신조어 쪽은 그 작품에서 직접 이어진 말이 아니라 별개로 생겨난 표현이다.', '{"de": "잉여 (Überschuss, das Übriggebliebene) plus 인간 (Mensch). Verbreitete sich um 2006-2008 online, vor dem Hintergrund der Massenarbeitslosigkeit nach der Krise von 1997 und eines brutalen Arbeitsmarkts für Junge. Im Standardwörterbuch steht eine gleichnamige Erzählung von Son Chang-seop (1958), doch der Slang entstand unabhängig davon.", "en": "잉여 (surplus, the leftover in surplus product) plus 인간 (human). It spread online around 2006-2008 against the backdrop of mass unemployment after the 1997 financial crisis and a brutal youth job market. A 1958 Son Chang-seop short story of the same name is in the standard dictionary, but the slang arose separately rather than from that work.", "es": "잉여 (excedente, lo que sobra) más 인간 (humano). Se difundió en internet hacia 2006-2008, con el telón de fondo del paro masivo tras la crisis de 1997 y un mercado laboral juvenil durísimo. El diccionario estándar recoge un relato homónimo de Son Chang-seop (1958), pero la jerga nació aparte, no de esa obra.", "ja": "経済用語「剰余生産物」の「剰余(使い残り)」に「人間」を付けた語。1997年の通貨危機後の大量失業と若年就職難を背景に、2006〜2008年頃ネットで広まった。同名の孫昌渉の短編小説(1958)が標準国語大辞典に載っているが、新造語はその作品から直接つながったものではなく別個に生まれた表現。", "vi": "잉여 (thặng dư, phần dư ra) ghép với 인간 (con người). Lan trên mạng khoảng 2006-2008, trên nền thất nghiệp hàng loạt sau khủng hoảng 1997 và thị trường việc làm khắc nghiệt cho người trẻ. Từ điển chuẩn có truyện ngắn cùng tên của Son Chang-seop (1958), nhưng tiếng lóng này sinh ra độc lập chứ không nối tiếp tác phẩm đó."}'::jsonb, '2010년대 이후 커뮤니티에서는 본래 뜻으로 잘 쓰이지 않고 더 날이 선 표현들이 자리를 대신했다. 지금은 「갓생」의 반대말을 설명할 때 옛말로 언급되는 정도다. 남에게 쓰면 꽤 모욕적이니 자기 얘기에만 쓰는 게 안전하다.', '{"de": "Seit den 2010ern in der ursprünglichen Bedeutung kaum noch in Communities gebräuchlich, verdrängt von schärferen Ausdrücken; heute vor allem als altmodisches Gegenteil von 갓생 erwähnt. Auf andere gemünzt ist es beleidigend — besser nur über sich selbst sagen.", "en": "Since the 2010s it has largely dropped out of community use in its original sense, displaced by harsher terms; today it mostly comes up as the old-fashioned opposite of 갓생. Aimed at someone else it stings — keep it for talking about yourself.", "es": "Desde los 2010 apenas se usa en su sentido original en los foros, desplazada por términos más hirientes; hoy sale sobre todo como el opuesto anticuado de 갓생. Dirigida a otro resulta ofensiva: mejor reservarla para hablar de uno mismo.", "ja": "2010年代以降、コミュニティでは本来の意味ではあまり使われず、より刺々しい表現に取って代わられた。今は「갓생」の反対語を説明するときに古い言葉として挙がる程度。人に向けるとかなり侮辱的なので自分の話にとどめるのが安全。", "vi": "Từ thập niên 2010 nó gần như không còn dùng theo nghĩa gốc trên các diễn đàn, bị những từ gay gắt hơn thay thế; nay chủ yếu được nhắc như từ cũ đối lập với 갓생. Nói về người khác thì khá xúc phạm — chỉ nên dùng cho chính mình."}'::jsonb, array['갓생', '이생망', '쉬었음 청년']::text[], array['잉여', '잉여롭다', '잉여짓']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "A waste of space / deadweight"}, {"lang": "🇯🇵 JA", "text": "無駄人間、余り物人間"}, {"lang": "🇨🇳 ZH", "text": "废人、多余的人"}, {"lang": "🇻🇳 VI", "text": "Kẻ thừa thãi, đồ bỏ đi"}, {"lang": "🇪🇸 ES", "text": "Un cero a la izquierda"}, {"lang": "🇩🇪 DE", "text": "Überflüssiger Mensch"}]'::jsonb),
('551', '정줄놓', 'Jeong-jul-no', 'outdated-slang', NULL, '''정신 줄을 놓다'' — 넋 놓고 저지른 실수', '{"de": "''Die Verstandesleine loslassen'' — geistesabwesend danebenhauen", "en": "''Letting go of the mind-string'' — spacing out and blowing it", "es": "''Soltar el hilo de la cordura'': despistarse y meter la pata", "ja": "「正気の紐を放す」——ぼんやりしてやらかすこと", "vi": "''Buông sợi dây tỉnh táo'' — lơ đễnh rồi làm hỏng việc"}'::jsonb, NULL, '[{"type": "동사", "examples": [{"de": "Gestern war ich total weggetreten und bin in die falsche U-Bahn-Richtung gestiegen.", "es": "Ayer me despisté y cogí el metro en dirección contraria.", "ja": "昨日ぼーっとして地下鉄を逆方向に乗っちゃった。", "vi": "Hôm qua lơ đễnh quá, tớ lên tàu điện ngược chiều luôn.", "eng": "I totally spaced yesterday and got on the subway going the wrong way.", "kor": "어제 정줄놓고 지하철 반대 방향으로 탔어."}, {"de": "''정줄놓''? Das ist eine Lehrbuch-Abkürzung der 2010er.", "es": "¿''정줄놓''? Es una abreviatura de manual de los 2010.", "ja": "「정줄놓」とか、まさに2010年代の略語だね", "vi": "''정줄놓'' á? Đúng kiểu từ viết tắt thập niên 2010", "eng": "''정줄놓''? That is a textbook 2010s abbreviation.", "kor": "정줄놓이라니, 딱 2010년대 줄임말이네"}], "definition": "''정신 줄을 놓다''를 줄인 말. 한국어는 정신을 줄에 비유해, 그 줄을 놓으면 사람이 멍해진다고 표현한다. 잠깐 넋을 놓아 어이없는 실수를 하는 가벼운 경우부터 아예 제정신이 아닌 행동을 하는 경우까지 폭넓게 쓴다.", "definition_i18n": {"de": "Kurzform von 정신 줄을 놓다. Im Koreanischen hängt der Verstand an einer Leine; lässt man sie los, wird man geistesabwesend. Reicht vom kurzen Aussetzer mit albernem Fehler bis zum Verhalten, als hätte man den Verstand verloren.", "en": "Clipped from 정신 줄을 놓다. Korean pictures the mind as held by a string; let the string go and you go blank. It covers everything from a brief lapse that leads to a silly mistake to behaving as if you have lost your mind entirely.", "es": "Recorte de 정신 줄을 놓다. El coreano imagina la mente sujeta por un hilo: si lo sueltas, te quedas en blanco. Abarca desde un despiste momentáneo que acaba en un error tonto hasta comportarse como si hubieras perdido la cabeza.", "ja": "「정신 줄을 놓다(正気の紐を放す)」の略。韓国語では精神を紐に見立て、その紐を放すとぼんやりすると表現する。一瞬ぼうっとしてばかげたミスをする軽い場合から、完全に正気を失った振る舞いまで幅広く使う。", "vi": "Rút gọn từ 정신 줄을 놓다. Tiếng Hàn hình dung tinh thần được giữ bằng một sợi dây; buông dây ra là đầu óc trống rỗng. Dùng cho mọi mức độ, từ lơ đễnh thoáng chốc dẫn đến lỗi ngớ ngẩn cho tới hành xử như mất trí hoàn toàn."}}]'::jsonb, '''정신을 놓다'', ''넋을 놓다'' 같은 기존 표현에서 나온 것으로 보인다는 설이 일반적이지만, 누가 언제 어디서 처음 썼는지는 확인되지 않았다. 이어지는 것을 줄이나 끈에 비유하는 방식(''의식의 끈을 놓지 않다'')은 한국어에서 오래된 관습이다. 표준국어대사전에는 ''정신이 나가다'' 같은 관용구는 있어도 ''정신줄을 놓다''는 없어, 이 표현 자체가 인터넷에서 자란 말로 여겨진다. 본딧말 ''정신줄 놓다''는 지금도 살아 있지만, 네 글자로 줄인 ''정줄놓''은 2010년대 줄임말 유행이 지나가면서 함께 옛말이 됐다.', '{"de": "Allgemein nimmt man an, es sei aus bestehenden Wendungen wie 정신을 놓다 oder 넋을 놓다 hervorgegangen, doch keine Quelle belegt, wer es zuerst benutzte, wann oder wo. Kontinuität als Schnur oder Seil zu denken, ist im Koreanischen alte Gewohnheit. Das Standardwörterbuch kennt Redewendungen wie 정신이 나가다, nicht aber 정신줄을 놓다 — daher gilt der Ausdruck als im Internet gewachsen. Die volle Wendung 정신줄 놓다 lebt weiter; nur die viersilbige Kurzform 정줄놓 alterte mit der Abkürzungsmode der 2010er.", "en": "It is generally assumed to have grown out of existing phrases like 정신을 놓다 or 넋을 놓다, but no source establishes who first used it, when, or where. Picturing continuity as a string or cord is an old habit in Korean (as in ''not letting go of the cord of consciousness''). The standard dictionary has idioms like 정신이 나가다 but not 정신줄을 놓다, which is why the expression is treated as internet-grown. The full phrase 정신줄 놓다 is still alive; only the four-syllable clip 정줄놓 aged out with the 2010s fashion for abbreviations.", "es": "Se asume que surgió de expresiones ya existentes como 정신을 놓다 o 넋을 놓다, pero ninguna fuente fija quién la usó primero, cuándo ni dónde. Imaginar la continuidad como un hilo o cuerda es un hábito antiguo del coreano. El diccionario estándar recoge modismos como 정신이 나가다 pero no 정신줄을 놓다, por lo que se considera una expresión nacida en internet. La frase completa 정신줄 놓다 sigue viva; solo el recorte 정줄놓 envejeció con la moda de abreviar de los 2010.", "ja": "「정신을 놓다」「넋을 놓다」といった既存表現から生まれたとする見方が一般的だが、誰がいつどこで最初に使ったかは確認されていない。続くものを紐や綱に例える発想(「意識の綱を放さない」)は韓国語で古くからの習慣。標準国語大辞典には「정신이 나가다」のような慣用句はあっても「정신줄을 놓다」はなく、この表現自体がネット発と見なされる。元の「정신줄 놓다」は今も生きているが、4文字に縮めた「정줄놓」は2010年代の略語ブームとともに古びた。", "vi": "Người ta thường cho rằng nó nảy ra từ các cách nói sẵn có như 정신을 놓다 hay 넋을 놓다, nhưng không nguồn nào xác định ai dùng đầu tiên, khi nào, ở đâu. Việc hình dung sự liên tục như một sợi dây vốn là thói quen lâu đời trong tiếng Hàn. Từ điển chuẩn có thành ngữ 정신이 나가다 nhưng không có 정신줄을 놓다, nên cách nói này được xem là sinh ra từ internet. Cụm đầy đủ 정신줄 놓다 vẫn còn sống; chỉ bản rút gọn bốn âm tiết 정줄놓 già đi cùng trào lưu viết tắt thập niên 2010."}'::jsonb, '''정줄놓하다'', ''정줄놓했다''처럼 동사로 쓰거나 ''정줄놓 사진''처럼 앞에 붙여 썼다. 자기 실수를 스스로 웃으며 말할 때 쓰면 자연스럽고, 남에게 쓰면 정신 상태를 지적하는 셈이라 조심해야 한다. 줄임말 없이 ''정신줄 놓다''라고 하면 지금도 그대로 통한다.', '{"de": "Verwendet als Verb (정줄놓하다, 정줄놓했다) oder vor einem Nomen (정줄놓 사진). Über den eigenen Aussetzer zu lachen klingt natürlich; auf andere gemünzt kommentiert es deren Geisteszustand — also Vorsicht. Ungekürzt funktioniert 정신줄 놓다 auch heute noch.", "en": "Used as a verb (정줄놓하다, 정줄놓했다) or attached to a noun (정줄놓 사진, a ''lost the plot'' photo). It sounds natural when you are laughing at your own lapse; aimed at someone else it comments on their sanity, so tread carefully. Unclipped, 정신줄 놓다 still works perfectly today.", "es": "Se usa como verbo (정줄놓하다, 정줄놓했다) o antepuesta a un sustantivo (정줄놓 사진). Suena natural al reírte de tu propio despiste; dirigida a otro, comenta su cordura, así que cuidado. Sin recortar, 정신줄 놓다 sigue funcionando hoy.", "ja": "「정줄놓하다」「정줄놓했다」と動詞で使ったり、「정줄놓 사진」のように名詞の前に付けたりした。自分のミスを笑って話すときは自然だが、他人に使うと精神状態を指摘することになるので注意。略さず「정신줄 놓다」と言えば今でもそのまま通じる。", "vi": "Dùng như động từ (정줄놓하다, 정줄놓했다) hoặc đặt trước danh từ (정줄놓 사진). Nghe tự nhiên khi bạn tự cười lỗi của mình; nhắm vào người khác thì thành bình phẩm về đầu óc họ, nên cẩn thận. Không rút gọn, 정신줄 놓다 vẫn dùng tốt ngày nay."}'::jsonb, array['멘붕', '뇌정지', '순삭']::text[], array['정신줄 놓다', '정신줄']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "To space out / lose the plot"}, {"lang": "🇯🇵 JA", "text": "正気の紐を放す(ぼーっとしてやらかす)"}, {"lang": "🇨🇳 ZH", "text": "放开精神的绳子(走神、失神犯错)"}, {"lang": "🇻🇳 VI", "text": "Buông dây tỉnh táo (lơ đễnh, mất trí)"}, {"lang": "🇪🇸 ES", "text": "Soltar el hilo de la cordura / despistarse"}, {"lang": "🇩🇪 DE", "text": "Die Verstandesleine loslassen"}]'::jsonb),
('552', '지름신', 'Ji-reum-sin', 'outdated-slang', NULL, '충동구매를 부추긴다는 상상 속의 신', '{"de": "Der imaginäre Gott, der zu Spontankäufen verleitet", "en": "The imaginary god who makes you buy what you do not need", "es": "El dios imaginario que te empuja a comprar por impulso", "ja": "衝動買いをそそのかす想像上の神", "vi": "Vị thần tưởng tượng xui bạn mua sắm bốc đồng"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Schon wieder Schuhe? — Gestern kam der Kaufgott über mich.", "es": "¿Otra vez zapatos? — Ayer se me apareció el dios de las compras.", "ja": "また靴買ったの? — 昨日チルムシンが降臨しちゃって。", "vi": "Lại mua giày à? — Hôm qua thần mua sắm nhập vào tớ rồi.", "eng": "You bought shoes again? — The shopping god descended on me yesterday.", "kor": "또 신발 샀어? — 어제 지름신이 강림하셨어."}], "definition": "꼭 필요하지도 않은 물건을 앞뒤 가리지 않고 사게 만든다는 가상의 신. 주로 「지름신이 강림하셨다/오셨다」 형태로 쓴다. 생필품을 살 때는 쓰지 않고, 신제품이거나 디자인이 화려한 물건을 지를 때만 쓰는 것이 특징이다.", "definition_i18n": {"de": "Eine erfundene Gottheit, die zu Spontankäufen verleitet, meist als 지름신이 강림하셨다 (der Kaufgott kam über mich). Nie für Notwendiges, nur für schicke Neuheiten.", "en": "An imaginary deity that makes you buy things on impulse, usually phrased as 지름신이 강림하셨다 (the shopping god descended on me). Never used for necessities — only for shiny new gadgets or things bought purely for looks.", "es": "Un dios imaginario que te hace comprar sin pensar. Se usa como 지름신이 강림하셨다 (se me apareció el dios de las compras). Nunca para lo necesario, solo para caprichos o novedades vistosas.", "ja": "必要でもない物を後先考えずに買わせるという架空の神。主に「지름신이 강림하셨다(衝動買いの神が降臨した)」の形で使う。生活必需品には使わず、新製品や見た目重視の買い物にだけ使う。", "vi": "Vị thần tưởng tượng khiến bạn mua đồ không cần thiết, thường nói 지름신이 강림하셨다 (thần mua sắm giáng thế). Không dùng cho đồ thiết yếu, chỉ cho hàng mới hay đồ mua vì đẹp."}}]'::jsonb, '동사 「지르다」의 명사형 「지름」에 「신(神)」을 붙인 말. 2000년대 초 인터넷 커뮤니티에서 퍼져 2005년에는 언론이 「인터넷 신조어」로 따로 다룰 만큼 널리 쓰였다. 「지르다」가 충동적으로 산다는 뜻을 갖게 된 경위는 「저지르다」와 「내기에 돈을 걸다」의 뜻이 소비 행위로 확장된 결과라는 설명이 유력하나 확정된 것은 아니다.', '{"de": "지름 (Nominalform von 지르다, klotzen) plus 신 (Gott). Verbreitete sich Anfang der 2000er in Online-Foren; 2005 berichtete die Presse darüber als bemerkenswerte Internet-Neuschöpfung. Dass 지르다 Spontankauf bedeutet, wird meist als Erweiterung älterer Bedeutungen (etwas anstellen; Geld setzen) erklärt — eine führende These, keine gesicherte Etymologie.", "en": "지름 (the noun form of 지르다, to splurge) plus 신 (god). It spread through online communities in the early 2000s and by 2005 was covered in the press as a notable internet coinage. How 지르다 came to mean impulse-buying is usually explained as an extension of its older senses (to commit an act; to stake money on a bet), though this is a leading theory rather than a settled etymology.", "es": "지름 (sustantivo de 지르다, gastar sin medida) más 신 (dios). Se difundió por foros a comienzos de los 2000 y en 2005 ya salía en prensa como neologismo de internet. Que 지르다 pase a significar comprar por impulso se explica como extensión de sus sentidos antiguos (cometer algo; apostar dinero), pero es una hipótesis, no una etimología cerrada.", "ja": "動詞「지르다」の名詞形「지름」に「神」を付けた語。2000年代初頭にネットコミュニティで広まり、2005年には新聞が「ネット新造語」として取り上げるほど定着した。「지르다」が衝動買いを指すようになった経緯は「やらかす」「賭ける」の意味が消費行動へ拡張したという説明が有力だが確定していない。", "vi": "지름 (danh từ của 지르다, vung tiền) ghép với 신 (thần). Lan trên các diễn đàn đầu những năm 2000, đến 2005 đã được báo chí nhắc tới như từ mới của internet. Việc 지르다 mang nghĩa mua bốc đồng thường được giải thích là mở rộng từ nghĩa cũ (gây ra chuyện; đặt cược), nhưng đây là giả thuyết chứ chưa phải từ nguyên chắc chắn."}'::jsonb, '2000년대 온라인 쇼핑 붐과 함께 크게 유행했으나 지금 10~20대는 거의 쓰지 않고 「플렉스」·「내돈내산」 같은 말이 그 자리를 대신한다. 옛 블로그 글이나 중고 거래 게시물에서 자주 만나게 되는 말이다.', '{"de": "Im Online-Shopping-Boom der 2000er allgegenwärtig, heute unter Jüngeren kaum noch — 플렉스 und 내돈내산 haben es abgelöst. In alten Blogposts und Kleinanzeigen begegnet es einem noch.", "en": "Huge during the 2000s online-shopping boom, but people in their teens and twenties rarely say it now — 플렉스 and 내돈내산 have taken its place. You still run into it in old blog posts and secondhand-market listings.", "es": "Arrasó con el boom de las compras online de los 2000, pero hoy los jóvenes casi no lo dicen: lo han reemplazado 플렉스 y 내돈내산. Aún aparece en blogs antiguos y anuncios de segunda mano.", "ja": "2000年代のネット通販ブームとともに大流行したが、今の10〜20代はほぼ使わず「플렉스」「내돈내산」が取って代わった。古いブログや中古取引の投稿でよく見かける。", "vi": "Rất thịnh thời bùng nổ mua sắm online những năm 2000, nay giới trẻ hiếm dùng — 플렉스 và 내돈내산 đã thay thế. Vẫn gặp trong blog cũ và tin rao đồ cũ."}'::jsonb, array['플렉스', '내돈내산', '득템']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "The shopping god (impulse-buy urge)"}, {"lang": "🇯🇵 JA", "text": "衝動買いの神"}, {"lang": "🇨🇳 ZH", "text": "剁手神(冲动购物之神)"}, {"lang": "🇻🇳 VI", "text": "Thần mua sắm bốc đồng"}, {"lang": "🇪🇸 ES", "text": "El dios de las compras"}, {"lang": "🇩🇪 DE", "text": "Der Kaufgott"}]'::jsonb),
('553', '차도남', 'Cha-Do-Nam', 'outdated-slang', 'love', '겉은 차갑고 속은 따뜻한 도시 남자 — 2010년대 초 유행어', '{"de": "Der aussen kuehle, innen warme Stadtmann — ein Modewort der fruehen 2010er", "en": "The cold-on-the-outside, warm-on-the-inside city guy — an early-2010s buzzword", "es": "El chico urbano frío por fuera y cálido por dentro — palabra de moda de inicios de 2010", "ja": "外は冷たく中は温かい都会の男 — 2010年代初めの流行語", "vi": "Chàng trai thành thị lạnh ngoài ấm trong — từ thịnh hành đầu thập niên 2010"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Ich hielt ihn fuer einen echten Cha-do-nam, aber bei seiner Freundin schmilzt er komplett dahin.", "es": "Pensaba que era un cha-do-nam total, pero con su novia se derrite entero.", "ja": "あいつ完全にチャドナムだと思ってたのに、彼女の前ではデレデレだった。", "vi": "Tưởng nó là cha-do-nam chính hiệu, ai ngờ trước bạn gái thì ngoan như cún.", "eng": "I thought he was a total cha-do-nam, but he is completely whipped around his girlfriend.", "kor": "쟤 완전 차도남인 줄 알았는데 여자친구한테는 완전 껌뻑 죽더라."}, {"de": "2011 reichte eine Cha-do-nam-Figur, damit eine Serie zum Hit wurde.", "es": "En 2011 bastaba un personaje cha-do-nam para que un drama triunfara.", "ja": "2011年はチャドナムキャラ一人いればドラマが当たってたよね。", "vi": "Hồi 2011 chỉ cần một nhân vật cha-do-nam là phim đã hot rồi.", "eng": "Back in 2011, one cha-do-nam character was enough to make a drama a hit.", "kor": "2011년에는 차도남 캐릭터 하나면 드라마가 떴잖아."}], "definition": "차가운 도시 남자의 줄임말. 남들에게는 무뚝뚝하고 시크하게 굴지만 자기가 아끼는 사람에게만은 다정한 남자를 가리켰다. 여자 버전은 차도녀, 더 까칠한 버전은 까도남/까도녀라고 했다.", "definition_i18n": {"de": "Kurzform fuer kalter Stadtmann: schroff und chic zu allen, aber zaertlich nur zu der einen Person. Weibliche Variante: Cha-do-nyeo, die schroffere: Kka-do-nam / Kka-do-nyeo.", "en": "Short for cha-gaun do-si nam-ja (cold city man): a guy who is curt and chic with everyone but tender toward the one person he cares about. Female version: cha-do-nyeo; the pricklier version: kka-do-nam / kka-do-nyeo.", "es": "Abreviatura de hombre urbano frio: seco y chic con todos, pero tierno solo con la persona que le importa. Version femenina: cha-do-nyeo; version mas arisca: kka-do-nam / kka-do-nyeo.", "ja": "冷たい都会の男の略。周りにはそっけなくクールに振る舞うが、大切な人にだけは優しい男。女性版はチャドニョ、より刺のある版はカドナム/カドニョ。", "vi": "Viết tắt của chàng trai thành thị lạnh lùng: cộc cằn và ngầu với mọi người nhưng dịu dàng với riêng người mình thương. Bản nữ: cha-do-nyeo; bản gắt hơn: kka-do-nam / kka-do-nyeo."}}]'::jsonb, '조석의 웹툰 <마음의 소리> 242화 <도시남자>(2008)에서 쓰인 말이 인터넷 커뮤니티로 퍼졌고, 2010년 말 드라마 <시크릿 가든>의 현빈 캐릭터가 인기를 끌면서 차도남/차도녀/까도남/까도녀가 한꺼번에 대유행했다. 2010~2011년 유행어 결산 기사마다 상위권에 오른 말이다.', '{"de": "Der Ausdruck tauchte in Jo Seoks Webtoon Sound of the Heart Folge 242 (2008) auf und verbreitete sich in Online-Foren; Ende 2010 explodierte er, als Hyun Bins Figur in der Serie Secret Garden Cha-do-nam, Cha-do-nyeo, Kka-do-nam und Kka-do-nyeo populaer machte. In den Modewort-Rueckblicken 2010-2011 stand er ganz oben.", "en": "The phrase appeared in Jo Seok webtoon Sound of the Heart episode 242 (2008) and spread through online communities; it exploded in late 2010 when Hyun Bin character in the drama Secret Garden made cha-do-nam, cha-do-nyeo, kka-do-nam and kka-do-nyeo household words. It topped the 2010-2011 buzzword roundups in Korean media.", "es": "La expresion aparecio en el webtoon de Jo Seok El sonido del corazon episodio 242 (2008) y se difundio por foros; estallo a finales de 2010 con el personaje de Hyun Bin en el drama Secret Garden, popularizando cha-do-nam, cha-do-nyeo, kka-do-nam y kka-do-nyeo. Encabezo los recuentos de palabras de moda de 2010-2011.", "ja": "チョ・ソクのウェブトゥーン<マウムの声>242話<都市男子>(2008)で使われた言葉がネットコミュニティに広がり、2010年末のドラマ<シークレット・ガーデン>のヒョンビン役の人気でチャドナム/チャドニョ/カドナム/カドニョが一斉に大流行。2010-2011年の流行語まとめ記事で常に上位。", "vi": "Cụm từ xuất hiện trong webtoon Tiếng nói trái tim của Jo Seok tập 242 (2008) rồi lan trên các diễn đàn; bùng nổ cuối 2010 khi nhân vật của Hyun Bin trong phim Secret Garden khiến cha-do-nam, cha-do-nyeo, kka-do-nam, kka-do-nyeo phổ biến khắp nơi. Luôn đứng đầu các bảng tổng kết từ thịnh hành 2010-2011."}'::jsonb, '2010~2012년에 폭발적으로 쓰였고 지금은 거의 쓰지 않는다. 같은 뜻으로 요즘은 일본어에서 온 츤데레를 쓰거나, 아예 성격을 풀어 설명한다. 지금 이 말을 쓰면 그 시절을 일부러 소환하는 농담처럼 들린다.', '{"de": "Von 2010 bis 2012 riesig, heute praktisch ausser Gebrauch. Man sagt heute Tsundere (aus dem Japanischen) oder beschreibt den Charakter direkt. Heute klingt es wie ein bewusster Retro-Witz.", "en": "Huge from 2010 to 2012, now basically retired. Today people say tsundere (from Japanese) or just describe the personality. Using it now reads as a deliberate throwback joke.", "es": "Enorme entre 2010 y 2012, hoy practicamente retirado. Ahora se dice tsundere (del japones) o se describe el caracter sin mas. Usarlo hoy suena a broma retro deliberada.", "ja": "2010-2012年に爆発的に使われ、今はほぼ使わない。今は日本語由来のツンデレを使うか、性格をそのまま説明する。今使うとわざと当時を呼び出すネタっぽく聞こえる。", "vi": "Cực thịnh 2010-2012, nay gần như không dùng. Giờ người ta nói tsundere (từ tiếng Nhật) hoặc mô tả thẳng tính cách. Dùng bây giờ nghe như đùa hoài niệm cố ý."}'::jsonb, array['훈남', '뇌섹남', '초식남', '육식남']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Cold city guy (aloof but soft for his person)"}, {"lang": "🇯🇵 JA", "text": "冷たい都会の男(ツンデレ系)"}, {"lang": "🇨🇳 ZH", "text": "高冷都市男(对自己人才温柔)"}, {"lang": "🇻🇳 VI", "text": "Chàng trai thành thị lạnh lùng"}, {"lang": "🇪🇸 ES", "text": "Chico urbano frio (tsundere)"}, {"lang": "🇩🇪 DE", "text": "Kuehler Stadtmann (tsundere-artig)"}]'::jsonb),
('554', '초글링', 'Cho-geul-ring', 'outdated-slang', NULL, '떼로 몰려와 시끄럽게 하는 초등학생을 비하한 2000년대 말', '{"de": "Ein 2000er-Schimpfwort für Kinder, die in lauten Rudeln einfallen", "en": "A 2000s put-down for kids who swarm an online space in noisy packs", "es": "Insulto de los 2000 para los niños que invaden en manada ruidosa", "ja": "群れで押し寄せて騒ぐ小学生をけなした2000年代の言葉", "vi": "Từ hạ thấp thập niên 2000 chỉ lũ trẻ tràn vào ồn ào theo đàn"}'::jsonb, '[초글링]', '[{"type": "명사", "examples": [{"de": "Da kommt wieder der Cho-geul-ring-Schwarm — der Server stirbt.", "es": "Otra vez llega la manada de cho-geul-ring; el servidor va a explotar.", "ja": "またチョグリンが群れで来た、サーバー落ちるわ。", "vi": "Lại một bầy cho-geul-ring tràn vào, server sập mất.", "eng": "The cho-geul-rings are swarming again — the server is going to melt.", "kor": "또 초글링 몰려온다, 서버 터지겠네."}, {"de": "Kennst du Cho-geul-ring? Die alte Version von 잼민이.", "es": "¿Conoces cho-geul-ring? Es la versión antigua de 잼민이.", "ja": "チョグリンって知ってる? 잼민이の昔バージョン。", "vi": "Biết từ cho-geul-ring không? Là bản cũ của 잼민이 đó.", "eng": "Know the word cho-geul-ring? It is the old version of 잼민이.", "kor": "초글링이라는 말 알아? 잼민이 옛날 버전이야."}], "definition": "''초딩''(초등학생)과 스타크래프트 유닛 ''저글링''을 합친 비하 표현. 온라인 게임이나 게시판에 초등학생들이 떼로 들어와 시끄럽게 구는 모습을, 한 마리씩은 약하지만 무리로 몰려오는 저글링에 비유했다. 2005년 전후에 흔히 쓰였고 지금은 ''잼민이''가 그 자리를 대신한다.", "definition_i18n": {"de": "Mischung aus 초딩 (Grundschüler) und der StarCraft-Einheit Zergling — ein Schimpfwort für Kinder, die ein Spiel oder Forum in lauten Rudeln überfluten, wie Zerglinge, die einzeln schwach sind, aber im Schwarm kommen. Um 2005 verbreitet; heute sagt man 잼민이.", "en": "A blend of 초딩 (elementary schooler) and the StarCraft unit Zergling — a put-down for little kids who flood an online game or forum in noisy packs, like Zerglings that are weak alone but come in swarms. Common around 2005; today 잼민이 does the job.", "es": "Mezcla de 초딩 (alumno de primaria) y el Zergling de StarCraft: un insulto para los niños que inundan un juego o foro en manadas ruidosas, como Zerglings débiles solos pero que llegan en enjambre. Común hacia 2005; hoy se dice 잼민이.", "ja": "「초딩」(小学生)とスタークラフトのユニット「ザーグリング」を合わせた侮蔑語。オンラインゲームや掲示板に小学生が群れで来て騒ぐ様子を、単体では弱いが群れで押し寄せるザーグリングに例えた。2005年前後に多用され、今は「잼민이」がその役割。", "vi": "Ghép 초딩 (học sinh tiểu học) với đơn vị Zergling trong StarCraft — từ hạ thấp lũ trẻ tràn vào game hay diễn đàn theo đàn ồn ào, như Zergling yếu khi lẻ nhưng kéo cả bầy. Phổ biến quanh 2005; nay dùng 잼민이."}}]'::jsonb, '2005년 무렵 디시인사이드 등 커뮤니티에서 ''초딩 + 저글링''으로 만들어졌다. 저글링은 스타크래프트의 값싸고 작은 유닛으로, 한 마리는 약하지만 떼로 몰려온다는 점이 비유의 핵심이다. 2020년대에는 ''잼민이''·''급식충''이 대체했는데, 정작 초글링이라 불렸던 세대가 자라서 만든 말이라는 지적도 있다.', '{"de": "Um 2005 in Communities wie DCInside aus 초딩 + Zergling gebildet. Der Zergling ist StarCrafts billige kleine Einheit — allein schwach, im Schwarm furchtbar, und genau das ist die Pointe. In den 2020ern übernahmen 잼민이 und 급식충; dass diese Wörter von genau der Generation stammen, die einst 초글링 hieß, wurde bereits angemerkt.", "en": "Coined around 2005 on communities such as DCInside from 초딩 + Zergling. The Zergling is StarCraft''s cheap little unit — weak alone, terrifying in a swarm, which is the whole joke. In the 2020s 잼민이 and 급식충 took over, and it has been pointed out that those words were coined by the very generation once called 초글링.", "es": "Acuñado hacia 2005 en comunidades como DCInside a partir de 초딩 + Zergling. El Zergling es la unidad pequeña y barata de StarCraft: débil sola, temible en enjambre, y ahí está la gracia. En los 2020 lo relevaron 잼민이 y 급식충, y se ha señalado que esas palabras las creó la propia generación a la que llamaban 초글링.", "ja": "2005年頃、DCインサイドなどのコミュニティで「초딩+ザーグリング」として作られた。ザーグリングはスタークラフトの安い小型ユニットで、単体では弱いが群れで来る点が比喩の核心。2020年代は「잼민이」「급식충」が代替し、しかもそれはかつて초글링と呼ばれた世代が作った言葉だという指摘もある。", "vi": "Ra đời khoảng 2005 trên các cộng đồng như DCInside từ 초딩 + Zergling. Zergling là đơn vị nhỏ rẻ của StarCraft — lẻ thì yếu, cả bầy thì đáng sợ, đó chính là điểm hài. Sang thập niên 2020, 잼민이 và 급식충 thay thế, và có ý kiến rằng chính thế hệ từng bị gọi là 초글링 đã tạo ra những từ đó."}'::jsonb, '명백한 비하 표현이므로 지금은 쓰지 않는 게 좋다. 옛 게시판·커뮤니티 글을 읽을 때 만나는 단어라 뜻만 알아두면 된다. 요즘 같은 뜻으로 쓰이는 ''잼민이''도 비하어인 것은 마찬가지.', '{"de": "Es ist klar abwertend, also nicht verwenden. Nur zum Erkennen in alten Forenbeiträgen. Der moderne Ersatz 잼민이 ist genauso abwertend.", "en": "It is a clear slur, so do not use it. Treat it as a word to recognise in old forum posts, not one to say. Its modern replacement 잼민이 is just as derogatory.", "es": "Es un insulto claro, así que no lo uses. Basta con reconocerlo al leer foros antiguos. Su relevo moderno, 잼민이, es igual de despectivo.", "ja": "明確な侮蔑語なので今は使わないほうがよい。昔の掲示板の書き込みを読むときに出会う語として意味だけ知っておけばよい。現代版の「잼민이」も同じく侮蔑語。", "vi": "Đây rõ ràng là từ hạ thấp nên đừng dùng. Chỉ cần nhận ra khi đọc bài diễn đàn cũ. Từ thay thế hiện đại 잼민이 cũng mang tính hạ thấp như vậy."}'::jsonb, array['잼민이', '급식체', '틀딱']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Swarming bratty kids (2000s slur)"}, {"lang": "🇯🇵 JA", "text": "群れで騒ぐガキ(2000年代の侮蔑語)"}, {"lang": "🇨🇳 ZH", "text": "成群闹事的小屁孩(2000年代贬称)"}, {"lang": "🇻🇳 VI", "text": "Lũ trẻ tràn vào ồn ào (từ hạ thấp 2000s)"}, {"lang": "🇪🇸 ES", "text": "Manada de críos pesados (insulto 2000)"}, {"lang": "🇩🇪 DE", "text": "Rudel nerviger Kinder (2000er-Schimpfwort)"}]'::jsonb),
('555', '행쇼', 'Haeng-Syo', 'outdated-slang', NULL, '''행복하십쇼''의 줄임말, 2012년 유행한 작별 인사', '{"de": "Kurzform von ''Sei glücklich'' — ein Abschiedsspruch von 2012", "en": "Short for ''be happy'' — a 2012 farewell catchphrase", "es": "Abreviatura de ''sé feliz'', muletilla de despedida de 2012", "ja": "「幸せでいてください」の略、2012年に流行した別れの挨拶", "vi": "Viết tắt của ''chúc hạnh phúc'' — câu chào tạm biệt hot năm 2012"}'::jsonb, '[행쇼]', '[{"type": "감탄사", "examples": [{"de": "Ich geh schon mal, Haeng-syo~", "es": "Me voy ya, ¡haeng-syo!", "ja": "お先に行くね、ヘンショ〜", "vi": "Tớ đi trước nhé, haeng-syo~", "eng": "I am heading off first — haeng-syo!", "kor": "나 먼저 간다, 행쇼~"}], "definition": "''행복하십쇼''를 줄인 인사말. 헤어질 때나 말끝에 붙여 ''잘 지내라'', ''행복해라'' 정도의 뜻으로 쓴다. 2012년 한 해 크게 유행했으나 지금은 그 시절을 떠올리게 하는 말로만 남았다.", "definition_i18n": {"de": "Kurzform von ''Sei glücklich''. Wird als Verabschiedung im Sinne von ''Mach''s gut, sei glücklich'' benutzt. 2012 ein Riesenhit, heute nur noch ein nostalgischer Rückgriff.", "en": "A contraction of ''haengbok-hasipsyo'' (be happy). Used as a sign-off meaning roughly ''take care, be happy''. It swept 2012 and now survives mainly as a throwback.", "es": "Contracción de ''sé feliz''. Se usa como despedida con el sentido de ''cuídate, sé feliz''. Arrasó en 2012 y hoy solo sobrevive como guiño nostálgico.", "ja": "「幸せでいてください」の略。別れ際や文末に付けて「元気でね」「幸せにね」ほどの意味で使う。2012年に大流行したが、今は当時を思い出させる言葉として残るだけ。", "vi": "Rút gọn của ''hãy hạnh phúc''. Dùng khi chia tay hoặc cuối câu, nghĩa đại khái ''giữ gìn nhé, vui vẻ nhé''. Bùng nổ năm 2012, giờ chỉ còn là câu gợi nhớ thời đó."}}]'::jsonb, '2012년 9월 29일 방송된 MBC ''무한도전'' 무한상사 특집에 신입사원으로 출연한 지드래곤(권지용)이, 새 유행어를 소개해 달라는 유재석의 요청에 ''행쇼''를 내놓으면서 퍼졌다. 같은 방송에서 ''사나샷(사장님 나이스 샷)'', ''부나샷(부장님 나이스 샷)''도 함께 소개했다.', '{"de": "In der Folge vom 29. September 2012 von MBCs Infinite Challenge (Muhan-Company-Special) trat G-Dragon als neuer Mitarbeiter auf und schlug auf Yoo Jae-suks Bitte um einen neuen Spruch ''Haeng-syo'' vor. Im selben Segment kamen auch ''Sana-Shot'' und ''Buna-Shot'' vor.", "en": "On the 29 September 2012 episode of MBC''s Infinite Challenge (the Muhan Company special), G-Dragon appeared as a new hire and, asked by Yoo Jae-suk to coin a catchphrase, offered ''haeng-syo''. The same segment introduced ''sana-shot'' and ''buna-shot'' (nice shot, boss).", "es": "En el episodio del 29 de septiembre de 2012 de Infinite Challenge (MBC), especial Muhan Company, G-Dragon apareció como nuevo empleado y, ante la petición de Yoo Jae-suk de inventar una muletilla, propuso ''haeng-syo''. En el mismo segmento presentó ''sana-shot'' y ''buna-shot''.", "ja": "2012年9月29日放送のMBC「無限に挑戦」無限商社特集に新入社員として出演したG-DRAGON(クォン・ジヨン)が、ユ・ジェソクに新しい流行語を求められて「ヘンショ」を披露したことで広まった。同じ放送で「サナショット(社長ナイスショット)」「ブナショット(部長ナイスショット)」も紹介された。", "vi": "Trong tập ngày 29/9/2012 của Infinite Challenge (MBC), phần Muhan Company, G-Dragon vào vai nhân viên mới và khi Yoo Jae-suk đề nghị nghĩ một câu cửa miệng mới, anh đưa ra ''haeng-syo''. Cùng tập còn có ''sana-shot'' và ''buna-shot''."}'::jsonb, '헤어질 때 인사 대신 가볍게 던지던 말. 지금은 2012년을 아는 사람끼리의 농담처럼 들리고, 또래 대화에서 진지하게 쓰는 사람은 거의 없다.', '{"de": "Ein lockerer Abschied statt eines richtigen Tschüss. Heute wirkt es wie ein Insiderwitz unter Leuten, die 2012 erlebt haben; ernst benutzt es kaum jemand.", "en": "A light throwaway sign-off instead of a proper goodbye. Today it lands as an in-joke among people who remember 2012; almost nobody uses it straight.", "es": "Una despedida ligera en lugar de un adiós formal. Hoy suena a chiste interno entre quienes recuerdan 2012; casi nadie lo dice en serio.", "ja": "別れ際に挨拶代わりに軽く投げる言葉。今は2012年を知る人同士の冗談のように響き、真面目に使う人はほとんどいない。", "vi": "Câu chào tạm biệt nhẹ nhàng thay cho lời chia tay đàng hoàng. Giờ nghe như câu đùa giữa những người còn nhớ năm 2012; hầu như không ai dùng nghiêm túc."}'::jsonb, array['ㅂㅂ', 'ㅌㅌ', '즐']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Be happy! (2012 sign-off)"}, {"lang": "🇯🇵 JA", "text": "お幸せに!(2012年の別れ言葉)"}, {"lang": "🇨🇳 ZH", "text": "祝你幸福!(2012年流行告别语)"}, {"lang": "🇻🇳 VI", "text": "Chúc hạnh phúc! (câu chào 2012)"}, {"lang": "🇪🇸 ES", "text": "¡Sé feliz! (despedida de 2012)"}, {"lang": "🇩🇪 DE", "text": "Sei glücklich! (Abschied von 2012)"}]'::jsonb),
('556', '프로불편러', 'Peu-Ro-Bul-Pyeon-Reo', 'outdated-slang', NULL, '사소한 일까지 불편해하는 사람을 비꼬는 말', '{"de": "Spitze gegen jemanden, der sich an jeder Kleinigkeit stört", "en": "A jab at someone who takes offense at every little thing", "es": "Pulla para quien se ofende por cualquier nimiedad", "ja": "ささいなことにまで不快感を示す人を皮肉る言葉", "vi": "Câu mỉa người thấy khó chịu với cả những chuyện vụn vặt"}'::jsonb, '[프로불편너]', '[{"type": "명사", "examples": [{"de": "War doch nur ein Witz — und schon kommt der Berufsempörte.", "es": "Solo era una broma y ya apareció el ofendidito profesional.", "ja": "ただの冗談なのにプロ不便ラー登場だね", "vi": "Chỉ là câu đùa thôi mà đã có nhà khó chịu chuyên nghiệp xuất hiện.", "eng": "It was just a joke and here comes the professional complainer.", "kor": "그냥 웃자고 한 말인데 프로불편러 등장했네"}], "definition": "별것 아닌 일을 크게 해석해 불편함을 드러내고 논쟁을 키우는 사람을 비꼬아 부르는 말. ''프로(전문가)+불편+-러(하는 사람)''로 만들어졌다. 2016년 전후 온라인에서 많이 쓰였고, 지금은 정당한 문제 제기를 입막음하는 말이라는 비판과 함께 쓰임이 줄었다.", "definition_i18n": {"de": "Ein sarkastisches Etikett für jemanden, der Kleinigkeiten zur Beschwerde aufbläst und Streit schürt; gebildet aus 프로 (Profi) + 불편 (Unbehagen) + -러 (-er). Um 2016 online groß; der Gebrauch ging zurück, weil ihm vorgeworfen wird, berechtigte Kritik mundtot zu machen.", "en": "A sarcastic label for someone who magnifies trivia into grievance and stokes arguments, built from 프로 (pro) + 불편 (discomfort) + -러 (-er). Big online around 2016; its use has since faded amid criticism that it silences legitimate complaints.", "es": "Etiqueta sarcástica para quien agranda nimiedades hasta convertirlas en agravio y aviva discusiones; se forma con 프로 (pro) + 불편 (incomodidad) + -러 (-dor). Muy usada hacia 2016; su uso decayó ante la crítica de que silencia quejas legítimas.", "ja": "たいしたことのない事柄を大きく解釈して不快感を示し、議論を煽る人を皮肉って呼ぶ言葉。「プロ(専門家)+不便+〜する人(러)」の造語。2016年前後にオンラインで多用されたが、正当な問題提起を封じる言葉だという批判とともに使用が減った。", "vi": "Cách gọi mỉa người phóng đại chuyện nhỏ thành nỗi bất bình rồi khơi mào tranh cãi, ghép từ 프로 (chuyên nghiệp) + 불편 (khó chịu) + -러 (người). Rộ trên mạng quanh 2016; nay ít dùng dần vì bị phê là bịt miệng những ý kiến chính đáng."}}]'::jsonb, '영어 professional의 앞부분 ''프로''에 ''불편''과 사람을 뜻하는 접미사 ''-러''를 붙여 만든 조어다. 처음에는 인터넷 유머 게시글에 과도하게 지적하는 사람을 가리키다가, 사회 전반의 문제 제기에까지 넓게 쓰이게 됐다. 누가 언제 처음 썼는지는 확인되지 않았고, 2016년 무렵 언론에 오르며 널리 알려졌다. 뒤이어 ''화이트불편러''(합리적인 문제 제기를 하는 사람) 같은 파생어도 나왔다.', '{"de": "Gebildet aus 프로 (von englisch ''professional'') + 불편 (Unbehagen) + dem Personensuffix -러. Zunächst zielte es auf Leute, die an Humorbeiträgen herumnörgelten, später auf jede gesellschaftliche Beschwerde. Wer es wann prägte, ist unbelegt; um 2016 kam es in die Presse. Es folgten Ableitungen wie 화이트불편러 für als vernünftig geltende Einwände.", "en": "Coined from 프로 (from English ''professional'') + 불편 (discomfort) + the agent suffix -러. It first targeted people who nitpicked humor posts online, then widened to anyone raising social complaints. Who coined it and when is unverified; it entered the press around 2016. Spin-offs followed, such as 화이트불편러 for someone whose objections are seen as reasonable.", "es": "Acuñado con 프로 (del inglés ''professional'') + 불편 (incomodidad) + el sufijo agentivo -러. Primero apuntaba a quienes puntillaban publicaciones humorísticas y luego se amplió a cualquier queja social. No está verificado quién lo acuñó ni cuándo; llegó a la prensa hacia 2016. Después surgieron derivados como 화이트불편러, para objeciones consideradas razonables.", "ja": "英語 professional の頭「プロ」に「不便」と人を表す接尾辞「-러」を付けた造語。最初はネットのユーモア投稿に過剰な指摘をする人を指し、のちに社会全般の問題提起にまで広がった。誰がいつ最初に使ったかは未確認で、2016年ごろ報道に登場して広く知られた。「ホワイト不便ラー」(合理的な問題提起をする人)のような派生語も生まれた。", "vi": "Ghép từ 프로 (từ ''professional'') + 불편 (khó chịu) + hậu tố chỉ người -러. Ban đầu nhắm vào người bới móc các bài hài trên mạng, sau mở rộng sang mọi ý kiến phản đối xã hội. Ai đặt ra và khi nào thì chưa xác minh được; nó lên báo khoảng năm 2016. Sau đó có các từ phái sinh như 화이트불편러 cho những phản đối được cho là hợp lý."}'::jsonb, '남을 깎아내리는 말이라 대놓고 쓰면 시비가 붙기 쉽다. 요즘은 이 말 자체가 비판받아 예전만큼 쓰이지 않으니, 뜻을 알아듣는 용도로 익혀 두는 편이 낫다.', '{"de": "Es ist eine Herabsetzung, direkt gesagt führt es meist zum Streit. Der Ausdruck selbst steht in der Kritik und wird seltener — besser zum Verstehen lernen als zum Benutzen.", "en": "It is a put-down, so saying it to someone''s face usually starts a fight. The term itself has come under criticism and is less common now — worth knowing to understand, not to use.", "es": "Es un desprecio, así que soltarlo a la cara suele acabar en pelea. El propio término está cuestionado y se usa menos: conviene conocerlo para entenderlo, no para decirlo.", "ja": "人を貶す言葉なので面と向かって使うともめやすい。最近はこの言葉自体が批判され以前ほど使われないので、理解するために覚えておく程度がよい。", "vi": "Đây là lời hạ thấp người khác nên nói thẳng vào mặt dễ gây cãi nhau. Bản thân từ này cũng bị phê phán và nay ít dùng — nên biết để hiểu hơn là để nói."}'::jsonb, array['씹선비', '진지충', '억까']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Professional complainer / easily-offended type"}, {"lang": "🇯🇵 JA", "text": "プロ不便ラー(何にでも不快がる人)"}, {"lang": "🇨🇳 ZH", "text": "职业玻璃心、专业挑刺者"}, {"lang": "🇻🇳 VI", "text": "Nhà khó chịu chuyên nghiệp"}, {"lang": "🇪🇸 ES", "text": "Ofendidito profesional"}, {"lang": "🇩🇪 DE", "text": "Berufsempörter"}]'::jsonb),
('557', '킹카', 'King-ka', 'outdated-slang', NULL, '2000년대 학교에서 제일 잘 나가던 남학생', '{"de": "Das 2000er-Wort für den beliebtesten Jungen der Schule", "en": "The 2000s word for the most popular boy at school", "es": "La palabra de los 2000 para el chico más popular del colegio", "ja": "2000年代に学校で一番人気だった男子を指した言葉", "vi": "Từ thập niên 2000 chỉ nam sinh nổi nhất trường"}'::jsonb, '[킹카]', '[{"type": "명사", "examples": [{"de": "Weißt du noch, wer der King-ka unserer Klasse war?", "es": "¿Te acuerdas de quién era el king-ka de nuestra clase?", "ja": "うちのクラスのキンカ、誰だったか覚えてる?", "vi": "Cậu còn nhớ ai là king-ka của lớp mình không?", "eng": "Remember who the king-ka of our class was?", "kor": "우리 반 킹카가 누구였는지 기억나?"}, {"de": "''King-ka''? Du verrätst dein Alter.", "es": "¿''King-ka''? Se te nota la edad.", "ja": "キンカって、めっちゃ昔の人じゃん。", "vi": "''King-ka'' á? Nghe là biết bạn thuộc thế hệ trước rồi.", "eng": "''King-ka''? You are showing your age.", "kor": "킹카라니, 너 완전 옛날 사람이네."}], "definition": "학교나 모임에서 외모·인기·존재감이 가장 뛰어난 남자. 여자는 ''퀸카''라고 했다. 얼굴만 잘생긴 게 아니라 ''그 반에서 제일 잘 나가는 한 명''이라는 서열의 뜻이 핵심. 2000년대 초중반 10대·20대가 즐겨 쓰다가 2010년대에 ''인싸'', ''존잘''에 자리를 넘겨줬다.", "definition_i18n": {"de": "Der bestaussehende, beliebteste Junge einer Klasse oder Gruppe; die weibliche Form war 퀸카. Es geht nicht nur ums Aussehen: Kern ist, DER eine zu sein, den alle kennen. Blüte in den frühen bis mittleren 2000ern, in den 2010ern von 인싸 und 존잘 abgelöst.", "en": "The best-looking, most popular guy in a class or group — the female version was 퀸카. It is not just about looks: the point is being THE one guy everyone knows. Peaked in the early-to-mid 2000s, then lost out to 인싸 and 존잘 in the 2010s.", "es": "El chico más guapo y popular de la clase o del grupo; la versión femenina era 퀸카. No va solo de guapura: la clave es ser EL chico que todos conocen. Reinó a principios y mediados de los 2000 y en los 2010 lo sustituyeron 인싸 y 존잘.", "ja": "クラスや集まりで外見・人気・存在感が一番の男子。女子は「퀸카」。顔だけでなく「その中で一番目立つ一人」という序列の意味が核心。2000年代前半に流行し、2010年代には「인싸」「존잘」に取って代わられた。", "vi": "Nam sinh nổi nhất lớp hay nhóm về ngoại hình, độ nổi tiếng và sức hút; bản nữ là 퀸카. Không chỉ là đẹp trai: cốt lõi là ''người duy nhất ai cũng biết''. Thịnh hành đầu-giữa thập niên 2000, sang 2010 bị 인싸 và 존잘 thay thế."}}]'::jsonb, '어원은 확정되지 않았다. 표준국어대사전은 ''king←card''로 적고 중세 유럽 사교계의 King Card에서 왔다는 설이 널리 퍼져 있지만, 근거가 없다는 반론이 있다. 1970년대 미팅(단체 소개팅) 은어에서 시작됐다는 설과 일본어 ''킨카(きんか)''에서 왔다는 설도 있어, 어느 하나로 단정할 수 없다.', '{"de": "Die Herkunft ist ungeklärt. Das Standardwörterbuch notiert ''king←card'', und die Geschichte einer mittelalterlichen ''King Card'' ist verbreitet, wurde aber als unbelegt bestritten. Weitere Theorien: Slang der Gruppen-Blinddates der 1970er oder japanisch kinka. Keine ist bestätigt.", "en": "The etymology is unsettled. The Standard Korean Dictionary writes ''king←card'', and the story of a medieval European ''King Card'' is widespread but has been challenged as baseless. Other theories trace it to 1970s group-blind-date slang or to Japanese kinka. None is confirmed.", "es": "La etimología no está resuelta. El diccionario estándar anota ''king←card'' y circula la historia de un ''King Card'' europeo medieval, pero se ha cuestionado por infundada. Otras teorías la remontan a la jerga de citas grupales de los 70 o al japonés kinka. Ninguna está confirmada.", "ja": "語源は未確定。標準国語大辞典は「king←card」と記し、中世ヨーロッパ社交界のKing Card由来説が広まっているが根拠がないという反論もある。1970年代の合コン隠語説、日本語「きんか」説もあり断定できない。", "vi": "Từ nguyên chưa xác định. Từ điển chuẩn ghi ''king←card'' và thuyết ''King Card'' thời trung cổ châu Âu phổ biến nhưng bị phản bác là vô căn cứ. Còn thuyết từ tiếng lóng hẹn hò nhóm thập niên 1970 và thuyết tiếng Nhật kinka. Không thuyết nào được xác nhận."}'::jsonb, '지금 10대·20대에게 쓰면 ''옛날 사람'' 소리를 듣는다. 2020년대에는 같은 자리를 ''인싸'', ''존잘''이 맡는다. 단, 여성형 ''퀸카''는 2023년 (여자)아이들의 노래 제목으로 다시 알려져 킹카보다 훨씬 오래 살아남았다 — 퀸카는 통하지만 킹카는 안 통하는 비대칭에 주의.', '{"de": "Wer es heute zu Teenagern oder Zwanzigjährigen sagt, klingt altmodisch; die Rolle übernehmen 인싸 und 존잘. Achtung auf die Asymmetrie: Die weibliche Form 퀸카 wurde 2023 als (G)I-DLE-Songtitel wiederbelebt und ist noch verständlich, 킹카 nicht.", "en": "Say it to a Korean in their teens or twenties today and you will sound dated; 인싸 and 존잘 fill that slot now. Note the asymmetry: the female form 퀸카 was revived in 2023 as a (G)I-DLE song title and is still understood, while 킹카 is not.", "es": "Si se lo dices hoy a alguien de 15 o 25 años, sonarás anticuado; ese hueco lo ocupan 인싸 y 존잘. Ojo con la asimetría: la forma femenina 퀸카 revivió en 2023 como título de una canción de (G)I-DLE y sigue viva, 킹카 no.", "ja": "今の10〜20代に使うと「昔の人」扱いされる。同じ位置は「인싸」「존잘」が担う。ただし女性形「퀸카」は2023年に(G)I-DLEの曲名で復活し今も通じる — 퀸카は通じるが킹카は通じない非対称に注意。", "vi": "Nói với người Hàn tuổi teen hay 20 bây giờ là nghe rất cũ; chỗ đó nay là 인싸 và 존잘. Lưu ý bất đối xứng: dạng nữ 퀸카 được hồi sinh năm 2023 làm tên bài hát của (G)I-DLE nên vẫn hiểu được, còn 킹카 thì không."}'::jsonb, array['인싸', '존잘', '얼짱']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "The hottest guy in school (2000s slang)"}, {"lang": "🇯🇵 JA", "text": "学校で一番人気の男子(2000年代語)"}, {"lang": "🇨🇳 ZH", "text": "校园里最受欢迎的男生(2000年代用语)"}, {"lang": "🇻🇳 VI", "text": "Nam sinh nổi nhất trường (tiếng lóng 2000s)"}, {"lang": "🇪🇸 ES", "text": "El chico más popular del colegio (jerga 2000)"}, {"lang": "🇩🇪 DE", "text": "Der beliebteste Junge der Schule (2000er-Slang)"}]'::jsonb),
('558', '긔엽긔', 'Gui-yeop-gui', 'outdated-slang', NULL, '''귀엽다''를 애교스럽게 적던 2000년대 싸이월드 말투', '{"de": "Die süßliche 2000er-Cyworld-Schreibweise für ''so süß''", "en": "The cutesy 2000s Cyworld way of writing ''so cute''", "es": "La forma cursi de escribir ''qué lindo'' en el Cyworld de los 2000", "ja": "「かわいい」を甘えた調子で書いた2000年代サイワールド語", "vi": "Cách viết ''đáng yêu'' kiểu nhí nhảnh trên Cyworld thập niên 2000"}'::jsonb, '[귀엽귀]', '[{"type": "감탄사", "examples": [{"de": "Dieser Welpe ist echt gui-yeop-gui.", "es": "Este cachorro es súper gui-yeop-gui.", "ja": "この子犬まじでクィヨプクィ", "vi": "Con cún này gui-yeop-gui thật sự.", "eng": "This puppy is so gui-yeop-gui.", "kor": "이 강아지 진짜 긔엽긔"}, {"de": "In der Cyworld-Zeit schrieb das jeder so-gui.", "es": "En la época de Cyworld todo el mundo escribía así-gui.", "ja": "サイワールド時代はみんなこう書いてたクィ", "vi": "Thời Cyworld ai cũng viết kiểu này-gui.", "eng": "Back in the Cyworld days everyone wrote like this-gui.", "kor": "싸이월드 시절엔 다 이렇게 썼긔"}], "definition": "''귀엽귀''(귀엽다)를 지금은 쓰지 않는 음절 ''긔''로 바꿔 적은 말. 문장을 ''-긔''로 끝내 애교를 부리는 말투 전체를 ''긔체''라 불렀고, 그중 가장 많이 쓰인 단어가 긔엽긔다. 읽을 때는 그냥 ''귀엽귀''로 읽는다.", "definition_i18n": {"de": "''Süßi-süß'', geschrieben mit 긔, einer Silbe, die das moderne Koreanisch nicht verwendet. Die ganze Angewohnheit, Sätze auf -긔 enden zu lassen, hieß 긔체, und 긔엽긔 war ihr Paradewort. Gelesen wird es einfach ''gwi-yeop-gwi''.", "en": "''Cutie-cute'' respelled with 긔, a syllable modern Korean never uses. The whole habit of ending sentences in -긔 to sound adorable was called 긔체, and 긔엽긔 was its most-used word. It is simply read as ''gwi-yeop-gwi''.", "es": "''Lindito-lindo'' reescrito con 긔, una sílaba que el coreano actual no usa. A la costumbre de terminar frases en -긔 para sonar adorable se le llamaba 긔체, y 긔엽긔 era su palabra estrella. Se lee simplemente ''gwi-yeop-gwi''.", "ja": "「귀엽귀(かわいい)」を現代語では使わない音節「긔」に置き換えた語。文末を「-긔」で終える甘え口調全体を「긔체」と呼び、その代表語が긔엽긔。読みは普通に「クィヨプクィ」。", "vi": "''Đáng yêu-yêu'' viết lại bằng âm tiết 긔 mà tiếng Hàn hiện đại không dùng. Toàn bộ thói kết câu bằng -긔 cho dễ thương được gọi là 긔체, và 긔엽긔 là từ tiêu biểu. Đọc đơn giản là ''gwi-yeop-gwi''."}}]'::jsonb, '유래에 여러 설이 있으며 확정되지 않았다. 널리 퍼진 설은 2000년대 초 인터넷 ''얼짱''으로 유명했던 한 남성 사용자의 싸이월드 글에 어떤 팬이 ''-긔''로 끝나는 닉네임·댓글을 달았고, 이후 얼짱 관련 카페에서 그 말투를 조롱하며 흉내 낸 것이 ''긔체''로 굳었다는 것이다. 다른 설명은 특정 인물 없이, 당시 유행한 ''외계어''(문자를 일부러 낯설게 바꿔 쓰기)의 한 갈래로 자연히 퍼졌다고만 본다.', '{"de": "Es kursieren mehrere Versionen, keine ist bestätigt. Die verbreitete: Anfang der 2000er hinterließ ein Fan auf der Cyworld-Seite eines als Internet-''Schönheitskönig'' bekannten Nutzers Nicknames und Kommentare auf -긔; Communities ahmten diesen Ton dann spöttisch nach, bis 긔체 sich festsetzte. Andere Versionen nennen niemanden und ordnen es nur der damaligen 외계어-Mode ein, Hangul absichtlich zu verfremden.", "en": "Several accounts circulate and none is settled. The widespread one: in the early 2000s a fan left -긔 nicknames and comments on the Cyworld page of a male user famous as an internet ''looks king'', and communities then mimicked that style mockingly until 긔체 stuck. Other accounts name no individual and simply place it within the era''s 외계어 fad of deliberately misspelling Hangul.", "es": "Circulan varias versiones y ninguna está confirmada. La más difundida: a principios de los 2000, una fan dejó apodos y comentarios terminados en -긔 en el Cyworld de un usuario famoso como ''rey de la belleza'' de internet, y luego las comunidades imitaron ese tono en burla hasta que 긔체 cuajó. Otras versiones no señalan a nadie y lo sitúan sin más en la moda del 외계어 de la época, escribir hangul mal a propósito.", "ja": "由来は諸説あり未確定。広く知られる説は、2000年代初めにネット「オルチャン」として有名だった男性ユーザーのサイワールドに、あるファンが「-긔」で終わるニックネームやコメントを残し、その後コミュニティがその口調を嘲笑して真似たことから「긔체」が定着したというもの。別の説は特定人物を挙げず、当時流行した「外界語」(文字をわざと崩す遊び)の一種として自然に広まったとする。", "vi": "Có nhiều thuyết và chưa thuyết nào được xác nhận. Thuyết phổ biến: đầu thập niên 2000, một fan để lại nickname và bình luận kết thúc bằng -긔 trên Cyworld của một nam người dùng nổi tiếng là ''ngôi sao ngoại hình'' trên mạng, rồi các cộng đồng bắt chước giọng đó để trêu cho đến khi 긔체 thành nếp. Các thuyết khác không nêu cá nhân nào, chỉ xếp nó vào trào lưu 외계어 thời đó — cố tình viết sai Hangul."}'::jsonb, '지금 쓰면 싸이월드 시절을 일부러 흉내는 농담으로만 읽힌다. 문장 끝을 ''-긔''로 바꾸면 어떤 말이든 긔체가 된다(했긔, 좋긔). 요즘 같은 애교 말투는 ''-뀨'', ''-냐옹''이나 그냥 ''ㅎㅎ''가 맡는다. 참고로 ''긔'' 자체는 현대 한국어에서 쓰지 않는 음절이라 키보드로 치려면 ㄱ+ㅡ+ㅣ를 눌러야 한다.', '{"de": "Heute liest es sich nur als bewusster Cyworld-Witz. Tausche jede Satzendung gegen -긔 und du hast 긔체 (했긔, 좋긔). Moderne süßliche Entsprechungen: -뀨, -냐옹 oder einfach ㅎㅎ. Beachte: 긔 ist keine Silbe des modernen Koreanisch, man tippt sie als ㄱ + ㅡ + ㅣ.", "en": "Today it only reads as a knowing Cyworld-era joke. Swap any sentence ending for -긔 and you have 긔체 (했긔, 좋긔). The modern cutesy equivalents are -뀨, -냐옹 or just ㅎㅎ. Note that 긔 is not a syllable modern Korean uses, so you type it as ㄱ + ㅡ + ㅣ.", "es": "Hoy solo se lee como un guiño a la era Cyworld. Cambia el final de cualquier frase por -긔 y ya tienes 긔체 (했긔, 좋긔). Los equivalentes cursis actuales son -뀨, -냐옹 o un simple ㅎㅎ. Ojo: 긔 no es una sílaba del coreano actual, se teclea ㄱ + ㅡ + ㅣ.", "ja": "今使うとサイワールド時代をわざと真似たジョークとしてしか読まれない。文末を「-긔」に変えれば何でも긔체になる(했긔、좋긔)。現代の甘え口調は「-뀨」「-냐옹」や単なる「ㅎㅎ」。なお「긔」は現代韓国語では使わない音節なので、入力はㄱ+ㅡ+ㅣ。", "vi": "Ngày nay chỉ đọc như một câu đùa cố tình gợi thời Cyworld. Đổi đuôi câu thành -긔 là ra 긔체 (했긔, 좋긔). Tương đương nhí nhảnh hiện nay là -뀨, -냐옹 hoặc chỉ ㅎㅎ. Lưu ý 긔 không phải âm tiết tiếng Hàn hiện đại, phải gõ ㄱ + ㅡ + ㅣ."}'::jsonb, array['졸귀', '커엽다', '얼짱', '방가방가']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "So cute (cutesy 2000s spelling)"}, {"lang": "🇯🇵 JA", "text": "かわいい(2000年代の甘え表記)"}, {"lang": "🇨🇳 ZH", "text": "好可爱(2000年代卖萌写法)"}, {"lang": "🇻🇳 VI", "text": "Đáng yêu quá (cách viết nhí nhảnh 2000s)"}, {"lang": "🇪🇸 ES", "text": "Qué lindo (grafía cursi de los 2000)"}, {"lang": "🇩🇪 DE", "text": "So süß (süßliche 2000er-Schreibweise)"}]'::jsonb),
('559', '대략난감', 'Dae-Ryak-Nan-Gam', 'outdated-slang', 'exclamation', '뭐라 할 말이 없을 만큼 당황스럽다 — 2000년대 인터넷 유행어', '{"de": "So peinlich, dass einem nichts einfaellt — ein Internet-Spruch der 2000er", "en": "So awkward you have nothing to say — a 2000s internet catchphrase", "es": "Tan incomodo que te quedas sin palabras — muletilla de internet de los 2000", "ja": "言葉に詰まるほど気まずい — 2000年代のネット流行語", "vi": "Khó xử đến mức không biết nói gì — câu cửa miệng mạng thập niên 2000"}'::jsonb, '[대량난감]', '[{"type": "명사", "examples": [{"de": "Ich habe meine Mutter beim Lesen meiner KakaoTalk-Nachrichten erwischt … Dae-ryak-nan-gam.", "es": "Pille a mi madre leyendo mis mensajes de KakaoTalk… dae-ryak-nan-gam.", "ja": "ママが私のカカオトークを読んでるのを見ちゃって…デリャクナンガム。", "vi": "Bắt gặp mẹ đang đọc tin nhắn KakaoTalk của mình… dae-ryak-nan-gam.", "eng": "I caught my mom reading my KakaoTalk messages… dae-ryak-nan-gam.", "kor": "엄마가 내 카톡 읽는 걸 봤는데… 대략난감."}, {"de": "Ich kam zum Blind Date und mein Ex sass da. Wirklich Dae-ryak-nan-gam.", "es": "Fui a una cita a ciegas y alli estaba mi ex. De verdad, dae-ryak-nan-gam.", "ja": "合コンに行ったら元カレが座ってた。マジでデリャクナンガムだった。", "vi": "Đi xem mắt thì thấy người yêu cũ ngồi đó. Đúng kiểu dae-ryak-nan-gam.", "eng": "I showed up to a blind date and my ex was sitting there. Truly dae-ryak-nan-gam.", "kor": "소개팅 나갔는데 전 남친이 앉아 있었어. 진짜 대략난감이었지."}], "definition": "대략(대체로)과 난감(어찌할 바를 모름)을 붙인 말로, 상황이 몹시 당황스럽고 어색해서 뭐라 반응해야 할지 모르겠다는 뜻이다. 네 글자에 한자로 이루어져 사자성어처럼 보이지만 전통 성어가 아니라 인터넷에서 만들어진 조어다.", "definition_i18n": {"de": "Dae-ryak (ungefaehr) plus Nan-gam (ratlos) — eine Lage, die so unangenehm ist, dass man nicht weiss, wie man reagieren soll. Vier Hanja-Zeichen lassen es wie eine klassische Redewendung aussehen, doch es ist eine Internet-Neuschoepfung.", "en": "Dae-ryak (roughly) plus nan-gam (at a loss) — a situation so awkward you do not know how to react. Four hanja characters make it look like a classical idiom, but it is an internet coinage, not a real four-character idiom.", "es": "Dae-ryak (mas o menos) mas nan-gam (sin saber que hacer): una situacion tan incomoda que no sabes como reaccionar. Sus cuatro caracteres hanja lo hacen parecer una locucion clasica, pero es un invento de internet, no un modismo real.", "ja": "デリャク(おおむね)とナンガム(どうしてよいかわからない)を合わせた語で、状況が気まずすぎてどう反応していいかわからないという意味。漢字四文字で四字熟語に見えるが、伝統的な成語ではなくネットで作られた造語。", "vi": "Dae-ryak (đại khái) ghép với nan-gam (không biết xoay xở): tình huống khó xử đến mức không biết phản ứng ra sao. Bốn chữ Hán khiến nó trông như thành ngữ bốn chữ, nhưng thật ra là từ do dân mạng chế, không phải thành ngữ cổ."}}]'::jsonb, '2000년대 초 인터넷 커뮤니티에서 쓰이기 시작했으나 정확한 발생 시점은 어느 출처도 특정하지 못한다. 공통으로 확인되는 것은 2006년 드라마 <궁> 이후 언론에 급격히 자주 등장했다는 점이다. 초기에는 대략 난감으로 띄어 쓰거나 대략에 따옴표를 붙이는 표기가 섞여 있었는데, 이는 당시 언론이 이 말을 아직 한 단어로 인정하지 않았다는 흔적이다. 아햏햏과 같은 2000년대 초 디시인사이드발 유행어 흐름 속에서 자란 말이다.', '{"de": "Es begann in Online-Foren der fruehen 2000er, den genauen Moment nennt keine Quelle. Einig sind sich alle, dass die Presseverwendung nach der Serie Goong von 2006 sprunghaft anstieg. Anfangs schrieb man es getrennt oder setzte Dae-ryak in Anfuehrungszeichen — eine Spur davon, dass Zeitungen es noch nicht als ein Wort behandelten. Es wuchs aus derselben DCInside-Welle der fruehen 2000er wie A-haet-haet.", "en": "It started in early-2000s online communities, though no source pins the exact moment. What every account agrees on is that press usage spiked after the 2006 drama Goong. Early on it was written spaced out or with quotation marks around dae-ryak — a trace of newspapers not yet treating it as one word. It grew out of the same early-2000s DCInside wave that produced a-haet-haet.", "es": "Comenzo en los foros de inicios de los 2000, aunque ninguna fuente fija el momento exacto. Todos coinciden en que su presencia en prensa se disparo tras el drama Goong de 2006. Al principio se escribia separado o con comillas en dae-ryak, rastro de que los periodicos aun no lo trataban como una sola palabra. Crecio dentro de la misma ola de DCInside de inicios de los 2000 que dio a-haet-haet.", "ja": "2000年代初めのネットコミュニティで使われ始めたが、正確な発生時期はどの出典も特定していない。共通して確認できるのは2006年のドラマ<宮>以降、報道での露出が急増した点。初期は分かち書きしたりデリャクに引用符を付けたりする表記が混在し、当時のメディアがまだ一語と認めていなかった痕跡が残る。アヘッヘッなど2000年代初頭のDCインサイド発の流行語の流れの中で育った語。", "vi": "Bắt đầu từ các diễn đàn đầu thập niên 2000, dù không nguồn nào xác định thời điểm chính xác. Điểm chung là báo chí dùng nhiều hẳn lên sau bộ phim Goong năm 2006. Thời đầu nó được viết tách rời hoặc để dae-ryak trong ngoặc kép — dấu vết cho thấy báo chí chưa coi đó là một từ. Nó lớn lên trong cùng làn sóng DCInside đầu 2000 sinh ra a-haet-haet."}'::jsonb, '2000년대 중후반에 아주 흔했고 지금은 거의 쓰지 않는다. 같은 상황에서 요즘은 갑분싸, 현타, 멘붕이나 그냥 어쩔 줄 모르겠다고 말한다. 지금 대략난감이라고 쓰면 2000년대 인터넷을 아는 사람이라는 신호처럼 읽힌다.', '{"de": "Mitte bis Ende der 2000er sehr gelaeufig, heute so gut wie verschwunden. Fuer denselben Moment sagt man heute Gap-bun-ssa, Hyeon-ta, Men-bung oder beschreibt die Ratlosigkeit einfach. Wer es heute benutzt, signalisiert, dass er das Internet der 2000er kennt.", "en": "Very common in the mid-to-late 2000s, now nearly gone. For the same moment people today say gap-bun-ssa, hyeon-ta, men-bung, or just describe being at a loss. Using it now signals that you remember the 2000s internet.", "es": "Muy frecuente a mediados y finales de los 2000, hoy practicamente desaparecido. Para ese mismo momento hoy se dice gap-bun-ssa, hyeon-ta, men-bung, o simplemente se describe el apuro. Usarlo ahora indica que recuerdas el internet de los 2000.", "ja": "2000年代半ばから後半に非常によく使われ、今はほぼ使わない。同じ場面では今はカプブンサ、ヒョンタ、メンブンと言うか、単に困ったと説明する。今これを使うと2000年代のネットを知る人という合図に読まれる。", "vi": "Rất phổ biến giữa và cuối thập niên 2000, nay gần như biến mất. Cùng tình huống ấy, giờ người ta nói gap-bun-ssa, hyeon-ta, men-bung, hoặc chỉ tả thẳng là chẳng biết làm sao. Dùng bây giờ là dấu hiệu bạn còn nhớ internet thập niên 2000."}'::jsonb, array['갑분싸', '멘붕', '현타', '안습', '뭥미']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Awkward beyond words / at a total loss"}, {"lang": "🇯🇵 JA", "text": "何とも気まずい・返答に困る"}, {"lang": "🇨🇳 ZH", "text": "尴尬到无言以对"}, {"lang": "🇻🇳 VI", "text": "Khó xử không biết nói gì"}, {"lang": "🇪🇸 ES", "text": "Incomodo sin palabras"}, {"lang": "🇩🇪 DE", "text": "Sprachlos peinlich"}]'::jsonb),
('560', '빵셔틀', 'Ppang-Syeo-Teul', 'outdated-slang', NULL, '일진의 빵 심부름을 강요당하던 학생 — 2010년 전후 학교폭력 용어', '{"de": "Ein Schueler, der fuer Schlaeger Snacks holen muss — Schulgewalt-Vokabular um 2010", "en": "A student forced to fetch snacks for bullies — school-violence vocabulary from around 2010", "es": "Alumno obligado a comprar meriendas a los matones — vocabulario de acoso escolar de hacia 2010", "ja": "不良の代わりにパンを買わされる生徒 — 2010年前後の学校暴力用語", "vi": "Học sinh bị ép đi mua đồ ăn cho đám bắt nạt — từ vựng bạo lực học đường quanh 2010"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Damals stand das Wort Ppang-syeo-teul jeden Tag in den Nachrichten.", "es": "En aquella epoca la palabra ppang-syeo-teul salia en las noticias cada dia.", "ja": "あの頃はパンシャトルという言葉が毎日ニュースに出てた。", "vi": "Hồi đó từ ppang-syeo-teul ngày nào cũng lên tin tức.", "eng": "Back then the word ppang-syeo-teul was in the news every single day.", "kor": "그 시절엔 빵셔틀이라는 말이 뉴스에 매일 나왔어."}, {"de": "2012 stufte das Bildungsministerium Ppang-syeo-teul als Schulgewalt ein und machte es strafbar.", "es": "En 2012 el ministerio de Educacion clasifico el ppang-syeo-teul como violencia escolar y paso a ser sancionable.", "ja": "2012年に教育部がパンシャトルを学校暴力と規定し、処罰の対象になった。", "vi": "Năm 2012 Bộ Giáo dục xếp ppang-syeo-teul vào bạo lực học đường và nó trở thành hành vi bị xử phạt.", "eng": "In 2012 the education ministry classified ppang-syeo-teul as school violence, making it punishable.", "kor": "2012년에 교육부가 빵셔틀을 학교폭력으로 규정하면서 처벌 대상이 됐다."}], "definition": "학교에서 힘센 학생들에게 협박당해 매점에서 빵이나 간식을 대신 사다 주는 학생, 또는 그 행위. 심부름 종류에 따라 담배 셔틀, 핸드폰 셔틀, 와이파이 셔틀처럼 앞말만 바꿔 쓰는 말들이 함께 생겼다. 놀림처럼 들리지만 실제로는 강요·갈취를 가리키는 학교폭력 용어다.", "definition_i18n": {"de": "Ein Schueler, den staerkere Mitschueler zwingen, ihnen im Schulkiosk Brot oder Snacks zu holen, oder die Handlung selbst. Varianten tauschten das erste Wort: Zigaretten-Shuttle, Handy-Shuttle, WLAN-Shuttle. Es klingt nach Neckerei, benennt aber Noetigung und Erpressung — ein Begriff aus der Schulgewalt.", "en": "A student coerced by stronger classmates into buying bread or snacks for them at the school shop, or the act itself. Variants swapped the first word: cigarette shuttle, phone shuttle, wifi shuttle. It sounds like teasing, but it names coercion and extortion — a school-violence term.", "es": "Alumno al que compañeros mas fuertes obligan a comprarles pan o meriendas en la tienda del colegio, o el propio acto. Variantes cambiaban la primera palabra: shuttle de tabaco, shuttle de movil, shuttle de wifi. Suena a burla, pero designa coaccion y extorsion: es terminologia de acoso escolar.", "ja": "学校で力の強い生徒に脅され、購買でパンや軽食を代わりに買わされる生徒、またはその行為。使い走りの中身に応じてタバコシャトル、携帯シャトル、ワイファイシャトルのように前の語だけ替えた言葉も生まれた。からかいのように聞こえるが、実際は強要・恐喝を指す学校暴力の用語。", "vi": "Học sinh bị bạn mạnh hơn ép đi mua bánh mì hay đồ ăn vặt ở căng tin, hoặc chính hành vi đó. Các biến thể đổi chữ đầu: shuttle thuốc lá, shuttle điện thoại, shuttle wifi. Nghe như trêu chọc nhưng thực chất chỉ sự cưỡng ép và tống tiền — đây là từ về bạo lực học đường."}}]'::jsonb, '셔틀은 전략 시뮬레이션 게임 스타크래프트에서 병력을 실어 나르는 수송 유닛의 이름이다. 심부름을 반복해서 실어 나른다는 뜻으로 학생들이 이 이름을 가져다 붙였다. 2009년 무렵 온라인에서 퍼졌고 2010년 1월 교육과학기술부가 학교폭력 예방 대책에 이 유형을 포함시키면서 언론 보도가 급증했다.', '{"de": "Shuttle ist die Transporteinheit, die im Strategiespiel StarCraft Truppen befoerdert; Schueler uebertrugen den Namen auf jemanden, der immer wieder Besorgungen schleppen muss. Es verbreitete sich um 2009 online, und die Berichterstattung schnellte im Januar 2010 hoch, als das Bildungsministerium dieses Muster in seinen Praeventionsplan gegen Schulgewalt aufnahm.", "en": "Shuttle is the transport unit that ferries troops in the strategy game StarCraft; students borrowed the name for someone made to ferry errands over and over. It spread online around 2009, and press coverage spiked in January 2010 when the education ministry folded this pattern into its school-violence prevention plan.", "es": "Shuttle es la unidad de transporte que traslada tropas en el juego de estrategia StarCraft; los alumnos tomaron el nombre para quien es obligado a acarrear recados una y otra vez. Se difundio en linea hacia 2009 y la cobertura mediatica se disparo en enero de 2010, cuando el ministerio de Educacion incluyo esta modalidad en su plan de prevencion del acoso escolar.", "ja": "シャトルは戦略シミュレーションゲーム、スタークラフトで兵力を運ぶ輸送ユニットの名。使い走りを繰り返し運ばされる者にその名を当てた。2009年頃ネットで広まり、2010年1月に教育科学技術部が学校暴力予防対策にこの類型を含めたことで報道が急増した。", "vi": "Shuttle là đơn vị vận tải chở quân trong game chiến thuật StarCraft; học sinh mượn tên đó cho người bị bắt chạy vặt hết lần này đến lần khác. Nó lan trên mạng khoảng 2009, và báo chí đưa tin dồn dập từ tháng 1 năm 2010 khi Bộ Giáo dục đưa hình thức này vào kế hoạch phòng chống bạo lực học đường."}'::jsonb, '2010년 전후 몇 년간 뉴스와 학교 현장에서 널리 쓰였고 지금은 거의 들리지 않는다. 학교폭력 자체가 사라져서가 아니라, 대책과 보도의 초점이 사이버폭력·단톡방 괴롭힘 쪽으로 옮겨 가면서 이 말이 쓰일 자리가 줄었다. 피해를 가리키는 말이므로 농담조로 쓰지 않는 것이 좋다.', '{"de": "Einige Jahre um 2010 in Nachrichten und an Schulen weit verbreitet, heute kaum noch zu hoeren. Nicht weil Schulgewalt aufgehoert haette, sondern weil Praevention und Berichterstattung sich zu Cybermobbing und Gruppenchat-Schikane verschoben haben. Das Wort benennt eine Form von Viktimisierung und sollte nicht scherzhaft verwendet werden.", "en": "Widely used in the news and in schools for a few years around 2010, rarely heard now. Not because school violence ended, but because prevention efforts and reporting shifted toward cyberbullying and group-chat harassment, leaving this word fewer occasions. It names a form of victimisation, so it is best not used as a joke.", "es": "Muy usado en prensa y en los colegios durante unos años alrededor de 2010, hoy apenas se oye. No porque el acoso escolar acabara, sino porque la prevencion y la cobertura se desplazaron al ciberacoso y al acoso en chats grupales, dejando menos ocasiones para la palabra. Designa una forma de victimizacion, asi que conviene no usarla en broma.", "ja": "2010年前後の数年間、報道と学校現場で広く使われたが今はほとんど聞かない。学校暴力がなくなったからではなく、対策と報道の焦点がサイバー暴力やグループチャットのいじめへ移り、この語の出番が減ったため。被害を指す語なので冗談めかして使わない方がよい。", "vi": "Được dùng rộng rãi trên báo chí và trong trường học vài năm quanh 2010, nay hiếm khi nghe. Không phải vì bạo lực học đường đã hết, mà vì trọng tâm phòng chống và đưa tin đã chuyển sang bắt nạt trên mạng và trong nhóm chat, khiến từ này ít dịp dùng. Đây là từ chỉ sự bị hại, nên đừng dùng đùa."}'::jsonb, array['고문관', '박제', '급식체']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Bread shuttle (bullied errand runner)"}, {"lang": "🇯🇵 JA", "text": "パンシャトル(使い走りをさせられる生徒)"}, {"lang": "🇨🇳 ZH", "text": "面包跑腿(被霸凌者)"}, {"lang": "🇻🇳 VI", "text": "Shuttle bánh mì (học sinh bị sai vặt)"}, {"lang": "🇪🇸 ES", "text": "Shuttle del pan (alumno mandadero por acoso)"}, {"lang": "🇩🇪 DE", "text": "Brot-Shuttle (gemobbter Botengaenger)"}]'::jsonb),
('561', '뽀대', 'Ppo-dae', 'outdated-slang', NULL, '폼 나는 겉모습, 멋', '{"de": "Style, eine Erscheinung, die sitzt", "en": "Swagger, a look that lands", "es": "Estilo, pinta que impone", "ja": "格好よさ、決まった見た目", "vi": "Vẻ ngầu, phong độ bắt mắt"}'::jsonb, NULL, '[{"type": "명사", "examples": [{"de": "Der Typ in der Lederjacke sah echt scharf aus.", "es": "Ese tío con la cazadora de cuero tenía una pinta que no veas.", "ja": "あの兄さん、革ジャン着たらめっちゃ決まってたよ。", "vi": "Ông anh đó mặc áo da vào trông ngầu phết.", "eng": "That guy in the leather jacket? He looked seriously sharp.", "kor": "그 형 가죽자켓 입으니까 뽀대 나더라."}], "definition": "사람이나 물건에서 느껴지는 폼 나는 모양새. 거의 언제나 「뽀대(가) 난다」 꼴로 써서 「멋지다」를 뜻했다. 아주 멋질 때는 「뽀대작살」이라고 했다. 옷차림뿐 아니라 차·가방·자세 등 겉으로 드러나는 모든 것에 쓸 수 있었다.", "definition_i18n": {"de": "Die eindrucksvolle Ausstrahlung von jemandem oder etwas. Fast immer als 뽀대(가) 난다 (das sieht scharf aus) im Sinn von cool; 뽀대작살 für richtig cool. Galt nicht nur für Kleidung, sondern für Autos, Taschen, Haltung — alles Sichtbare.", "en": "The impressive look something or someone gives off. Almost always used as 뽀대(가) 난다 (it looks sharp) to mean cool; 뽀대작살 for seriously cool. It covered not just clothes but cars, bags, posture — anything visible.", "es": "La pinta imponente que desprende algo o alguien. Casi siempre como 뽀대(가) 난다 (tiene pinta) con el sentido de molar; 뽀대작살 para algo que mola muchísimo. Servía no solo para la ropa, sino para coches, bolsos, la postura — cualquier cosa visible.", "ja": "人や物から感じられる格好いい見た目。ほぼ必ず「뽀대(가) 난다(決まってる)」の形で「かっこいい」を意味した。すごくかっこいいときは「뽀대작살」。服装だけでなく車・カバン・立ち姿など外見全般に使えた。", "vi": "Vẻ ngoài bắt mắt toát ra từ người hay đồ vật. Hầu như luôn dùng dạng 뽀대(가) 난다 (trông ngầu ghê) với nghĩa là chất; 뽀대작살 khi cực chất. Dùng được cho cả quần áo, xe, túi, dáng đứng — mọi thứ nhìn thấy được."}}]'::jsonb, '맵시나 모양새를 뜻하는 「본때」가 변해 생긴 말로 설명된다. 2000년대 중반에는 십대 은어를 다룬 신문 기사에 예시로 실릴 만큼 널리 퍼져 있었고, 인터넷 문화를 타고 한 시대를 풍미했다.', '{"de": "Meist als abgeschliffene Form von 본때 (Haltung, Zuschnitt) erklärt. Mitte der 2000er war es verbreitet genug, um in Zeitungsartikeln über Jugendslang als Beispiel zu erscheinen, und wurde über die Internetkultur allgegenwärtig.", "en": "Generally explained as a worn-down form of 본때 (bearing, cut of a thing). By the mid-2000s it was common enough to be cited in newspaper pieces on teen slang, and it rode internet culture to real ubiquity.", "es": "Suele explicarse como una deformación de 본때 (porte, hechura). A mediados de los 2000 era tan común que la prensa la citaba en reportajes sobre jerga adolescente, y la cultura de internet la llevó a estar en todas partes.", "ja": "「本때(見栄え・格好)」が変化してできた語と説明される。2000年代半ばには十代の隠語を扱う新聞記事に例として載るほど広まり、ネット文化に乗って一時代を築いた。", "vi": "Thường được giải thích là biến thể của 본때 (dáng vẻ, phom). Đến giữa những năm 2000 nó phổ biến đến mức được báo chí dẫn làm ví dụ trong bài về tiếng lóng tuổi teen, rồi theo văn hóa internet mà thịnh hành một thời."}'::jsonb, '2010년대 들어 일본어에서 온 「간지」에 자리를 내주고 거의 사라졌다. 지금 쓰면 확실히 옛날 말투로 들리며, 40대 이상이나 복고 콘텐츠에서 주로 들린다. 뜻은 아직 다 통한다.', '{"de": "In den 2010ern verlor es gegen das aus dem Japanischen stammende 간지 und verschwand fast. Heute klingt es deutlich altmodisch — man hört es vor allem von Über-Vierzigjährigen oder in Retro-Content. Verstanden wird es weiterhin.", "en": "In the 2010s it lost ground to the Japanese-derived 간지 and all but disappeared. Saying it now sounds distinctly dated — you mostly hear it from people over forty or in retro content. Everyone still understands it.", "es": "En los 2010 cedió el terreno al 간지 de origen japonés y prácticamente desapareció. Hoy suena claramente anticuado: se oye sobre todo a mayores de cuarenta o en contenido retro. Se sigue entendiendo perfectamente.", "ja": "2010年代に日本語由来の「간지」に取って代わられ、ほぼ姿を消した。今使うと明らかに古い言い回しに聞こえ、40代以上やレトロなコンテンツで主に耳にする。意味は今も通じる。", "vi": "Sang thập niên 2010 nó nhường chỗ cho 간지 gốc tiếng Nhật và gần như biến mất. Dùng bây giờ nghe rõ là kiểu nói cũ, chủ yếu gặp ở người trên bốn mươi hoặc nội dung hoài cổ. Ai cũng vẫn hiểu."}'::jsonb, array['간지', '갓벽', '재질']::text[], array['뽀대나다', '뽀대작살']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Swagger / looking sharp"}, {"lang": "🇯🇵 JA", "text": "格好よさ、決まってる"}, {"lang": "🇨🇳 ZH", "text": "有型、拉风"}, {"lang": "🇻🇳 VI", "text": "Ngầu, có phong độ"}, {"lang": "🇪🇸 ES", "text": "Tener pinta, molar"}, {"lang": "🇩🇪 DE", "text": "Style, scharf aussehen"}]'::jsonb),
('562', '안구정화', 'An-Gu-Jeong-Hwa', 'outdated-slang', NULL, '보기만 해도 눈이 맑아지는 것 같은 좋은 볼거리', '{"de": "Etwas so Schönes, dass es die Augen reinigt", "en": "Something so nice to look at your eyes feel cleansed", "es": "Algo tan bonito de ver que te limpia los ojos", "ja": "見るだけで目が浄化されるような眼福", "vi": "Thứ đẹp đến mức nhìn vào là mắt được thanh lọc"}'::jsonb, '[안구정화]', '[{"type": "명사", "examples": [{"de": "Dieses Foto ist echt Balsam für die Augen.", "es": "Esta foto de verdad me limpia los ojos.", "ja": "この写真、マジで眼福すぎる", "vi": "Tấm ảnh này đúng là thanh lọc mắt thật.", "eng": "This photo is pure eye-bleach, honestly.", "kor": "이 사진 진짜 안구정화된다"}], "definition": "멋진 사람, 경치, 사진 따위를 보고 기분이 좋아지는 일. 눈(안구)이 깨끗하게 씻긴다는 과장된 비유로, 보기 괴로운 것을 봤을 때 쓰는 ''눈 버렸다''의 반대말처럼 쓰였다. 2000년대 후반에서 2010년대 초에 흔했고 지금 10~20대는 잘 쓰지 않는다.", "definition_i18n": {"de": "Das Vergnügen, etwas Schönes anzusehen — ein übertriebenes Bild von reingewaschenen Augäpfeln. Es funktionierte als Gegenteil von ''meine Augen sind ruiniert''. Verbreitet von den späten 2000ern bis Anfang der 2010er, von heutigen Jugendlichen kaum benutzt.", "en": "The pleasure of looking at a gorgeous person, view or photo — an exaggerated image of your eyeballs being washed clean. It worked as the opposite of ''my eyes are ruined''. Common from the late 2000s into the early 2010s, rarely used by today''s teens and twenty-somethings.", "es": "El placer de mirar a alguien guapo, un paisaje o una foto — una imagen exagerada de tener los ojos lavados. Funcionaba como lo contrario de ''se me han ensuciado los ojos''. Habitual entre finales de los 2000 y principios de los 2010; hoy apenas lo usan los jóvenes.", "ja": "素敵な人や景色、写真を見て気分がよくなること。眼球が洗い清められるという大げさな比喩で、見るに堪えないものを見たときの「目が汚れた」の反対語のように使われた。2000年代後半から2010年代初めによく使われ、今の10〜20代はあまり使わない。", "vi": "Cảm giác dễ chịu khi ngắm người đẹp, cảnh đẹp hay ảnh đẹp — hình ảnh phóng đại về việc nhãn cầu được rửa sạch. Nó là phản nghĩa của câu ''hỏng cả mắt''. Phổ biến cuối thập niên 2000 đến đầu 2010, nay giới trẻ ít dùng."}}]'::jsonb, '''안구(眼球)''에 ''정화(淨化)''를 붙여 만든 인터넷 조어로, 누가 언제 처음 썼는지는 확인되지 않았다. 비슷한 시기에 유행한 ''안습(안구에 습기)''과 함께 ''안구'' 계열 조어로 묶여 쓰였다.', '{"de": "Eine Internet-Wortschöpfung aus 안구 (Augapfel) und 정화 (Reinigung); wer sie wann prägte, ist unbekannt. Sie kursierte zusammen mit dem zeitgleichen 안습 (''Feuchtigkeit in den Augen'') als Teil derselben 안구-Familie.", "en": "An internet coinage joining 안구 (eyeball) and 정화 (purification); who coined it and when is unknown. It circulated alongside the contemporaneous 안습 (''moisture in the eyeballs'') as part of the same 안구 family of slang.", "es": "Un neologismo de internet que une 안구 (globo ocular) y 정화 (purificación); se desconoce quién lo acuñó y cuándo. Circuló junto a 안습 (''humedad en los ojos''), de la misma familia.", "ja": "「眼球」に「浄化」を付けて作られたネット造語で、誰がいつ最初に使ったかは不明。同時期に流行した「안습(眼球に湿気)」とともに「眼球」系の造語として使われた。", "vi": "Từ mạng ghép 안구 (nhãn cầu) với 정화 (thanh lọc); không rõ ai đặt ra và từ khi nào. Nó lưu hành cùng 안습 (''mắt ẩm'') cùng họ 안구."}'::jsonb, '잘생기거나 예쁜 사람, 예쁜 풍경 사진에 댓글로 달던 말. 지금은 같은 자리를 ''눈호강''이 대신하는 경우가 많다.', '{"de": "Wurde als Kommentar unter Fotos gutaussehender Menschen oder schöner Landschaften gepostet. Heute steht dort meist 눈호강.", "en": "Typically dropped as a comment under a photo of a good-looking person or a pretty landscape. These days 눈호강 usually fills that slot instead.", "es": "Se dejaba como comentario bajo la foto de alguien atractivo o de un paisaje bonito. Hoy suele ocupar ese lugar 눈호강.", "ja": "かっこいい人やきれいな人、風景写真へのコメントとして書かれた。今は同じ場面で「눈호강」が使われることが多い。", "vi": "Thường được bình luận dưới ảnh người đẹp trai xinh gái hay phong cảnh đẹp. Ngày nay chỗ đó thường là 눈호강."}'::jsonb, array['안습', '얼짱']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "A sight for sore eyes / eye candy"}, {"lang": "🇯🇵 JA", "text": "眼福・目の保養"}, {"lang": "🇨🇳 ZH", "text": "养眼"}, {"lang": "🇻🇳 VI", "text": "Thanh lọc mắt / mát mắt"}, {"lang": "🇪🇸 ES", "text": "Un placer para la vista"}, {"lang": "🇩🇪 DE", "text": "Augenweide"}]'::jsonb)
